-- =============================================================================
-- 500 — LE CAHIER D'EXERCICES DE 2DE (partie 2)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/2de/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 500 --niveau 2de --fichiers allemand.jumelles --suffixe 2 > supabase/contenu/500_exercices_2de_2.sql
--
-- 87 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   allemand.jumelles       87 exercices · 29 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('41d699ab-7ab2-5f49-8f3b-cf3dd9cc9818'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Une ville en travaux","competence":"comprendre-langue","situation":"Un journal local décrit tout ce qui se passe dans la ville cet été. Lis l’article et repère le passif.","documents":[{"id":"stadt","type":"texte","genre":"article","titre":"Bei uns wird gebaut","blocs":["In unserer Stadt wird viel gebaut. Das Schwimmbad wird renoviert. Im Sommer wurde die Brücke repariert. Die neue Schule ist schon gebaut worden."],"source":"Article écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux formes de « werden » au présent qui construisent un passif d’action.","aide":"Cherche l’auxiliaire werden conjugué à la 3e personne du singulier.","type":"zone","document":"stadt","multiple":true},{"enonce":"Que dit la phrase « Die neue Schule ist schon gebaut worden » ?","aide":"Au parfait du passif, on a « ist … worden » et le mot « schon ».","type":"choix","options":[{"id":"a","texte":"L’école neuve sera bientôt construite"},{"id":"b","texte":"L’école neuve a déjà été construite"},{"id":"c","texte":"L’école neuve n’a pas encore été construite"},{"id":"d","texte":"L’école neuve est en train d’être construite"}],"multiple":false},{"enonce":"Complète au prétérit passif : « La maison fut construite. »","aide":"Au prétérit, werden devient « wurde ».","type":"trous","segments":["Das Haus ",0," gebaut."],"banque":["ist","wurde","worden","wird"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3","m8"]},"explication":"**wird** (deux fois) est le présent de *werden* : *wird gebaut*, *wird renoviert*. *wurde* est au prétérit et *ist … worden* au parfait."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le parfait du passif (**ist gebaut worden**) dit que l’action est faite : l’école a déjà été construite."},{"cle":{"type":"trous","trous":[["wurde"]]},"affichage":"wurde","explication":"**Das Haus wurde gebaut.** Prétérit du passif : *wurde* + participe passé."}]$ex$::jsonb),
  ('41d699ab-7ab2-5f49-8f3b-cf3dd9cc9818'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Qui l’a fait ? Von ou durch","competence":"analyser-texte","situation":"Trois courtes nouvelles locales utilisent le passif. À chaque fois, une préposition introduit « celui qui fait » ou « ce par quoi ».","documents":[{"id":"meldungen","type":"texte","genre":"article","titre":"Drei Meldungen","blocs":["Das Märchen wurde von den Brüdern Grimm gesammelt.","Die Brücke wurde durch das Hochwasser zerstört.","Heute wird in der Aula getanzt."],"source":"Articles écrits pour l’exercice"}],"questions":[{"enonce":"Touche la préposition qui introduit une personne agissante : les frères Grimm.","aide":"C’est une préposition suivie du datif.","type":"zone","document":"meldungen","multiple":false},{"enonce":"Que signifie la troisième phrase « Heute wird in der Aula getanzt » ?","aide":"Il n’y a pas de complément d’objet, donc pas de sujet « réel ».","type":"choix","options":[{"id":"a","texte":"Aujourd’hui, on danse dans l’aula"},{"id":"b","texte":"Aujourd’hui, on va construire l’aula"},{"id":"c","texte":"Aujourd’hui, l’aula est dansée"},{"id":"d","texte":"Aujourd’hui, il a dansé dans l’aula"}],"multiple":false},{"enonce":"Touche la préposition qui introduit un moyen ou une cause naturelle : le Hochwasser, la crue.","aide":"C’est une préposition suivie de l’accusatif.","type":"zone","document":"meldungen","multiple":false},{"enonce":"Remets en ordre : « Le travail doit être fait aujourd’hui. » La phrase commence par Die Arbeit.","aide":"Le modal est conjugué, le passif passe à l’infinitif : participe + werden à la fin.","type":"ordre","items":[{"id":"a","texte":"werden"},{"id":"b","texte":"gemacht"},{"id":"c","texte":"muss"},{"id":"d","texte":"heute"},{"id":"e","texte":"Die Arbeit"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3"]},"explication":"**von** + datif introduit l’agent quand c’est une personne ou une force qui agit : *von den Brüdern Grimm*."},{"cle":{"type":"choix","ids":["a"]},"explication":"C’est un **passif impersonnel** : le verbe *tanzen* n’a pas de COD, et la phrase se traduit par « on danse »."},{"cle":{"type":"zone","ids":["m11"]},"explication":"**durch** + accusatif introduit un moyen, un intermédiaire ou un événement : *durch das Hochwasser*."},{"cle":{"type":"ordre","ids":["e","c","d","b","a"]},"explication":"**Die Arbeit muss heute gemacht werden.** Avec un modal, le passif est à l’infinitif : *gemacht werden*, tout à la fin."}]$ex$::jsonb),
  ('41d699ab-7ab2-5f49-8f3b-cf3dd9cc9818'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"La rue fermée : action ou résultat ?","competence":"raisonner","situation":"Anna et Jonas croisent une rue fermée pour travaux. Leur conversation oppose ce qui se passe et ce qui est acquis.","documents":[{"id":"strasse","type":"dialogue","modele":"sms","titre":"Gesperrte Straße","participants":[{"nom":"Anna","emoji":"👧","cote":"gauche"},{"nom":"Jonas","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Anna","texte":"Warum ist die Straße gesperrt?"},{"qui":"Jonas","texte":"Sie wird gerade repariert."},{"qui":"Anna","texte":"Und wann ist das fertig?"},{"qui":"Jonas","texte":"Morgen. Dann ist sie wieder geöffnet. Gestern wurde sie noch von der Stadt geprüft."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les deux participes qui décrivent un résultat acquis (passif d’état, avec « ist »).","aide":"Le passif d’état se construit avec sein + participe : cherche « ist … ».","type":"zone","document":"strasse","multiple":true},{"enonce":"Range chaque phrase selon qu’elle décrit une action en cours ou un résultat acquis.","aide":"Werden + participe : action. Sein + participe : résultat.","type":"categories","categories":[{"id":"c0","texte":"Passif d’action (le film)"},{"id":"c1","texte":"Passif d’état (la photo)"}],"items":[{"id":"i0","texte":"Die Tür ist geöffnet."},{"id":"i1","texte":"Die Straße wird repariert."},{"id":"i2","texte":"Das Haus ist gebaut."},{"id":"i3","texte":"Das Haus wird gebaut."}]},{"enonce":"Complète au parfait du passif : « La rue a déjà été réparée. »","aide":"Au parfait du passif, le participe de werden perd son ge-.","type":"trous","segments":["Die Straße ist schon repariert ",0,"."],"banque":["worden","werden","wurde","geworden"]},{"enonce":"Mets « Man repariert die Straße » au passif présent.","aide":"Le COD devient sujet ; werden est conjugué, le participe est à la fin.","type":"ordre","items":[{"id":"a","texte":"wird"},{"id":"b","texte":"repariert"},{"id":"c","texte":"Die Straße"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4","m19"]},"explication":"**gesperrt** et **geöffnet** suivent « ist » : ils décrivent un état. À l’inverse, *wird repariert* décrit une action en cours."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0"}},"explication":"**werden + participe** montre l’action en train de se faire ; **sein + participe** montre le résultat, comme une photographie."},{"cle":{"type":"trous","trous":[["worden"]]},"affichage":"worden","explication":"**Die Straße ist schon repariert worden.** Au passif, le participe de *werden* est *worden* (et non *geworden*, réservé à « devenir »)."},{"cle":{"type":"ordre","ids":["c","a","b"]},"explication":"**Die Straße wird repariert.** Le complément d’objet du tour actif (*die Straße*) devient le sujet du passif."}]$ex$::jsonb),
  ('032feacc-974b-505b-a485-923ed367cc33'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Au café","competence":"comprendre-langue","situation":"Dans un café de Vienne, un client commande avec politesse. Observe les formes qui adoucissent la demande.","documents":[{"id":"cafe","type":"dialogue","modele":"sms","titre":"Im Café","participants":[{"nom":"Kellnerin","emoji":"👩","cote":"gauche"},{"nom":"Gast","emoji":"🧑","cote":"droite"}],"repliques":[{"qui":"Kellnerin","texte":"Guten Tag! Was möchten Sie?"},{"qui":"Gast","texte":"Ich hätte gern einen Tee. Könnten Sie mir auch ein Wasser bringen?"},{"qui":"Kellnerin","texte":"Natürlich. Würden Sie lieber drinnen sitzen?"}],"source":"Dialogue écrit pour l’exercice"}],"questions":[{"enonce":"Touche les quatre formes de politesse (subjonctif II).","aide":"Ce sont möchten, hätte, Könnten et Würden.","type":"zone","document":"cafe","multiple":true},{"enonce":"Pourquoi dit-on « Ich hätte gern einen Tee » plutôt que « Ich will einen Tee » ?","aide":"Pense à l’effet produit sur le serveur.","type":"choix","options":[{"id":"a","texte":"Parce que l’infinitif doit venir en première position"},{"id":"b","texte":"Il rend la demande polie : le présent ferait un ordre brusque"},{"id":"c","texte":"Parce que hätte est le prétérit de haben et parle du passé"},{"id":"d","texte":"Parce que gern est obligatoire avec le verbe haben"}],"multiple":false},{"enonce":"Associe chaque verbe à son subjonctif II simple.","aide":"On part du prétérit et on ajoute une inflexion.","type":"association","gauche":[{"id":"g0","texte":"sein"},{"id":"g1","texte":"haben"},{"id":"g2","texte":"können"},{"id":"g3","texte":"werden"}],"droite":[{"id":"d0","texte":"hätte"},{"id":"d1","texte":"wäre"},{"id":"d2","texte":"würde"},{"id":"d3","texte":"könnte"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3","m6","m10","m18"]},"explication":"**möchten, hätte, Könnten, Würden** : le subjonctif II adoucit la phrase et la rend polie."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le **subjonctif II** est l’outil de la politesse : *Ich hätte gern…* sonne comme une demande, *Ich will…* comme un ordre."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g3":"d2","g2":"d3"}},"explication":"**wäre, hätte, könnte, würde** : formes simples fréquentes, construites sur le prétérit avec inflexion."}]$ex$::jsonb),
  ('032feacc-974b-505b-a485-923ed367cc33'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Si j’étais riche","competence":"manier-langue","situation":"Dans sa lettre, Jonas rêve d’une vie au bord de la mer. Pour rêver, l’allemand utilise le subjonctif II.","documents":[{"id":"traum","type":"texte","genre":"lettre","titre":"Mein Traum","blocs":["Wenn ich reich wäre, würde ich ein Haus am Meer kaufen. Hätte ich dort ein Boot, würde ich jeden Tag segeln. Aber ich habe nur wenig Geld, deshalb arbeite ich im Sommer."],"source":"Lettre écrite pour l’exercice"}],"questions":[{"enonce":"Touche les deux formes simples du subjonctif II.","aide":"Ce sont des formes de sein et de haben.","type":"zone","document":"traum","multiple":true},{"enonce":"Complète : « Si nous avions plus de temps, nous resterions plus longtemps. »","aide":"Hypothèse : subjonctif II de haben, puis würde + infinitif.","type":"trous","segments":["Wenn wir mehr Zeit ",0,", ",1," wir länger bleiben."],"banque":["hatten","würden","hätten","wären"]},{"enonce":"Remets en ordre, sans « wenn » : « S’il était ici, il aiderait. » La phrase commence par Wäre.","aide":"Sans wenn, le verbe prend la première place ; l’infinitif de la principale est à la fin.","type":"ordre","items":[{"id":"a","texte":"er hier"},{"id":"b","texte":"helfen"},{"id":"c","texte":"Wäre"},{"id":"d","texte":"würde"},{"id":"e","texte":"er"}]},{"enonce":"Associe chaque phrase à son emploi.","aide":"Souhait, conseil, politesse, irréel : les trois emplois et un tour sans wenn.","type":"association","gauche":[{"id":"g0","texte":"Wenn er nur hier wäre!"},{"id":"g1","texte":"Du solltest mehr schlafen"},{"id":"g2","texte":"Könnten Sie mir helfen?"},{"id":"g3","texte":"Hätte ich Zeit, würde ich kommen"}],"droite":[{"id":"d0","texte":"une demande polie"},{"id":"d1","texte":"une hypothèse irréelle"},{"id":"d2","texte":"un souhait"},{"id":"d3","texte":"un conseil"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3","m11"]},"explication":"**wäre** (*sein*) et **Hätte** (*haben*) sont les formes simples. Dans « Hätte ich… », *wenn* a disparu."},{"cle":{"type":"trous","trous":[["hatten"],["wurden"]]},"affichage":"hätten · würden","explication":"**Wenn wir mehr Zeit hätten, würden wir länger bleiben.** *hätten* (forme simple) + *würden* + infinitif."},{"cle":{"type":"ordre","ids":["c","a","d","e","b"]},"explication":"**Wäre er hier, würde er helfen.** Sans *wenn*, le verbe est en première position."},{"cle":{"type":"association","paires":{"g2":"d0","g3":"d1","g0":"d2","g1":"d3"}},"explication":"*wenn nur…* = souhait ; *solltest* = conseil ; *Könnten Sie…* = politesse ; *Hätte ich…, würde ich…* = hypothèse irréelle."}]$ex$::jsonb),
  ('032feacc-974b-505b-a485-923ed367cc33'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Un entraîneur et un caprice de glace","competence":"raisonner","situation":"Dans la presse locale, un entraîneur parle de son équipe. Plus loin, un enfant apprend à demander poliment. Deux documents, plusieurs subjonctifs.","documents":[{"id":"presse","type":"texte","genre":"article","titre":"Der Trainer spricht","blocs":["Der Trainer sagte, er sei zufrieden. Er tut aber so, als ob er alles wüsste. Die Spieler wären lieber im Urlaub."],"source":"Article écrit pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Ein Eis","participants":[{"nom":"Ben","emoji":"👦","cote":"gauche"},{"nom":"Mama","emoji":"👩","cote":"droite"}],"repliques":[{"qui":"Ben","texte":"Ich will ein Eis."},{"qui":"Mama","texte":"Wie bitte? Sag das noch einmal höflich."},{"qui":"Ben","texte":"Ich möchte bitte ein Eis. Könntest du mir Geld geben?"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le subjonctif I qui rapporte les paroles de l’entraîneur.","aide":"Il apparaît après « sagte » et se traduit par « il est ».","type":"zone","document":"presse","multiple":false},{"enonce":"Touche le verbe au subjonctif II après « als ob ».","aide":"C’est le verbe qui suit « alles ».","type":"zone","document":"presse","multiple":false},{"enonce":"Touche la forme de « sein » qui dit ce que les joueurs préféreraient.","aide":"Elle s’écrit avec ä.","type":"zone","document":"presse","multiple":false},{"enonce":"Pourquoi la mère de Ben réagit-elle à « Ich will ein Eis » ?","aide":"Compare avec la phrase polie de Ben, plus bas.","type":"choix","options":[{"id":"a","texte":"Parce que Ben aurait dû employer l’impératif"},{"id":"b","texte":"Parce que ein Eis exige un verbe au prétérit"},{"id":"c","texte":"Parce que will est un verbe faible mal conjugué"},{"id":"d","texte":"Le présent sonne comme un ordre brusque"}],"multiple":false},{"enonce":"Remets en ordre : « Pourriez-vous m’aider ? »","aide":"Question : le verbe conjugué ouvre la phrase ; l’infinitif part à la fin.","type":"ordre","items":[{"id":"a","texte":"Sie"},{"id":"b","texte":"mir"},{"id":"c","texte":"helfen"},{"id":"d","texte":"Könnten"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4"]},"explication":"**sei** : subjonctif I de *sein*, typique du discours indirect de la presse. Il suffit de le reconnaître."},{"cle":{"type":"zone","ids":["m14"]},"explication":"**wüsste** : après *als ob*, le subjonctif II est de règle (*wissen* → *wüsste*)."},{"cle":{"type":"zone","ids":["m17"]},"explication":"**wären** : subjonctif II de *sein* ; il exprime ce qui n’est pas réel (« seraient plutôt en vacances »)."},{"cle":{"type":"choix","ids":["d"]},"explication":"*Ich will…* sonne comme un ordre ; **Ich möchte bitte…** et **Könntest du…?** (subjonctif II) rendent la demande acceptable."},{"cle":{"type":"ordre","ids":["d","a","b","c"]},"explication":"**Könnten Sie mir helfen?** Subjonctif II de *können*, très poli, en première place pour une question."}]$ex$::jsonb),
  ('d591234c-8ff1-580f-8fe7-bdc1d4fe344f'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un café sans café","competence":"comprendre-langue","situation":"Emre est assis à la terrasse d’un café. Il refuse presque tout ce que la serveuse lui propose.","documents":[{"id":"cafe","type":"dialogue","modele":"sms","titre":"Im Café","participants":[{"nom":"Kellnerin","emoji":"☕","cote":"gauche"},{"nom":"Emre","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Kellnerin","texte":"Guten Tag! Möchten Sie einen Kaffee?"},{"qui":"Emre","texte":"Nein, danke. Ich trinke keinen Kaffee."},{"qui":"Kellnerin","texte":"Und etwas zu essen? Wir haben Kuchen und Kekse."},{"qui":"Emre","texte":"Ich esse keinen Kuchen und keine Kekse."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les trois formes de « kein » dans les réponses d’Emre.","aide":"Cherche les mots qui commencent par « kein-».","type":"zone","document":"cafe","multiple":true},{"enonce":"Pourquoi Emre dit-il « keinen Kaffee » et non « nicht Kaffee » ?","aide":"Le nom « Kaffee » est employé sans article.","type":"choix","options":[{"id":"a","texte":"Kaffee est un mot étranger, donc invariable"},{"id":"b","texte":"Nicht ne peut jamais se placer après un verbe"},{"id":"c","texte":"Le nom n’a pas d’article défini : on nie par kein"},{"id":"d","texte":"Le verbe trinken exige toujours la forme kein"}],"multiple":false},{"enonce":"Complète pour dire : « Je n’ai pas de voiture et pas de sœur. »","aide":"Auto est neutre ; Schwester est féminin.","type":"trous","segments":["Ich habe ",0," Auto und ",1," Schwester."],"banque":["keinen","kein","nicht","keine"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m10","m23","m26"]},"explication":"**keinen, keinen, keine** : *kein* se décline comme *ein*, et prend la terminaison selon le genre et le cas du nom."},{"cle":{"type":"choix","ids":["c"]},"explication":"Devant un nom précédé de *ein* ou **sans article**, on nie avec **kein** : *Ich trinke keinen Kaffee.*"},{"cle":{"type":"trous","trous":[["kein"],["keine"]]},"affichage":"kein · keine","explication":"**Ich habe kein Auto und keine Schwester.** *kein* devant un neutre (*das Auto*), *keine* devant un féminin (*die Schwester*)."}]$ex$::jsonb),
  ('d591234c-8ff1-580f-8fe7-bdc1d4fe344f'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les phrases négatives de Zoé","competence":"manier-langue","situation":"Zoé s’entraîne à placer « nicht » dans ses phrases. Observe où il se trouve selon ce qu’elle nie.","documents":[{"id":"nicht","type":"tableau","titre":"Fünf negative Sätze","colonnes":["Satz"],"lignes":[["Ich habe ihn gestern nicht gesehen."],["Ich gehe nicht ins Kino."],["Ich lese das Buch nicht."],["Das Buch ist nicht interessant."],["Ich fahre nicht morgen, sondern heute."]],"enteteLignes":false,"source":"Phrases écrites pour l’exercice"}],"questions":[{"enonce":"Touche la phrase où « nicht » est le dernier mot, parce que le complément d’objet direct est défini.","aide":"Cherche la phrase qui se termine par « nicht ».","type":"zone","document":"nicht","multiple":false},{"enonce":"Touche la phrase où « nicht » ne nie qu’un seul mot et se place devant lui.","aide":"Cherche la phrase qui rectifie : « pas demain, mais aujourd’hui ».","type":"zone","document":"nicht","multiple":false},{"enonce":"Remets en ordre pour nier toute la phrase « Ich habe das Buch gelesen ». La phrase commence par « Ich habe ».","aide":"Quand on nie toute la phrase, nicht se place devant le second morceau du verbe.","type":"ordre","items":[{"id":"a","texte":"nicht"},{"id":"b","texte":"das Buch"},{"id":"c","texte":"gelesen"}]},{"enonce":"Dans « Das Buch ist nicht interessant », pourquoi « nicht » est-il devant « interessant » ?","aide":"Interessant décrit le livre après le verbe sein.","type":"choix","options":[{"id":"a","texte":"Il nie un COD défini : il se place après lui"},{"id":"b","texte":"Il nie un verbe seul : il va avant le sujet"},{"id":"c","texte":"Il nie un attribut : il se place devant lui"},{"id":"d","texte":"Il nie un lieu avec mouvement : il va à la fin"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c0"]},"explication":"**Ich lese das Buch nicht.** : le COD *das Buch* est défini, *nicht* se place après lui, tout à droite."},{"cle":{"type":"zone","ids":["r4c0"]},"explication":"**Ich fahre nicht morgen, sondern heute.** : *nicht* nie seulement *morgen*, et *sondern* rectifie."},{"cle":{"type":"ordre","ids":["b","a","c"]},"explication":"**Ich habe das Buch nicht gelesen.** *nicht* se place le plus à droite possible, juste devant le participe qui ferme la phrase."},{"cle":{"type":"choix","ids":["c"]},"explication":"**nicht** se place devant l’attribut : *Das Buch ist nicht interessant.*"}]$ex$::jsonb),
  ('d591234c-8ff1-580f-8fe7-bdc1d4fe344f'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Pourquoi Jan ne joue plus","competence":"analyser-document","situation":"Marie s’inquiète : Jan ne vient plus au training. Lis leur conversation et observe leurs mots de négation.","documents":[{"id":"training2","type":"dialogue","modele":"sms","titre":"Training","participants":[{"nom":"Marie","emoji":"👧","cote":"gauche"},{"nom":"Jan","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Marie","texte":"Kommst du heute zum Training?"},{"qui":"Jan","texte":"Nein, ich habe keine Zeit und ich bin nicht fit."},{"qui":"Marie","texte":"Du kommst nie! Ist das Problem das Wetter?"},{"qui":"Jan","texte":"Nicht das Wetter, sondern mein Knie. Ich spiele nicht mehr Fußball."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui nie le nom « Zeit » dans la première réponse de Jan.","aide":"Il se décline comme « ein » : cherche un mot de forme « kein- ».","type":"zone","document":"training2","multiple":false},{"enonce":"Associe chaque mot négatif à son sens.","aide":"Chaque mot négatif exprime un seul sens : un temps, une personne, un lieu…","type":"association","gauche":[{"id":"g0","texte":"nie"},{"id":"g1","texte":"niemand"},{"id":"g2","texte":"nirgends"},{"id":"g3","texte":"noch nicht"}],"droite":[{"id":"d0","texte":"pas encore"},{"id":"d1","texte":"personne"},{"id":"d2","texte":"nulle part"},{"id":"d3","texte":"jamais"}]},{"enonce":"Que signifie la phrase de Jan « Ich spiele nicht mehr Fußball » ?","aide":"Pense au sens de « mehr » dans « nicht mehr ».","type":"choix","options":[{"id":"a","texte":"Je ne joue pas encore au football"},{"id":"b","texte":"Je ne joue plus au football"},{"id":"c","texte":"Je joue plus de football qu’avant"},{"id":"d","texte":"Je ne joue jamais au football"}],"multiple":false},{"enonce":"Complète pour dire : « Je n’ai rien vu. »","aide":"Une seule négation suffit en allemand.","type":"trous","segments":["Ich habe ",0," gesehen."],"banque":["nicht","nie","nichts","niemand"]},{"enonce":"Pourquoi Jan emploie-t-il « sondern » dans « Nicht das Wetter, sondern mein Knie » ?","aide":"Jan nie « le temps » avant de dire quel est le vrai problème.","type":"choix","options":[{"id":"a","texte":"Il explique pourquoi il ne vient pas"},{"id":"b","texte":"Il remplace aber dans toutes les phrases"},{"id":"c","texte":"Il oppose deux idées sans rien corriger"},{"id":"d","texte":"Il rectifie une erreur après une négation"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8"]},"explication":"**keine** nie *Zeit* (nom féminin sans article) : *ich habe keine Zeit*."},{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g2":"d2","g0":"d3"}},"explication":"**nie** = jamais, **niemand** = personne, **nirgends** = nulle part, **noch nicht** = pas encore."},{"cle":{"type":"choix","ids":["b"]},"explication":"**nicht mehr** = « ne… plus » : Jan jouait avant, mais ne joue plus."},{"cle":{"type":"trous","trous":[["nichts"]]},"affichage":"nichts","explication":"**Ich habe nichts gesehen.** Deux négations ne s’additionnent pas : on n’écrit jamais « nicht nichts »."},{"cle":{"type":"choix","ids":["d"]},"explication":"**sondern** rectifie après une négation (*nicht A, sondern B*), alors qu’**aber** oppose simplement."}]$ex$::jsonb),
  ('05fe13dd-c7ff-56ce-9148-dfbe2b9e7ac9'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le matin de Leo","competence":"comprendre-langue","situation":"Leo raconte sa matinée. Dans son récit, quatre petits mots sont partis à la fin de leur phrase : les préverbes séparables.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"Ein Morgen","blocs":["Leo steht um sieben Uhr auf. Er isst ein Brot und ruft Tom an. Dann geht er mit Tom zum Bus. Um acht Uhr kommt er in der Schule an. Mittags kauft er in der Pause ein."],"source":"Récit écrit pour l’exercice"}],"questions":[{"enonce":"Touche les quatre préverbes séparés qui ferment leur phrase.","aide":"Ils sont tout seuls à la fin : ils étaient collés au verbe à l’infinitif.","type":"zone","document":"recit","multiple":true},{"enonce":"Associe chaque verbe de Leo à son sens.","aide":"Reconstitue le verbe : préverbe + radical.","type":"association","gauche":[{"id":"g0","texte":"aufstehen"},{"id":"g1","texte":"anrufen"},{"id":"g2","texte":"ankommen"},{"id":"g3","texte":"einkaufen"}],"droite":[{"id":"d0","texte":"faire les courses"},{"id":"d1","texte":"arriver"},{"id":"d2","texte":"se lever"},{"id":"d3","texte":"téléphoner à"}]},{"enonce":"Remets en ordre : « Il se lève à sept heures. » La phrase commence par Er.","aide":"Le verbe est en 2e position, le préverbe tout à la fin.","type":"ordre","items":[{"id":"a","texte":"Er"},{"id":"b","texte":"auf"},{"id":"c","texte":"steht"},{"id":"d","texte":"um sieben Uhr"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5","m13","m29","m36"]},"explication":"**auf, an, an, ein** : dans une principale, le préverbe quitte le verbe et va en fin de phrase."},{"cle":{"type":"association","paires":{"g3":"d0","g2":"d1","g0":"d2","g1":"d3"}},"explication":"**aufstehen** (se lever), **anrufen** (appeler), **ankommen** (arriver), **einkaufen** (faire les courses)."},{"cle":{"type":"ordre","ids":["a","c","d","b"]},"explication":"**Er steht um sieben Uhr auf.** Le verbe conjugué est en 2e position, le préverbe ferme la phrase."}]$ex$::jsonb),
  ('05fe13dd-c7ff-56ce-9148-dfbe2b9e7ac9'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Un week-end en famille","competence":"manier-langue","situation":"Tom raconte son week-end à Lea. Au parfait, certains participes ont un ge- au milieu, d’autres n’en ont pas du tout.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Das Wochenende","participants":[{"nom":"Lea","emoji":"👧","cote":"gauche"},{"nom":"Tom","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lea","texte":"Was hast du am Wochenende gemacht?"},{"qui":"Tom","texte":"Ich habe Fußball gespielt und meine Großeltern besucht. Ich habe auch ein neues Gericht probiert."},{"qui":"Lea","texte":"Hast du etwas mitgebracht?"},{"qui":"Tom","texte":"Ja, Kuchen. Und ich bin früh eingeschlafen."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les deux participes qui n’ont pas de ge-.","aide":"L’un commence par un préverbe inséparable (be-), l’autre vient d’un verbe en -ieren.","type":"zone","document":"sms","multiple":true},{"enonce":"Touche les deux participes où le ge- s’est glissé entre le préverbe et le radical.","aide":"Ce sont des verbes séparables : mit- et ein-.","type":"zone","document":"sms","multiple":true},{"enonce":"Écris les participes II.","aide":"Séparable : ge- au milieu. En -ieren et inséparable : pas de ge-.","type":"trous","segments":["aufräumen → ",0," · kopieren → ",1," · vergessen → ",2]},{"enonce":"Pourquoi Tom dit-il « Ich bin früh eingeschlafen » avec « bin » ?","aide":"Passer de l’éveil au sommeil, c’est changer d’état.","type":"choix","options":[{"id":"a","texte":"einschlafen exprime un changement d’état"},{"id":"b","texte":"Tous les verbes séparables prennent sein"},{"id":"c","texte":"ein- est un préverbe inséparable"},{"id":"d","texte":"Tom parle de lui-même"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m13","m20"]},"explication":"**besucht** (préverbe inséparable *be-*) et **probiert** (verbe en *-ieren*) n’ont pas de ge-."},{"cle":{"type":"zone","ids":["m24","m31"]},"explication":"**mitgebracht** et **eingeschlafen** : le ge- s’intercale entre le préverbe séparable et le radical."},{"cle":{"type":"trous","trous":[["aufgeraumt"],["kopiert"],["vergessen"]]},"affichage":"aufgeräumt · kopiert · vergessen","explication":"**aufgeräumt** (ge- intercalé), **kopiert** (-ieren, sans ge-), **vergessen** (préverbe ver- inséparable, sans ge-)."},{"cle":{"type":"choix","ids":["a"]},"explication":"**einschlafen** exprime un changement d’état : au parfait, il prend **sein**."}]$ex$::jsonb),
  ('05fe13dd-c7ff-56ce-9148-dfbe2b9e7ac9'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Je t’appelle quand tu arrives","competence":"raisonner","situation":"Eva et Ben s’organisent par SMS. Plusieurs verbes y sont séparables, un autre refuse de se séparer, et l’un d’eux se recolle dans une subordonnée.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Pläne","participants":[{"nom":"Ben","emoji":"👦","cote":"gauche"},{"nom":"Eva","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Ben","texte":"Kommst du heute mit?"},{"qui":"Eva","texte":"Ich rufe dich an, wenn mein Zug ankommt."},{"qui":"Ben","texte":"Okay. Ich habe dein Paket bekommen."},{"qui":"Eva","texte":"Super! Ich hole es morgen ab."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les trois préverbes détachés, tout seuls à la fin de leur phrase.","aide":"Ils sont séparés de leur verbe : mitkommen, anrufen, abholen.","type":"zone","document":"sms","multiple":true},{"enonce":"Touche le verbe qui s’est « recollé » parce qu’il est dans une subordonnée.","aide":"Il est après « wenn » et son préverbe est revenu devant lui.","type":"zone","document":"sms","multiple":false},{"enonce":"Touche le participe qui n’a pas de ge- parce que son préverbe est inséparable.","aide":"Il commence par be-.","type":"zone","document":"sms","multiple":false},{"enonce":"Remets en ordre : « Je t’appelle quand il arrive. » La phrase commence par Ich.","aide":"La principale se termine par le préverbe ; la subordonnée recolle le verbe à la fin.","type":"ordre","items":[{"id":"a","texte":"dich"},{"id":"b","texte":"an"},{"id":"c","texte":"rufe"},{"id":"d","texte":"Ich"},{"id":"e","texte":"er"},{"id":"f","texte":"ankommt"},{"id":"g","texte":"wenn"}]},{"enonce":"Complète avec zu : « Je n’ai pas envie de me lever tôt, ni le temps de rendre visite à Oma. »","aide":"Séparable : zu s’intercale. Inséparable : zu reste devant.","type":"trous","segments":["Ich habe keine Lust, früh ",0," (aufstehen), und keine Zeit, Oma ",1," (besuchen)."]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3","m7","m23"]},"explication":"**mit, an, ab** : dans une principale, le préverbe séparable va à la fin."},{"cle":{"type":"zone","ids":["m11"]},"explication":"**ankommt** : en subordonnée, le verbe conjugué part à la fin et rejoint son préverbe."},{"cle":{"type":"zone","ids":["m17"]},"explication":"**bekommen** : *be-* est inséparable, donc pas de *ge-* (et le verbe veut dire « recevoir »)."},{"cle":{"type":"ordre","ids":["d","c","a","b","g","e","f"]},"explication":"**Ich rufe dich an, wenn er ankommt.** Principale : préverbe séparé à la fin ; subordonnée : *ankommt* recollé et en dernière position."},{"cle":{"type":"trous","trous":[["aufzustehen"],["zu besuchen"]]},"affichage":"aufzustehen · zu besuchen","explication":"**aufzustehen** (le *zu* s’intercale) et **zu besuchen** (*be-* est inséparable : *zu* reste devant)."}]$ex$::jsonb),
  ('0d0877d7-b03e-592f-8ec5-29b4b4d2cfc1'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les vacances approchent","competence":"comprendre-langue","situation":"Lina et Tom discutent des vacances. Dans leurs messages, on retrouve le pronom réfléchi : mich, dich, sich…","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Ferien","participants":[{"nom":"Lina","emoji":"👧","cote":"gauche"},{"nom":"Tom","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lina","texte":"Ich freue mich auf die Ferien!"},{"qui":"Tom","texte":"Ich auch! Ich interessiere mich für Sport. Und du?"},{"qui":"Lina","texte":"Ich wasche mich schnell, dann kommen wir."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les trois pronoms réfléchis de la 1re personne.","aide":"Ils sont juste après le verbe : freue, interessiere, wasche.","type":"zone","document":"sms","multiple":true},{"enonce":"Touche la préposition qui accompagne « sich freuen » pour se réjouir de ce qui vient.","aide":"Elle est suivie de l’accusatif et parle de l’avenir.","type":"zone","document":"sms","multiple":false},{"enonce":"Complète : « Nous nous agaçons du mauvais temps. »","aide":"Sich ärgern se construit avec une préposition suivie de l’accusatif.","type":"trous","segments":["Wir ärgern uns ",0," das schlechte Wetter."],"banque":["für","auf","an","über"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m2","m10","m17"]},"explication":"**mich** apparaît trois fois : accusatif du réfléchi à la 1re personne du singulier."},{"cle":{"type":"zone","ids":["m3"]},"explication":"**sich freuen auf** + accusatif : se réjouir d’un événement à venir."},{"cle":{"type":"trous","trous":[["uber"]]},"affichage":"über","explication":"**Wir ärgern uns über das schlechte Wetter.** *sich ärgern über* + accusatif."}]$ex$::jsonb),
  ('0d0877d7-b03e-592f-8ec5-29b4b4d2cfc1'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Mich ou mir ?","competence":"manier-langue","situation":"Après le sport, une élève raconte sa soirée. Selon la phrase, le pronom réfléchi est à l’accusatif ou au datif.","documents":[{"id":"journal","type":"texte","genre":"recit","titre":"Nach dem Sport","blocs":["Nach dem Sport wasche ich mich. Dann putze ich mir die Zähne und kaufe mir ein Eis. Ich sehe mir einen Film an, und ich freue mich auf das Wochenende."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les trois pronoms réfléchis au datif.","aide":"Ils s’écrivent mir et apparaissent quand la phrase a déjà un COD.","type":"zone","document":"journal","multiple":true},{"enonce":"Touche les deux pronoms réfléchis à l’accusatif.","aide":"Ils s’écrivent mich et il n’y a pas de COD dans leur phrase.","type":"zone","document":"journal","multiple":true},{"enonce":"Pourquoi dit-on « Ich kaufe mir ein Eis » et non « Ich kaufe mich ein Eis » ?","aide":"Cherche le COD dans la phrase.","type":"choix","options":[{"id":"a","texte":"mir est la forme de politesse"},{"id":"b","texte":"ein Eis est un complément de temps"},{"id":"c","texte":"kaufen est un verbe pronominal à l’accusatif"},{"id":"d","texte":"La phrase contient déjà un COD : ein Eis"}],"multiple":false},{"enonce":"Complète avec le bon pronom.","aide":"À la 3e personne, le datif et l’accusatif sont identiques.","type":"trous","segments":["Max kauft ",0," ein Buch, und wir freuen ",1," auf Samstag."],"banque":["uns","dir","sich","euch","dich"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m9","m14","m19"]},"explication":"**mir** (3 fois) : au datif, parce que *die Zähne*, *ein Eis* et *einen Film* sont déjà des COD."},{"cle":{"type":"zone","ids":["m5","m26"]},"explication":"**mich** (2 fois) : à l’accusatif, car ni *wasche* ni *freue … auf* n’ont de COD."},{"cle":{"type":"choix","ids":["d"]},"explication":"Dès qu’il y a un COD (*ein Eis*), le réfléchi passe au **datif** : *mir*."},{"cle":{"type":"trous","trous":[["sich"],["uns"]]},"affichage":"sich · uns","explication":"**Max kauft sich ein Buch, und wir freuen uns auf Samstag.** *sich* (3e personne, datif) et *uns* (1re personne du pluriel)."}]$ex$::jsonb),
  ('0d0877d7-b03e-592f-8ec5-29b4b4d2cfc1'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une lettre pour Oma","competence":"argumenter","situation":"Une élève écrit à sa grand-mère. Elle se réjouit, s’agace, s’intéresse… et chaque verbe pronominal a sa préposition.","documents":[{"id":"brief","type":"texte","genre":"lettre","titre":"Liebe Oma","blocs":["Liebe Oma, ich freue mich sehr auf deinen Besuch im Sommer. Mein Bruder hat sich leider verspätet, deshalb ärgere ich mich über ihn. Interessierst du dich noch für Gartenarbeit? Erinnerst du dich an Opas Geburtstag? Ich möchte mir ein neues Fahrrad kaufen."],"source":"Lettre écrite pour l’exercice"}],"questions":[{"enonce":"Touche le pronom réfléchi de la 3e personne (« mon frère s’est… »).","aide":"Il s’écrit avec un s et ne change pas entre accusatif et datif.","type":"zone","document":"brief","multiple":false},{"enonce":"Touche la préposition qui accompagne « freue mich » quand on attend la visite.","aide":"Elle parle de ce qui va venir.","type":"zone","document":"brief","multiple":false},{"enonce":"Associe chaque verbe pronominal à sa préposition.","aide":"Le sens (ce qui vient ou ce qui est arrivé) distingue les deux sich freuen.","type":"association","gauche":[{"id":"g0","texte":"sich freuen (ce qui vient)"},{"id":"g1","texte":"sich freuen (ce qui est arrivé)"},{"id":"g2","texte":"sich interessieren"},{"id":"g3","texte":"sich erinnern"}],"droite":[{"id":"d0","texte":"über"},{"id":"d1","texte":"für"},{"id":"d2","texte":"an"},{"id":"d3","texte":"auf"}]},{"enonce":"Range ces verbes : pronominal en allemand ou non ?","aide":"Aufstehen, heißen et spazieren gehen sont pronominaux en français seulement.","type":"categories","categories":[{"id":"c0","texte":"Pronominal en allemand"},{"id":"c1","texte":"Pas pronominal en allemand"}],"items":[{"id":"i0","texte":"sich interessieren"},{"id":"i1","texte":"heißen"},{"id":"i2","texte":"spazieren gehen"},{"id":"i3","texte":"sich freuen"},{"id":"i4","texte":"sich verspäten"},{"id":"i5","texte":"aufstehen"}]},{"enonce":"Remets en ordre : « Je souris parce que je me réjouis. » La phrase commence par Ich lächle.","aide":"En subordonnée, le pronom réfléchi suit le sujet, et le verbe est à la fin.","type":"ordre","items":[{"id":"a","texte":"freue"},{"id":"b","texte":"Ich lächle"},{"id":"c","texte":"ich"},{"id":"d","texte":"weil"},{"id":"e","texte":"mich"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m14"]},"explication":"**sich** est le réfléchi de la 3e personne du singulier : *Mein Bruder hat sich verspätet*."},{"cle":{"type":"zone","ids":["m6"]},"explication":"**sich freuen auf** : se réjouir de ce qui vient. Pour ce qui est arrivé, on dit *sich freuen über*."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"**auf** (ce qui vient), **über** (ce qui est arrivé), **für** (s’intéresser à), **an** (se souvenir de) : toutes avec l’accusatif."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0","i4":"c0","i5":"c1"}},"explication":"*aufstehen* (se lever), *heißen* (s’appeler) et *spazieren gehen* (se promener) n’ont **pas** de pronom en allemand ; *sich verspäten* en a un alors que le français dit « être en retard »."},{"cle":{"type":"ordre","ids":["b","d","c","e","a"]},"explication":"**Ich lächle, weil ich mich freue.** Dans la subordonnée, le réfléchi vient après le sujet et le verbe conjugué ferme la phrase."}]$ex$::jsonb),
  ('0a6938bf-8709-5ce1-a842-8502ea1b406b'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Une carte postale de Hambourg","competence":"comprendre-langue","situation":"Lukas écrit à sa mère depuis Hambourg. Il raconte sa journée avec le temps des lettres et des messages : le parfait.","documents":[{"id":"postkarte","type":"texte","genre":"lettre","titre":"Liebe Mama","blocs":["Liebe Mama, heute habe ich Hamburg gesehen. Wir sind mit dem Schiff gefahren, und ich habe viele Fotos gemacht. Am Abend sind wir ins Hotel gegangen. Bis bald!"],"source":"Carte postale écrite pour l’exercice"}],"questions":[{"enonce":"Touche les deux participes de verbes de déplacement : ils se conjuguent avec sein.","aide":"Ils sont précédés de « sind » : on va d’un point à un autre.","type":"zone","document":"postkarte","multiple":true},{"enonce":"Touche les deux participes qui se conjuguent avec haben.","aide":"Ils sont précédés de « habe ».","type":"zone","document":"postkarte","multiple":true},{"enonce":"Complète : « J’ai vu un film. »","aide":"Sehen n’exprime pas un déplacement.","type":"trous","segments":["Ich ",0," einen Film gesehen."],"banque":["hat","bin","ist","habe"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m12","m25"]},"explication":"**gefahren** et **gegangen** : verbes de déplacement, donc *sind … gefahren*, *sind … gegangen*."},{"cle":{"type":"zone","ids":["m6","m18"]},"explication":"**gesehen** et **gemacht** : *sehen* et *machen* prennent *haben*."},{"cle":{"type":"trous","trous":[["habe"]]},"affichage":"habe","explication":"**Ich habe einen Film gesehen.** *sehen* prend *haben*."}]$ex$::jsonb),
  ('0a6938bf-8709-5ce1-a842-8502ea1b406b'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Un jeudi bien rempli","competence":"manier-langue","situation":"Ben raconte sa journée de jeudi dans un courriel. Les participes de son texte se forment de quatre façons différentes.","documents":[{"id":"mail","type":"texte","genre":"lettre","titre":"Mein Donnerstag","blocs":["Gestern habe ich viel erlebt. Ich bin früh aufgestanden und habe mit Oma telefoniert. Sie hat mir eine Geschichte erzählt, und ich habe alles verstanden. Danach habe ich Mathe gelernt und Pizza gegessen."],"source":"Courriel écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux participes qui n’ont pas de ge- à cause d’un préverbe inséparable.","aide":"Ils commencent par er- et ver-.","type":"zone","document":"mail","multiple":true},{"enonce":"Touche le participe où ge- s’est glissé entre le préverbe et le radical.","aide":"Il commence par auf-.","type":"zone","document":"mail","multiple":false},{"enonce":"Écris les participes II.","aide":"Séparable : ge- au milieu. En -ieren ou préverbe inséparable : pas de ge-.","type":"trous","segments":["einladen → ",0," · reparieren → ",1," · bezahlen → ",2]},{"enonce":"Pourquoi Ben dit-il « Ich bin früh aufgestanden » avec « bin » ?","aide":"Passer de couché à debout, c’est changer d’état.","type":"choix","options":[{"id":"a","texte":"aufstehen exprime un changement d’état"},{"id":"b","texte":"auf- est un préverbe inséparable"},{"id":"c","texte":"Ben parle de lui-même"},{"id":"d","texte":"Tous les verbes séparables prennent sein"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m19","m24"]},"explication":"**erzählt** et **verstanden** : les préverbes *er-* et *ver-* sont inséparables, donc pas de ge-."},{"cle":{"type":"zone","ids":["m8"]},"explication":"**aufgestanden** : le ge- s’intercale dans un verbe séparable (*auf* + *ge* + *standen*)."},{"cle":{"type":"trous","trous":[["eingeladen"],["repariert"],["bezahlt"]]},"affichage":"eingeladen · repariert · bezahlt","explication":"**eingeladen** (séparable), **repariert** (-ieren) et **bezahlt** (préverbe be- inséparable)."},{"cle":{"type":"choix","ids":["a"]},"explication":"**aufstehen** : changement d’état, donc *sein* au parfait."}]$ex$::jsonb),
  ('0a6938bf-8709-5ce1-a842-8502ea1b406b'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La classe 9b à Prague","competence":"raisonner","situation":"Pendant la sortie scolaire, un élève écrit à sa professeure, puis un SMS compare le parfait et le prétérit. Deux documents, une question : quel temps, pourquoi ?","documents":[{"id":"mail","type":"texte","genre":"lettre","titre":"An Frau Wolf","blocs":["Liebe Frau Wolf, wir sind gut in Prag gelandet. Am Montag haben wir das Schloss besucht. Ich glaube, dass alle viel gelernt haben. Leider ist Elias im Zug eingeschlafen, weil er schlecht geschlafen hat."],"source":"Courriel écrit pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Der Film","participants":[{"nom":"Tom","emoji":"👦","cote":"gauche"},{"nom":"Ana","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Tom","texte":"Gestern habe ich einen Film gesehen."},{"qui":"Ana","texte":"Welchen?"},{"qui":"Tom","texte":"Er war lustig. Ich habe viel gelacht."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les deux auxiliaires qui ferment une subordonnée, après le participe.","aide":"Ils sont après « gelernt » et « geschlafen ».","type":"zone","document":"mail","multiple":true},{"enonce":"Remets en ordre : « Il dit qu’elle est restée à la maison. » La phrase commence par Er sagt.","aide":"Après dass, tout part à la fin : le participe, puis l’auxiliaire.","type":"ordre","items":[{"id":"a","texte":"sie"},{"id":"b","texte":"dass"},{"id":"c","texte":"zu Hause"},{"id":"d","texte":"ist"},{"id":"e","texte":"geblieben"},{"id":"f","texte":"Er sagt"}]},{"enonce":"Complète avec ist ou sind : « Anna est partie à Cologne et ses parents sont restés à la maison. »","aide":"Reisen et bleiben se conjuguent avec sein ; accorde avec le sujet.","type":"trous","segments":["Anna ",0," nach Köln gereist, und ihre Eltern ",1," zu Hause geblieben."],"banque":["haben","hat","sind","ist"]},{"enonce":"Touche l’unique verbe de ce SMS qui est au prétérit.","aide":"Il décrit le film : il était drôle.","type":"zone","document":"sms","multiple":false},{"enonce":"Pourquoi Tom dit-il « habe gesehen » mais « war » ?","aide":"Pense aux verbes qui gardent le prétérit même à l’oral.","type":"choix","options":[{"id":"a","texte":"À l’oral, sein garde le prétérit, les autres verbes le parfait"},{"id":"b","texte":"Parce que le parfait ne s’emploie jamais avec lustig"},{"id":"c","texte":"Parce que Film est masculin et exige war au lieu de ist"},{"id":"d","texte":"Parce que war est le participe II de sein dans cette phrase"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m22","m33"]},"explication":"**haben** et **hat** sont à la toute fin : dans une subordonnée, l’auxiliaire du parfait vient après le participe."},{"cle":{"type":"ordre","ids":["f","b","a","c","e","d"]},"explication":"**Er sagt, dass sie zu Hause geblieben ist.** Subordonnée : participe II puis auxiliaire conjugué, tout à la fin."},{"cle":{"type":"trous","trous":[["ist"],["sind"]]},"affichage":"ist · sind","explication":"**Anna ist nach Köln gereist, und ihre Eltern sind zu Hause geblieben.** *reisen* (déplacement) et *bleiben* prennent *sein*."},{"cle":{"type":"zone","ids":["m8"]},"explication":"**war** : le prétérit de *sein*, même à l’oral. Les autres verbes sont au parfait."},{"cle":{"type":"choix","ids":["a"]},"explication":"À l’oral, on emploie le **parfait** pour presque tous les verbes, mais *sein*, *haben*, *werden* et les modaux restent au **prétérit** : *Er war lustig*."}]$ex$::jsonb),
  ('0b5ef7f9-8b66-5ebe-bf9d-a8994486e5fe'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"D’où viens-tu ? Où vas-tu ?","competence":"comprendre-langue","situation":"Lena, une jeune Française, bavarde avec Tom sur le quai d’une gare allemande. Il lui demande d’où elle vient et où elle va.","documents":[{"id":"bahnhof","type":"dialogue","modele":"sms","titre":"Am Bahnhof","participants":[{"nom":"Tom","emoji":"👧","cote":"gauche"},{"nom":"Lena","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Tom","texte":"Woher kommst du?"},{"qui":"Lena","texte":"Ich komme aus Frankreich. Jetzt wohne ich in Lyon."},{"qui":"Tom","texte":"Und wohin fährst du morgen?"},{"qui":"Lena","texte":"Ich fahre nach Berlin."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche la préposition qui dit d’où vient Lena.","aide":"Elle est suivie de *Frankreich*.","type":"zone","document":"bahnhof","multiple":false},{"enonce":"Touche la préposition qui dit où Lena va, devant une ville sans article.","aide":"Elle est devant *Berlin*.","type":"zone","document":"bahnhof","multiple":false},{"enonce":"Associe chaque question à son sens.","aide":"*hin* s’éloigne du locuteur, *her* se rapproche.","type":"association","gauche":[{"id":"g0","texte":"wo ?"},{"id":"g1","texte":"wohin ?"},{"id":"g2","texte":"woher ?"}],"droite":[{"id":"d0","texte":"l’origine (d’où)"},{"id":"d1","texte":"la localisation (où)"},{"id":"d2","texte":"la destination (vers où)"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5"]},"explication":"**aus** : *Ich komme aus Frankreich*. Il répond à la question *woher ?*."},{"cle":{"type":"zone","ids":["m19"]},"explication":"**nach** : *nach Berlin*. Il répond à la question *wohin ?*, pour une ville ou un pays sans article."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"*wo ?* = où l’on est ; *wohin ?* = où l’on va ; *woher ?* = d’où l’on vient."}]$ex$::jsonb),
  ('0b5ef7f9-8b66-5ebe-bf9d-a8994486e5fe'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Avec ou sans mouvement ?","competence":"manier-langue","situation":"Lea écrit à Tom, qui court d’un rendez-vous à l’autre. Selon qu’il est quelque part ou qu’il s’y rend, l’allemand change de préposition.","documents":[{"id":"tom","type":"dialogue","modele":"sms","titre":"Termine","participants":[{"nom":"Lea","emoji":"👧","cote":"gauche"},{"nom":"Tom","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lea","texte":"Wo bist du gerade?"},{"qui":"Tom","texte":"Ich bin beim Arzt. Danach gehe ich auf die Post."},{"qui":"Lea","texte":"Und am Wochenende?"},{"qui":"Tom","texte":"Ich fahre ans Meer, und danach aufs Land zu meiner Tante."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui dit que Tom est chez le médecin (sans mouvement).","aide":"Il répond à *wo ?* et se termine par -m.","type":"zone","document":"tom","multiple":false},{"enonce":"Touche le mot qui dit que Tom va au bord de la mer.","aide":"Il répond à *wohin ?* et se termine par -s.","type":"zone","document":"tom","multiple":false},{"enonce":"Range chaque expression : avec ou sans mouvement ?","aide":"Les formes contractées en *-s* (*ans*, *aufs*) sont des accusatifs : elles disent un mouvement.","type":"categories","categories":[{"id":"c0","texte":"Avec mouvement (wohin ?)"},{"id":"c1","texte":"Sans mouvement (wo ?)"}],"items":[{"id":"i0","texte":"zu Hause"},{"id":"i1","texte":"am Meer"},{"id":"i2","texte":"aufs Land"},{"id":"i3","texte":"auf dem Land"},{"id":"i4","texte":"nach Hause"},{"id":"i5","texte":"ans Meer"}]},{"enonce":"Complète : « Je vais chez ma grand-mère et je suis ensuite chez elle. »","aide":"Aller chez quelqu’un : *zu*. Être chez quelqu’un : *bei*.","type":"trous","segments":["Ich gehe ",0," meiner Oma und bin dann ",1," meiner Oma."],"banque":["zu","bei","aus","nach"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6"]},"explication":"**beim** = *bei dem* : on est chez le médecin, sans mouvement. Pour y aller, on dirait *zum Arzt*."},{"cle":{"type":"zone","ids":["m19"]},"explication":"**ans** = *an das* : *an* + accusatif, car il y a un mouvement vers le bord de la mer."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c1","i4":"c0","i5":"c0"}},"explication":"*ans Meer*, *aufs Land* et *nach Hause* disent un **mouvement** ; *am Meer*, *auf dem Land* et *zu Hause* disent un **lieu**. Elles vont toujours par paires."},{"cle":{"type":"trous","trous":[["zu"],["bei"]]},"affichage":"zu · bei","explication":"**zu meiner Oma** (mouvement vers une personne) et **bei meiner Oma** (lieu). Le français dit « chez » dans les deux cas, pas l’allemand."}]$ex$::jsonb),
  ('0b5ef7f9-8b66-5ebe-bf9d-a8994486e5fe'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Plan de voyage en Europe","competence":"lire-carte","situation":"Un jeune voyageur prépare un parcours en Europe. Une carte montre les pays traversés ; son courriel dit comment il y va, d’où il revient et où il séjourne.","documents":[{"id":"karte","type":"carte","titre":"Reiseziele","fond":"europe","cadrage":[-6,40,22,56],"regions":[{"code":"FRA","teinte":"ciel","etiquette":"Frankreich"},{"code":"DEU","teinte":"ciel","etiquette":"Deutschland"},{"code":"CHE","teinte":"ciel","etiquette":"Schweiz"},{"code":"AUT","teinte":"ciel","etiquette":"Österreich"}],"regionsCliquables":true,"source":"Carte écrite pour l’exercice"},{"id":"mail","type":"texte","genre":"lettre","titre":"Hallo Clara","blocs":["Ich komme gerade von der Arbeit. Morgen fahre ich nach Wien, am Samstag dann in die Schweiz, zu meinem Bruder. Er lebt seit zwei Jahren im Ausland."],"source":"Courriel écrit pour l’exercice"}],"questions":[{"enonce":"Touche le pays devant lequel on dit « in die » pour y aller.","aide":"Parmi ces pays, un seul a un article.","type":"zone","document":"karte","multiple":false},{"enonce":"Touche le pays où se trouve Wien.","aide":"Wien est la capitale de ce pays voisin de l’Allemagne.","type":"zone","document":"karte","multiple":false},{"enonce":"Touche la préposition qui dit d’où revient le voyageur (l’origine).","aide":"Elle est devant *der Arbeit*.","type":"zone","document":"mail","multiple":false},{"enonce":"Complète : « Ma tante habite à la campagne. Aujourd’hui, nous allons à la campagne. »","aide":"Premier trou : lieu (datif). Deuxième trou : mouvement (accusatif contracté).","type":"trous","segments":["Meine Tante wohnt ",0," Land. Heute fahren wir ",1," Land."],"banque":["auf dem","ans","auf den","aufs"]},{"enonce":"Remets en ordre : « Je reviens de mon travail. » La phrase commence par Ich.","aide":"*von* est suivi du datif.","type":"ordre","items":[{"id":"a","texte":"Ich"},{"id":"b","texte":"komme"},{"id":"c","texte":"der Arbeit"},{"id":"d","texte":"von"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["CHE"]},"explication":"**La Suisse** : *in die Schweiz*. Les pays avec article (*die Schweiz*, *die Türkei*) demandent *in* + accusatif ; les autres demandent *nach* (*nach Österreich*, *nach Frankreich*)."},{"cle":{"type":"zone","ids":["AUT"]},"explication":"**L’Autriche** : *nach Wien*. Une ville sans article se dit avec *nach*."},{"cle":{"type":"zone","ids":["m3"]},"explication":"**von** : *von der Arbeit* indique un point de départ ; elle répond à la question *woher ?*."},{"cle":{"type":"trous","trous":[["auf dem"],["aufs","auf das"]]},"affichage":"auf dem · aufs","explication":"**auf dem Land** (où ? datif) et **aufs Land** (où ? accusatif, *auf das* contracté en *aufs*) : l’expression se présente par paires."},{"cle":{"type":"ordre","ids":["a","b","d","c"]},"explication":"**Ich komme von der Arbeit.** *von* + datif féminin (*der Arbeit*) indique l’origine."}]$ex$::jsonb),
  ('0b721c74-364b-580f-bbdd-2330179abf8b'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Dans la chambre de Lisa","competence":"manier-langue","situation":"Lisa range sa chambre et dresse la liste de ce qu’elle y trouve. En allemand, chaque nom a son article : der, die ou das.","documents":[{"id":"zimmer","type":"tableau","titre":"Lisas Zimmer","colonnes":["Wort"],"lignes":[["Tisch"],["Lampe"],["Stuhl"],["Kätzchen"],["Tür"],["Buch"]],"enteteLignes":false,"source":"Liste écrite pour l’exercice"}],"questions":[{"enonce":"Range chaque mot de la liste de Lisa avec son article.","aide":"Le diminutif en -chen est neutre ; Lampe et Tür sont féminins.","type":"categories","categories":[{"id":"c0","texte":"der"},{"id":"c1","texte":"die"},{"id":"c2","texte":"das"}],"items":[{"id":"i0","texte":"Lampe"},{"id":"i1","texte":"Buch"},{"id":"i2","texte":"Tür"},{"id":"i3","texte":"Stuhl"},{"id":"i4","texte":"Tisch"},{"id":"i5","texte":"Kätzchen"}]},{"enonce":"Touche le mot de la liste qui est neutre à cause de sa terminaison -chen.","aide":"Cherche un diminutif : un petit animal.","type":"zone","document":"zimmer","multiple":false},{"enonce":"Lisa écrit « die Stühle ». Pourquoi l’article est-il « die » alors que « der Stuhl » est masculin ?","aide":"Pense à la seule « simplification » de l’allemand.","type":"choix","options":[{"id":"a","texte":"Le tréma sur le ü rend automatiquement le mot féminin"},{"id":"b","texte":"Au pluriel, l’article défini est die pour les trois genres"},{"id":"c","texte":"Die est le pluriel des seuls noms de genre masculin"},{"id":"d","texte":"Stühle est un nom féminin au singulier, comme Lampe"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c1","i1":"c2","i2":"c1","i3":"c0","i4":"c0","i5":"c2"}},"explication":"**der Tisch, der Stuhl** (masculins), **die Lampe, die Tür** (féminins), **das Kätzchen, das Buch** (neutres)."},{"cle":{"type":"zone","ids":["r3c0"]},"explication":"**Kätzchen** est neutre : tous les diminutifs en *-chen* et *-lein* sont neutres, même si le mot désigne un être vivant."},{"cle":{"type":"choix","ids":["b"]},"explication":"Au pluriel, l’article défini est **die** pour les trois genres : *die Stühle, die Lampen, die Bücher*."}]$ex$::jsonb),
  ('0b721c74-364b-580f-bbdd-2330179abf8b'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Les mots du quotidien","competence":"manier-langue","situation":"Dans son cahier, Mehmet a noté huit mots d’allemand pour s’entraîner à deviner le genre grâce à leur terminaison ou à leur sens.","documents":[{"id":"woerter","type":"tableau","titre":"Acht Wörter","colonnes":["Wort","Mein Tipp"],"lignes":[["Zeitung","terminaison -ung"],["Freiheit","terminaison -heit"],["Lehrer","terminaison -er"],["Frühling","une saison"],["Medikament","terminaison -ment"],["Mädchen","terminaison -chen"],["Bäckerei","terminaison -ei"],["Montag","un jour"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche les trois mots du tableau qui sont féminins.","aide":"Les terminaisons -ung, -heit et -ei signalent le féminin.","type":"zone","document":"woerter","multiple":true},{"enonce":"Complète avec le bon article : « La liberté est importante. Le printemps est beau. »","aide":"Freiheit finit par -heit ; les saisons sont masculines.","type":"trous","segments":[0," Freiheit ist wichtig. ",1," Frühling ist schön."],"banque":["Die","Das","Der"]},{"enonce":"Comment dit-on « Il est professeur » ?","aide":"Après sein, un métier s’emploie sans article.","type":"choix","options":[{"id":"a","texte":"Er ist ein Lehrer."},{"id":"b","texte":"Er ist der Lehrer."},{"id":"c","texte":"Er ist Lehrer."},{"id":"d","texte":"Er ist einen Lehrer."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c0","r1c0","r6c0"]},"explication":"**Zeitung, Freiheit, Bäckerei** sont féminins (*die*). Les noms en -ung, -heit, -keit, -schaft, -ion, -ei, -ie sont féminins."},{"cle":{"type":"trous","trous":[["die"],["der"]]},"affichage":"Die · Der","explication":"**Die Freiheit** (féminin, -heit) et **der Frühling** (masculin, une saison)."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Er ist Lehrer.** Après *sein* ou *werden*, un métier s’emploie sans article, contrairement au français « il est un… »."}]$ex$::jsonb),
  ('0b721c74-364b-580f-bbdd-2330179abf8b'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Une famille à Vienne","competence":"raisonner","situation":"Nina rend visite à son cousin Karl en Autriche. Il lui présente sa famille. Ils jouent aussi à deviner le genre des mots.","documents":[{"id":"familie","type":"dialogue","modele":"sms","titre":"Wer ist das?","participants":[{"nom":"Nina","emoji":"👧","cote":"gauche"},{"nom":"Karl","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Nina","texte":"Wer ist das?"},{"qui":"Karl","texte":"Das ist mein Onkel. Er ist Lehrer."},{"qui":"Nina","texte":"Und das?"},{"qui":"Karl","texte":"Das sind meine Cousinen. Sie wohnen in Österreich."}],"source":"Messages écrits pour l’exercice"},{"id":"regeln","type":"tableau","titre":"Drei Tipps","colonnes":["Wort","Hinweis"],"lignes":[["Zeitung","Endung -ung"],["Mädchen","Endung -chen"],["Montag","Wochentag"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche le verbe qui est au pluriel parce qu’il s’accorde avec « meine Cousinen », et non avec « das ».","aide":"Cherche le verbe sein conjugué à la 3e personne du pluriel.","type":"zone","document":"familie","multiple":false},{"enonce":"Quel est le rôle de « Das » dans « Das ist mein Onkel » ?","aide":"Onkel est masculin : l’article neutre ne pourrait pas s’accorder avec lui.","type":"choix","options":[{"id":"a","texte":"Démonstratif invariable qui désigne une personne ou une chose"},{"id":"b","texte":"Article défini neutre placé devant le nom Onkel"},{"id":"c","texte":"Conjonction de subordination, tout comme le mot dass"},{"id":"d","texte":"Pronom personnel qui remplace le groupe mein Onkel"}],"multiple":false},{"enonce":"Associe chaque mot du tableau de Karl au genre que sa terminaison ou son sens annonce.","aide":"Relis les trois indices du tableau : une terminaison, un diminutif, un jour.","type":"association","gauche":[{"id":"g0","texte":"die Zeitung"},{"id":"g1","texte":"das Mädchen"},{"id":"g2","texte":"der Montag"}],"droite":[{"id":"d0","texte":"masculin (jour)"},{"id":"d1","texte":"neutre (-chen)"},{"id":"d2","texte":"féminin (-ung)"}]},{"enonce":"Dans « Sie wohnen in Österreich », pourquoi le nom du pays n’a-t-il pas d’article ?","aide":"Pense à « nach Deutschland », « in Frankreich ».","type":"choix","options":[{"id":"a","texte":"Österreich est un nom pluriel, donc sans article"},{"id":"b","texte":"La plupart des noms de pays s’emploient sans article"},{"id":"c","texte":"Les noms de pays sont toujours masculins"},{"id":"d","texte":"Après in, un nom ne prend jamais d’article"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m13"]},"explication":"**sind** : dans *Das sind meine Cousinen*, *das* est invariable et le verbe s’accorde avec le groupe qui suit (pluriel)."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Das** est ici un démonstratif invariable (« ça, c’est… ») : il ne s’accorde ni avec le genre, ni avec le nombre de ce qui suit."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2"}},"explication":"**die Zeitung** (-ung : féminin), **das Mädchen** (-chen : neutre), **der Montag** (les jours sont masculins)."},{"cle":{"type":"choix","ids":["b"]},"explication":"La plupart des **noms de pays** (*Österreich, Deutschland, Frankreich*) s’emploient **sans article** : *Sie wohnen in Österreich.*"}]$ex$::jsonb),
  ('4dd6a4d6-28fe-5659-ab7f-ab81505be639'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Une recette de crêpes","competence":"comprendre-langue","situation":"Une recette de Pfannkuchen donne ses consignes à l’impératif. Observe comment l’ordre est formé quand on dit « tu ».","documents":[{"id":"rezept","type":"fiche","modele":"recette","entete":"Pfannkuchen","sousTitre":"Für zwei Personen","emoji":"🥞","lignes":[{"texte":"Nimm eine große Schüssel.","id":"z1"},{"texte":"Gib Mehl, Eier und Milch dazu.","id":"z2"},{"texte":"Rühre alles gut.","id":"z3"},{"texte":"Mach die Pfanne heiß.","id":"z4"}],"pied":"Guten Appetit!","source":"Recette écrite pour l’exercice"}],"questions":[{"enonce":"Touche les deux consignes dont l’impératif a gardé le changement de voyelle e → i.","aide":"Cherche nehmen et geben.","type":"zone","document":"rezept","multiple":true},{"enonce":"Associe chaque personne à l’impératif de « kommen ».","aide":"Seuls Sie et wir gardent le pronom.","type":"association","gauche":[{"id":"g0","texte":"du"},{"id":"g1","texte":"ihr"},{"id":"g2","texte":"Sie"},{"id":"g3","texte":"wir"}],"droite":[{"id":"d0","texte":"Kommen Sie!"},{"id":"d1","texte":"Komm!"},{"id":"d2","texte":"Kommen wir!"},{"id":"d3","texte":"Kommt!"}]},{"enonce":"Remets en ordre : « Donne-moi le sel ! »","aide":"Le verbe ouvre la phrase, sans pronom : le datif vient avant l’accusatif.","type":"ordre","items":[{"id":"a","texte":"Gib"},{"id":"b","texte":"das Salz"},{"id":"c","texte":"mir"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1","z2"]},"explication":"**Nimm** (*nehmen*) et **Gib** (*geben*) gardent la voyelle des 2e et 3e personnes : *du nimmst*, *du gibst*."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g3":"d2","g1":"d3"}},"explication":"**Komm!** (du), **Kommt!** (ihr), **Kommen Sie!** (politesse), **Kommen wir!** (allons-y)."},{"cle":{"type":"ordre","ids":["a","c","b"]},"explication":"**Gib mir das Salz!** Le verbe ouvre la phrase, sans *du*."}]$ex$::jsonb),
  ('4dd6a4d6-28fe-5659-ab7f-ab81505be639'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les consignes de Frau Weiß","competence":"manier-langue","situation":"Dans la classe, Frau Weiß donne des consignes à tous les élèves, puis à Jonas seul. Écoute bien à qui elle parle.","documents":[{"id":"klasse","type":"dialogue","modele":"sms","titre":"Im Klassenzimmer","participants":[{"nom":"Frau Weiß","emoji":"👩","cote":"gauche"},{"nom":"Jonas","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Frau Weiß","texte":"Seid bitte ruhig und öffnet eure Hefte. Jonas, lies den Text. Sprich laut und langsam!"},{"qui":"Jonas","texte":"Soll ich auch die Fragen lesen?"},{"qui":"Frau Weiß","texte":"Ja, aber nicht so schnell."}],"source":"Dialogue écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux impératifs adressés à toute la classe (ihr).","aide":"Ils se terminent par -t ou -d et n’ont pas de pronom.","type":"zone","document":"klasse","multiple":true},{"enonce":"Touche les deux impératifs adressés à Jonas seul (du).","aide":"Ils n’ont pas de terminaison et gardent e → ie et e → i.","type":"zone","document":"klasse","multiple":true},{"enonce":"Écris l’impératif à « du ».","aide":"Avec a → ä, l’inflexion se perd à l’impératif.","type":"trous","segments":["fahren : ",0," bitte langsam! · schlafen : ",1," jetzt!"]},{"enonce":"Pourquoi dit-on « Arbeite! » avec un -e final ?","aide":"Regarde la dernière lettre du radical : arbeit-.","type":"choix","options":[{"id":"a","texte":"Parce que tous les impératifs prennent un -e final"},{"id":"b","texte":"Parce que arbeiten est un verbe fort qui change de voyelle"},{"id":"c","texte":"Parce que arbeiten possède un préverbe séparable"},{"id":"d","texte":"Parce que le radical finit par -t : le e est obligatoire"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m0","m4"]},"explication":"**Seid** (*sein*) et **öffnet** (*öffnen*) sont des impératifs à *ihr* : la forme du présent, sans pronom."},{"cle":{"type":"zone","ids":["m8","m11"]},"explication":"**Lies** (*lesen*) et **Sprich** (*sprechen*) : le radical sans terminaison, avec la voyelle des 2e et 3e personnes."},{"cle":{"type":"trous","trous":[["fahr","fahre"],["schlaf","schlafe"]]},"affichage":"Fahr · Schlaf","explication":"**Fahr!** et **Schlaf!** : l’inflexion *a → ä* disparaît à l’impératif (alors que *du fährst*)."},{"cle":{"type":"choix","ids":["d"]},"explication":"**Arbeite!** : après -d, -t, -ig, le *-e* est obligatoire. Ailleurs, il est facultatif et soutenu (*Gehe!*)."}]$ex$::jsonb),
  ('4dd6a4d6-28fe-5659-ab7f-ab81505be639'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Ordres, consignes et services","competence":"raisonner","situation":"Dans un immeuble, l’affiche du règlement mêle plusieurs façons d’ordonner. Plus loin, deux amis se demandent un service : on adoucit l’ordre autrement.","documents":[{"id":"haus","type":"fiche","modele":"affiche","entete":"Hausordnung","sousTitre":"Bitte lesen","emoji":"🏢","lignes":[{"texte":"Nicht rauchen!","id":"z1"},{"texte":"Bitte Schuhe ausziehen!","id":"z2"},{"texte":"Seien Sie bitte leise.","id":"z3"},{"texte":"Schließen Sie die Tür.","id":"z4"}],"pied":"Danke!","source":"Affiche écrite pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Ein Gefallen","participants":[{"nom":"Ana","emoji":"👧","cote":"gauche"},{"nom":"Tom","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Ana","texte":"Hilf mir mal, Tom! Ich finde meinen Schlüssel nicht."},{"qui":"Tom","texte":"Such doch im Auto. Gib mir bitte deine Tasche."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les deux consignes données à l’infinitif, sans verbe conjugué.","aide":"Elles ne contiennent ni Sie ni forme conjuguée.","type":"zone","document":"haus","multiple":true},{"enonce":"Touche la ligne qui emploie l’impératif de politesse du verbe « sein ».","aide":"Cherche une forme de sein suivie de Sie.","type":"zone","document":"haus","multiple":false},{"enonce":"Touche les trois petits mots qui adoucissent l’ordre.","aide":"Ils se traduisent par un peu, donc, s’il te plaît.","type":"zone","document":"sms","multiple":true},{"enonce":"Remets en ordre : « Appelle-moi demain ! »","aide":"Le verbe ouvre la phrase ; le préverbe séparable part à la fin.","type":"ordre","items":[{"id":"a","texte":"mich"},{"id":"b","texte":"an"},{"id":"c","texte":"Ruf"},{"id":"d","texte":"morgen"}]},{"enonce":"Associe chaque pronom à l’impératif de « gehen ».","aide":"Seuls Sie et wir gardent le pronom.","type":"association","gauche":[{"id":"g0","texte":"du"},{"id":"g1","texte":"ihr"},{"id":"g2","texte":"Sie"},{"id":"g3","texte":"wir"}],"droite":[{"id":"d0","texte":"Gehen wir!"},{"id":"d1","texte":"Geh!"},{"id":"d2","texte":"Geht!"},{"id":"d3","texte":"Gehen Sie!"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1","z2"]},"explication":"**Nicht rauchen!** et **Bitte Schuhe ausziehen!** : l’infinitif seul sert aux panneaux et aux consignes."},{"cle":{"type":"zone","ids":["z3"]},"explication":"**Seien Sie bitte leise** : impératif de politesse de *sein* ; le pronom *Sie* se maintient."},{"cle":{"type":"zone","ids":["m2","m10","m15"]},"explication":"**mal**, **doch**, **bitte** : sans eux, l’impératif paraîtrait sec."},{"cle":{"type":"ordre","ids":["c","a","d","b"]},"explication":"**Ruf mich morgen an!** *anrufen* : le préverbe *an* passe à la fin."},{"cle":{"type":"association","paires":{"g3":"d0","g0":"d1","g1":"d2","g2":"d3"}},"explication":"**Geh!** (du), **Geht!** (ihr), **Gehen Sie!** (politesse), **Gehen wir!** (allons-y)."}]$ex$::jsonb),
  ('14eaa575-d3b9-5b1e-8b6a-a34ce30dd2de'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Les règles de la piscine","competence":"comprendre-langue","situation":"À l’entrée de la piscine municipale, une affiche rappelle les règles. Chaque ligne emploie un verbe de modalité différent.","documents":[{"id":"affiche","type":"fiche","modele":"affiche","entete":"Schwimmbad","sousTitre":"Die Regeln","emoji":"🏊","lignes":[{"texte":"Du musst vor dem Schwimmen duschen.","id":"z1"},{"texte":"Du darfst nicht rennen.","id":"z2"},{"texte":"Du kannst im Kiosk ein Eis kaufen.","id":"z3"},{"texte":"Du sollst bei Gewitter aus dem Wasser kommen.","id":"z4"}],"pied":"Viel Spaß!","source":"Affiche écrite pour l’exercice"}],"questions":[{"enonce":"Touche la règle qui exprime une interdiction.","aide":"Cherche le modal qui parle du droit, avec nicht.","type":"zone","document":"affiche","multiple":false},{"enonce":"Touche la ligne qui dit simplement ce qu’on est capable ou en mesure de faire.","aide":"C’est le modal de la possibilité, de la capacité.","type":"zone","document":"affiche","multiple":false},{"enonce":"Associe chaque modal à son idée principale.","aide":"Pense à ce que chaque modal exprime : capacité, droit, nécessité, volonté.","type":"association","gauche":[{"id":"g0","texte":"können"},{"id":"g1","texte":"dürfen"},{"id":"g2","texte":"müssen"},{"id":"g3","texte":"wollen"}],"droite":[{"id":"d0","texte":"vouloir (volonté ferme)"},{"id":"d1","texte":"pouvoir (capacité)"},{"id":"d2","texte":"avoir le droit"},{"id":"d3","texte":"devoir (nécessité)"}]},{"enonce":"Remets en ordre : « Je veux nager aujourd’hui. » La phrase commence par Ich.","aide":"Le modal est en deuxième position, l’infinitif part à la fin.","type":"ordre","items":[{"id":"a","texte":"schwimmen"},{"id":"b","texte":"heute"},{"id":"c","texte":"Ich"},{"id":"d","texte":"will"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"**Du darfst nicht rennen** : *dürfen* + *nicht* dit l’interdiction (« tu n’as pas le droit »)."},{"cle":{"type":"zone","ids":["z3"]},"explication":"**Du kannst im Kiosk ein Eis kaufen** : *können* exprime la possibilité."},{"cle":{"type":"association","paires":{"g3":"d0","g0":"d1","g1":"d2","g2":"d3"}},"explication":"**können** : capacité ; **dürfen** : droit ; **müssen** : nécessité ; **wollen** : volonté ferme."},{"cle":{"type":"ordre","ids":["c","d","b","a"]},"explication":"**Ich will heute schwimmen.** Le modal conjugué est en 2e position, l’infinitif à la fin de la phrase."}]$ex$::jsonb),
  ('14eaa575-d3b9-5b1e-8b6a-a34ce30dd2de'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Pas obligé ou pas le droit ?","competence":"comprendre-langue","situation":"Nils discute avec son père avant le week-end. Entre « pas obligé » et « interdit », un seul mot change tout.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Das Wochenende","participants":[{"nom":"Papa","emoji":"👨","cote":"gauche"},{"nom":"Nils","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Papa","texte":"Du musst heute nicht aufräumen. Aber du darfst nicht so lange fernsehen."},{"qui":"Nils","texte":"Ich muss nicht aufräumen? Super! Ich will mit Ben ins Kino gehen."},{"qui":"Papa","texte":"Du kannst gehen. Aber du sollst um zehn Uhr zu Hause sein, sagt Mama."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le modal qui, avec « nicht », exprime une interdiction.","aide":"C’est le modal du droit.","type":"zone","document":"sms","multiple":false},{"enonce":"Que signifie « Du musst heute nicht aufräumen » ?","aide":"Müssen + nicht nie veut dire « interdit ».","type":"choix","options":[{"id":"a","texte":"Tu n’es pas obligé de ranger"},{"id":"b","texte":"Tu n’as pas le droit de ranger"},{"id":"c","texte":"Tu ne peux pas ranger"},{"id":"d","texte":"Tu dois ranger deux fois"}],"multiple":false},{"enonce":"Touche le modal qui rapporte une consigne venue de Mama.","aide":"Il exprime un ordre qui vient d’une autre personne.","type":"zone","document":"sms","multiple":false},{"enonce":"Remets en ordre : « Il reste à la maison parce qu’il doit travailler. » La phrase commence par Er bleibt zu Hause.","aide":"Après weil, tout part à la fin : l’infinitif, puis le modal conjugué.","type":"ordre","items":[{"id":"a","texte":"arbeiten"},{"id":"b","texte":"weil"},{"id":"c","texte":"muss"},{"id":"d","texte":"er"},{"id":"e","texte":"Er bleibt zu Hause"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7"]},"explication":"**darfst … nicht** : « tu n’as pas le droit de ». Une interdiction, et non une absence d’obligation."},{"cle":{"type":"choix","ids":["a"]},"explication":"**müssen + nicht** = « ne pas être obligé » : l’action est facultative, pas interdite."},{"cle":{"type":"zone","ids":["m29"]},"explication":"**sollst** : *sollen* rapporte une consigne extérieure (« on t’a dit de… »)."},{"cle":{"type":"ordre","ids":["e","b","d","a","c"]},"explication":"**Er bleibt zu Hause, weil er arbeiten muss.** Dans la subordonnée, le verbe conjugué (le modal) est tout à la fin."}]$ex$::jsonb),
  ('14eaa575-d3b9-5b1e-8b6a-a34ce30dd2de'::uuid, 3, 3, 15, 50, 6,
   $ex${"titre":"Une excuse et une invitation","competence":"raisonner","situation":"Emma s’excuse auprès de Clara pour une fête manquée. Clara lui envoie alors une nouvelle invitation. Deux documents, six modaux à bien comprendre.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Liebe Clara","blocs":["Liebe Clara, es tut mir leid: Ich habe gestern nicht zu deiner Party kommen können. Ich musste für Mathe lernen, weil wir heute eine Arbeit schreiben müssen. Mama sagt, ich soll früh schlafen. Nächste Woche will ich dich besuchen. Dann darf ich auch länger bleiben. Deine Emma"],"source":"Lettre écrite pour l’exercice"},{"id":"invit","type":"fiche","modele":"invitation","entete":"Clara lädt dich ein","sousTitre":"Party am Samstag","emoji":"🎉","lignes":[{"texte":"Du kannst kommen!","id":"z1"},{"texte":"Du darfst Freunde mitbringen.","id":"z2"},{"texte":"Du musst nichts mitbringen.","id":"z3"}],"pied":"Ich freue mich auf dich!","source":"Invitation écrite pour l’exercice"}],"questions":[{"enonce":"Touche le modal conjugué au prétérit.","aide":"Le prétérit de müssen se termine par -te.","type":"zone","document":"lettre","multiple":false},{"enonce":"Touche les deux verbes qui forment le « double infinitif » du parfait.","aide":"À la fin de la phrase, le participe est remplacé par deux infinitifs.","type":"zone","document":"lettre","multiple":true},{"enonce":"Remets en ordre : « … parce que nous devons écrire un devoir. » La phrase commence par weil.","aide":"Dans la subordonnée, l’infinitif puis le modal conjugué sont tout à la fin.","type":"ordre","items":[{"id":"a","texte":"weil"},{"id":"b","texte":"schreiben"},{"id":"c","texte":"eine Arbeit"},{"id":"d","texte":"müssen"},{"id":"e","texte":"wir"}]},{"enonce":"Complète au parfait : « Hier, je n’ai pas pu venir. »","aide":"Avec un infinitif dépendant, le modal ne prend pas de participe.","type":"trous","segments":["Ich habe gestern nicht kommen ",0,"."],"banque":["konnte","gekonnt","kann","können"]},{"enonce":"Touche la ligne qui donne une autorisation.","aide":"Cherche le modal du droit.","type":"zone","document":"invit","multiple":false},{"enonce":"Que signifie « Du musst nichts mitbringen » ?","aide":"Müssen + négation ne dit pas l’interdiction.","type":"choix","options":[{"id":"a","texte":"Tu dois tout apporter"},{"id":"b","texte":"Tu ne sais pas apporter quoi que ce soit"},{"id":"c","texte":"Tu n’as pas le droit d’apporter quoi que ce soit"},{"id":"d","texte":"Tu n’es pas obligé d’apporter quoi que ce soit"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m16"]},"explication":"**musste** est le prétérit de *müssen* : sans inflexion, avec la terminaison *-te*."},{"cle":{"type":"zone","ids":["m13","m14"]},"explication":"**kommen können** : au parfait, un modal suivi d’un infinitif ne prend pas de participe. C’est le « double infinitif »."},{"cle":{"type":"ordre","ids":["a","e","c","b","d"]},"explication":"**weil wir eine Arbeit schreiben müssen.** Le modal conjugué ferme la subordonnée."},{"cle":{"type":"trous","trous":[["konnen"]]},"affichage":"können","explication":"**Ich habe gestern nicht kommen können.** Double infinitif : l’infinitif du modal (*können*) à la toute fin."},{"cle":{"type":"zone","ids":["z2"]},"explication":"**Du darfst Freunde mitbringen** : *dürfen* donne l’autorisation (« tu as le droit de »)."},{"cle":{"type":"choix","ids":["d"]},"explication":"**müssen + nichts** : aucune obligation. Clara dit à son invitée qu’elle peut venir les mains vides."}]$ex$::jsonb),
  ('cd20efcc-f2f3-50de-a18a-9236871967ab'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Lena reste à la maison","competence":"comprendre-langue","situation":"Lena est malade et prévient son ami Tom. Observe où se trouve le verbe dans leurs phrases à conjonction.","documents":[{"id":"krank","type":"dialogue","modele":"sms","titre":"Lena ist krank","participants":[{"nom":"Lena","emoji":"👧","cote":"gauche"},{"nom":"Tom","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lena","texte":"Ich bleibe heute zu Hause, weil ich krank bin."},{"qui":"Tom","texte":"Schade! Ich glaube, dass du bald wieder gesund bist."},{"qui":"Lena","texte":"Danke! Weißt du, ob wir morgen Mathe haben?"},{"qui":"Tom","texte":"Ich weiß es nicht, aber ich frage Frau Roth."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les trois conjonctions de subordination de la conversation : celles qui envoient le verbe conjugué à la fin.","aide":"Cherche les mots qui précèdent un sujet et un verbe final : « parce que », « que », « si ».","type":"zone","document":"krank","multiple":true},{"enonce":"Touche le verbe qui ferme la subordonnée « weil ich krank … ».","aide":"Dans une subordonnée, le verbe conjugué est le dernier mot.","type":"zone","document":"krank","multiple":false},{"enonce":"Associe chaque conjonction à son sens.","aide":"Relis les phrases de Lena et de Tom pour retrouver weil, dass et ob.","type":"association","gauche":[{"id":"g0","texte":"weil"},{"id":"g1","texte":"dass"},{"id":"g2","texte":"ob"},{"id":"g3","texte":"damit"}],"droite":[{"id":"d0","texte":"pour que"},{"id":"d1","texte":"parce que"},{"id":"d2","texte":"si (une alternative)"},{"id":"d3","texte":"que"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5","m12","m21"]},"explication":"**weil, dass, ob** introduisent une subordonnée : le verbe conjugué part à la fin. « aber » est une conjonction de coordination : l’ordre ne change pas."},{"cle":{"type":"zone","ids":["m8"]},"explication":"**bin** ferme la subordonnée : *…, weil ich krank bin.*"},{"cle":{"type":"association","paires":{"g3":"d0","g0":"d1","g2":"d2","g1":"d3"}},"explication":"**weil** = parce que, **dass** = que, **ob** = si (alternative), **damit** = pour que (but)."}]$ex$::jsonb),
  ('cd20efcc-f2f3-50de-a18a-9236871967ab'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les souvenirs de grand-mère","competence":"analyser-document","situation":"Oma raconte son enfance dans une lettre. Trois conjonctions de temps s’y cachent : als, wenn et wann.","documents":[{"id":"erinnerung","type":"texte","genre":"lettre","titre":"Omas Brief","blocs":["Als ich klein war, wohnte ich auf dem Land. Immer wenn es regnete, spielte ich im Stall. Als ich zehn wurde, zogen wir in die Stadt. Wenn ich heute meine Freundin besuche, sprechen wir noch von früher."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux conjonctions qui introduisent une période ou un événement unique du passé.","aide":"Cherche le mot qui traduit « quand » pour un fait qui n’est arrivé qu’une fois, sans répétition.","type":"zone","document":"erinnerung","multiple":true},{"enonce":"Pourquoi Oma écrit-elle « Immer wenn es regnete » et non « Immer als es regnete » ?","aide":"La pluie est tombée plusieurs fois, pas une seule.","type":"choix","options":[{"id":"a","texte":"La pluie revenait souvent : wenn exprime la répétition"},{"id":"b","texte":"Le verbe regnete est au présent, donc wenn est obligatoire"},{"id":"c","texte":"Als ne peut jamais suivre le mot immer, même au passé"},{"id":"d","texte":"Es regnete est une phrase sans sujet réel"}],"multiple":false},{"enonce":"Remets en ordre : « Quand j’étais petit, j’habitais à la campagne. »","aide":"La subordonnée ouvre la phrase : le verbe de la principale suit immédiatement la virgule.","type":"ordre","items":[{"id":"a","texte":"ich"},{"id":"b","texte":"wohnte"},{"id":"c","texte":"Als ich"},{"id":"d","texte":"klein war,"},{"id":"e","texte":"auf dem Land"}]},{"enonce":"Complète : « Quand j’ai le temps, je te rends visite. » (action qui se répète)","aide":"Une action qui se répète au présent se dit avec wenn.","type":"trous","segments":[0," ich Zeit habe, besuche ich dich."],"banque":["Wenn","Wann","Als","Weil"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m0","m17"]},"explication":"Les deux **Als** (*Als ich klein war*, *Als ich zehn wurde*) introduisent un fait ou une période unique du passé. *wenn* exprime la répétition (*immer wenn*) ou le présent."},{"cle":{"type":"choix","ids":["a"]},"explication":"**wenn** sert à la répétition dans le passé (« chaque fois que »). **als** est réservé à un fait unique."},{"cle":{"type":"ordre","ids":["c","d","b","a","e"]},"explication":"**Als ich klein war, wohnte ich auf dem Land.** Verbe de la subordonnée à la fin, puis le verbe de la principale, puis le sujet."},{"cle":{"type":"trous","trous":[["wenn"]]},"affichage":"Wenn","explication":"**Wenn ich Zeit habe, besuche ich dich.** *wann* ne s’emploie que dans une question ; *als* concerne un fait unique du passé."}]$ex$::jsonb),
  ('cd20efcc-f2f3-50de-a18a-9236871967ab'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une excuse bien écrite","competence":"manier-langue","situation":"Après une absence, un élève écrit à son professeur. Son courriel emploie plusieurs conjonctions, certaines de subordination, une seule de coordination.","documents":[{"id":"entschuldigung","type":"texte","genre":"lettre","titre":"Eine Entschuldigung","blocs":["Lieber Herr Braun,","ich konnte gestern nicht kommen, denn ich war krank. Weil ich Fieber hatte, blieb ich im Bett. Ich hoffe, dass Sie das verstehen. Obwohl ich noch müde bin, arbeite ich heute wieder.","Mit freundlichen Grüßen\nJonas"],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche la conjonction du courriel qui ne renvoie PAS le verbe à la fin de sa proposition.","aide":"Après cette conjonction, l’ordre est celui d’une phrase ordinaire : « ich war krank ».","type":"zone","document":"entschuldigung","multiple":false},{"enonce":"Remets en ordre la fin de la phrase « Ich bin müde, … » (« parce que j’ai beaucoup travaillé hier »).","aide":"Dans la subordonnée, l’auxiliaire conjugué ferme la phrase, après le participe.","type":"ordre","items":[{"id":"a","texte":"weil"},{"id":"b","texte":"gestern lange"},{"id":"c","texte":"gearbeitet"},{"id":"d","texte":"ich"},{"id":"e","texte":"habe"}]},{"enonce":"Touche le verbe de la principale qui suit immédiatement la subordonnée « Weil ich Fieber hatte, … ».","aide":"La subordonnée ouvre la phrase : le verbe de la principale vient tout de suite après la virgule.","type":"zone","document":"entschuldigung","multiple":false},{"enonce":"Laquelle de ces phrases est correcte ?","aide":"Après weil, le verbe conjugué est rejeté en fin de subordonnée.","type":"choix","options":[{"id":"a","texte":"Ich bleibe zu Hause, denn ich krank bin."},{"id":"b","texte":"Ich bleibe zu Hause, weil ich bin krank."},{"id":"c","texte":"Ich bleibe zu Hause, weil ich krank bin."},{"id":"d","texte":"Ich bleibe zu Hause, weil bin ich krank."}],"multiple":false},{"enonce":"Complète : « Bien que je sois fatigué, je vais au cinéma. »","aide":"On va au cinéma malgré la fatigue.","type":"trous","segments":[0," ich müde bin, gehe ich ins Kino."],"banque":["Damit","Obwohl","Bevor","Weil"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8"]},"explication":"**denn** est une conjonction de coordination : l’ordre des mots ne change pas (*denn ich war krank*), contrairement à *weil*."},{"cle":{"type":"ordre","ids":["a","d","b","c","e"]},"explication":"**…, weil ich gestern lange gearbeitet habe.** Au temps composé, c’est l’auxiliaire conjugué (*habe*) qui est le dernier mot."},{"cle":{"type":"zone","ids":["m16"]},"explication":"**blieb** : la subordonnée occupe la première place, donc le verbe de la principale est deuxième, avant son sujet *ich*."},{"cle":{"type":"choix","ids":["c"]},"explication":"**…, weil ich krank bin.** *weil* exige le verbe à la fin ; *denn* garde l’ordre ordinaire : *denn ich bin krank*."},{"cle":{"type":"trous","trous":[["obwohl"]]},"affichage":"Obwohl","explication":"**Obwohl ich müde bin, gehe ich ins Kino.** *obwohl* = bien que, et il envoie le verbe à la fin."}]$ex$::jsonb),
  ('3d9ceb19-367e-5aab-bfc5-2001708618a1'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le week-end de Lena","competence":"comprendre-langue","situation":"Lena raconte son week-end à son correspondant. Son texte relie les phrases avec de petits mots qu’il faut repérer.","documents":[{"id":"wochenende","type":"texte","genre":"recit","titre":"Mein Wochenende","blocs":["Am Samstag bleibe ich zu Hause, denn ich bin müde. Ich lese ein Buch und höre Musik. Am Sonntag gehe ich ins Kino oder ich besuche meine Oma. Das Wetter ist schlecht, aber ich habe gute Laune."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les quatre conjonctions de coordination du texte.","aide":"Elles relient deux éléments de même rang : cause, addition, choix, opposition.","type":"zone","document":"wochenende","multiple":true},{"enonce":"Associe chaque conjonction à son sens.","aide":"Retrouve chaque mot dans le texte de Lena.","type":"association","gauche":[{"id":"g0","texte":"und"},{"id":"g1","texte":"oder"},{"id":"g2","texte":"aber"},{"id":"g3","texte":"denn"}],"droite":[{"id":"d0","texte":"car"},{"id":"d1","texte":"mais"},{"id":"d2","texte":"ou"},{"id":"d3","texte":"et"}]},{"enonce":"Remets en ordre : « Je reste à la maison, car je suis malade. » La phrase commence par Ich bleibe zu Hause.","aide":"Après *denn*, l’ordre est normal : sujet puis verbe.","type":"ordre","items":[{"id":"a","texte":"krank"},{"id":"b","texte":"bin"},{"id":"c","texte":"denn"},{"id":"d","texte":"Ich bleibe zu Hause"},{"id":"e","texte":"ich"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6","m14","m23","m32"]},"explication":"**denn**, **und**, **oder** et **aber** sont des conjonctions de coordination : elles ne changent pas l’ordre des mots."},{"cle":{"type":"association","paires":{"g3":"d0","g2":"d1","g1":"d2","g0":"d3"}},"explication":"*und* = et, *oder* = ou, *aber* = mais, *denn* = car."},{"cle":{"type":"ordre","ids":["d","c","e","b","a"]},"explication":"**Ich bleibe zu Hause, denn ich bin krank.** *denn* est une coordination : le verbe reste en deuxième position."}]$ex$::jsonb),
  ('3d9ceb19-367e-5aab-bfc5-2001708618a1'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Pourquoi Ben ne vient pas","competence":"analyser-document","situation":"Ben et Mia parlent d’une fête. Pour expliquer pourquoi il reste chez lui, Ben utilise trois constructions qui disent la même chose, mais pas avec le même ordre des mots.","documents":[{"id":"party","type":"dialogue","modele":"sms","titre":"Die Party","participants":[{"nom":"Ben","emoji":"👧","cote":"gauche"},{"nom":"Mia","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Ben","texte":"Ich komme nicht zur Party, denn ich bin krank."},{"qui":"Mia","texte":"Schade! Es regnet auch, deshalb bleiben viele zu Hause."},{"qui":"Ben","texte":"Ich bleibe zu Hause, weil ich Fieber habe."},{"qui":"Mia","texte":"Gute Besserung! Ich komme zwar spät, aber ich komme."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche la conjonction de coordination qui veut dire « car ».","aide":"Le verbe qui suit reste en deuxième position.","type":"zone","document":"party","multiple":false},{"enonce":"Touche la conjonction de subordination : le verbe est envoyé à la fin.","aide":"Dans la phrase, le verbe *habe* est le dernier mot.","type":"zone","document":"party","multiple":false},{"enonce":"Touche l’adverbe de liaison qui provoque l’inversion du verbe et du sujet.","aide":"Le verbe *bleiben* précède son sujet.","type":"zone","document":"party","multiple":false},{"enonce":"Range chaque phrase selon la place du verbe.","aide":"Regarde la position du verbe après le mot de liaison.","type":"categories","categories":[{"id":"c0","texte":"Verbe en 2e position (coordination)"},{"id":"c1","texte":"Verbe à la fin (subordination)"},{"id":"c2","texte":"Inversion (adverbe de liaison)"}],"items":[{"id":"i0","texte":"Ich bin müde, aber ich komme."},{"id":"i1","texte":"Ich bleibe, weil ich krank bin."},{"id":"i2","texte":"Ich bleibe, denn ich bin krank."},{"id":"i3","texte":"Ich bin krank, deshalb bleibe ich."}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5"]},"explication":"**denn** : *denn ich bin krank*. Le verbe reste en deuxième position."},{"cle":{"type":"zone","ids":["m22"]},"explication":"**weil** : *weil ich Fieber habe*. Après *weil*, le verbe conjugué se place à la fin."},{"cle":{"type":"zone","ids":["m13"]},"explication":"**deshalb** : *deshalb bleiben viele zu Hause*. L’adverbe occupe la première place, donc le verbe passe devant le sujet."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c2"}},"explication":"*denn* et *aber* ne changent rien : sujet puis verbe. *weil* envoie le verbe à la fin. *deshalb* occupe la première place : le verbe passe devant le sujet."}]$ex$::jsonb),
  ('3d9ceb19-367e-5aab-bfc5-2001708618a1'::uuid, 3, 3, 15, 50, 6,
   $ex${"titre":"Le courriel de la classe de Berlin","competence":"argumenter","situation":"Paul est en voyage scolaire à Berlin. Pour rassurer ses parents, il leur envoie un courriel soigné qui joue avec les couples de conjonctions.","documents":[{"id":"klassenfahrt","type":"texte","genre":"lettre","titre":"Liebe Eltern","blocs":["Die Klassenfahrt nach Berlin ist nicht nur lustig, sondern auch lehrreich. Das Hotel ist zwar klein, aber sehr sauber. Wir haben weder Handy noch Computer im Zimmer. Wir fahren nicht mit dem Bus, sondern mit dem Zug. Entweder gehen wir ins Museum oder wir besuchen den Reichstag."],"source":"Courriel écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux « sondern » du courriel.","aide":"Ils suivent une négation (*nicht nur*, *nicht*).","type":"zone","document":"klassenfahrt","multiple":true},{"enonce":"Touche le couple qui veut dire « ni… ni ».","aide":"La phrase est déjà négative : pas de *nicht*.","type":"zone","document":"klassenfahrt","multiple":true},{"enonce":"Associe chaque couple à son sens.","aide":"Pense au courriel de Paul pour les deux premiers.","type":"association","gauche":[{"id":"g0","texte":"entweder … oder"},{"id":"g1","texte":"weder … noch"},{"id":"g2","texte":"sowohl … als auch"},{"id":"g3","texte":"zwar … aber"}],"droite":[{"id":"d0","texte":"certes … mais"},{"id":"d1","texte":"aussi bien … que"},{"id":"d2","texte":"ou bien … ou bien"},{"id":"d3","texte":"ni … ni"}]},{"enonce":"Pourquoi écrit-on « nicht mit dem Bus, sondern mit dem Zug » et non « aber » ?","aide":"Regarde le mot qui précède la virgule dans la première partie.","type":"choix","options":[{"id":"a","texte":"Aber est interdit devant une préposition"},{"id":"b","texte":"Sondern est plus poli que aber"},{"id":"c","texte":"La virgule est supprimée avec sondern"},{"id":"d","texte":"La première partie est négative et on la rectifie"}],"multiple":false},{"enonce":"Remets en ordre : « Il n’est pas seulement intelligent, mais aussi gentil. » La phrase commence par Er.","aide":"Le verbe est en deuxième position, puis le couple *nicht nur … sondern auch*.","type":"ordre","items":[{"id":"a","texte":"sondern"},{"id":"b","texte":"Er"},{"id":"c","texte":"nicht nur klug"},{"id":"d","texte":"auch nett"},{"id":"e","texte":"ist"}]},{"enonce":"Complète : « Je n’ai ni temps ni argent. »","aide":"Le couple veut dire « ni… ni ».","type":"trous","segments":["Ich habe ",0," Zeit ",1," Geld."],"banque":["noch","entweder","weder","nicht"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8","m33"]},"explication":"**sondern** (deux fois) : après une négation, il rectifie ou ajoute (*nicht nur … sondern auch*, *nicht mit dem Bus, sondern mit dem Zug*)."},{"cle":{"type":"zone","ids":["m21","m23"]},"explication":"**weder … noch** : *weder Handy noch Computer*. Ce couple contient déjà la négation."},{"cle":{"type":"association","paires":{"g3":"d0","g2":"d1","g0":"d2","g1":"d3"}},"explication":"*entweder … oder* = ou bien … ou bien ; *weder … noch* = ni … ni ; *sowohl … als auch* = aussi bien … que ; *zwar … aber* = certes … mais."},{"cle":{"type":"choix","ids":["d"]},"explication":"**La première partie est négative (*nicht*) et la seconde la rectifie** : c’est le cas de *sondern*. *aber* s’emploie sans négation ou pour une simple opposition."},{"cle":{"type":"ordre","ids":["b","e","c","a","d"]},"explication":"**Er ist nicht nur klug, sondern auch nett.** Le couple *nicht nur … sondern auch* ne modifie pas la place du verbe."},{"cle":{"type":"trous","trous":[["weder"],["noch"]]},"affichage":"weder · noch","explication":"**Ich habe weder Zeit noch Geld.** Le couple *weder … noch* est déjà négatif : on n’ajoute pas *nicht*."}]$ex$::jsonb),
  ('149b010e-7cf9-5452-9f66-28b46bb2ee67'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les montagnes allemandes","competence":"lire-tableau","situation":"Pour son exposé de géographie, Ben a noté l’altitude de quatre montagnes allemandes.","documents":[{"id":"berge","type":"tableau","titre":"Vier Berge","colonnes":["Berg","Höhe (m)"],"lignes":[["Zugspitze",2962],["Watzmann",2713],["Feldberg",1493],["Brocken",1141]],"enteteLignes":true,"source":"Chiffres arrondis"}],"questions":[{"enonce":"D’après le tableau, quelle phrase est juste ?","aide":"Cherche l’altitude la plus grande.","type":"choix","options":[{"id":"a","texte":"Der Brocken ist am höchsten"},{"id":"b","texte":"Der Feldberg ist am höchsten"},{"id":"c","texte":"Die Zugspitze ist am höchsten"},{"id":"d","texte":"Der Watzmann ist am höchsten"}],"multiple":false},{"enonce":"Complète : « Le Brocken est le plus bas des quatre. »","aide":"Après *g*, pas de *e* de liaison : adjectif + -sten.","type":"trous","segments":["Der Brocken ist am ",0,"."],"banque":["niedrigste","niedrigstes","niedrigsten","niedrigesten"]},{"enonce":"Complète : « La Zugspitze est la plus haute montagne. » (devant un nom)","aide":"Devant un nom, le superlatif se décline : article + -ste.","type":"trous","segments":["Die Zugspitze ist der ",0," Berg."],"banque":["höchsten","hohe","am höchsten","höchste"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["c"]},"explication":"**Die Zugspitze ist am höchsten** : 2 962 m, la plus haute des quatre. Attribut : forme figée *am … -sten*."},{"cle":{"type":"trous","trous":[["niedrigsten"]]},"affichage":"niedrigsten","explication":"**Der Brocken ist am niedrigsten** : *niedrig* + **-sten** ; pas de *e* de liaison, car il ne finit ni par d, t, s, ß, z ni sch."},{"cle":{"type":"trous","trous":[["hochste"]]},"affichage":"höchste","explication":"**der höchste Berg** : devant un nom, *der* + superlatif en **-ste** ; *hoch* perd son *c* et prend l’Umlaut."}]$ex$::jsonb),
  ('149b010e-7cf9-5452-9f66-28b46bb2ee67'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Mon sport préféré","competence":"manier-langue","situation":"Mia et Jan discutent de sport. Leurs messages contiennent deux sortes de superlatifs : l’un est figé, l’autre se décline.","documents":[{"id":"sport","type":"dialogue","modele":"sms","titre":"Sport und Freizeit","participants":[{"nom":"Mia","emoji":"👧","cote":"gauche"},{"nom":"Jan","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Mia","texte":"Welcher Sport gefällt dir am besten?"},{"qui":"Jan","texte":"Am liebsten spiele ich Fußball. Tim ist der beste Spieler unserer Klasse."},{"qui":"Mia","texte":"Ich schwimme am schnellsten in der Gruppe."},{"qui":"Jan","texte":"Und Opa? Er ist am ältesten, aber er läuft jeden Tag."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le superlatif qui se décline parce qu’il est devant un nom.","aide":"Il est précédé de *der* et suivi de *Spieler*.","type":"zone","document":"sport","multiple":false},{"enonce":"Touche le superlatif figé qui décrit la façon de nager de Mia.","aide":"Il suit « am ».","type":"zone","document":"sport","multiple":false},{"enonce":"Range chaque phrase selon la forme du superlatif.","aide":"Cherche si un nom suit le superlatif.","type":"categories","categories":[{"id":"c0","texte":"am + -sten (figé)"},{"id":"c1","texte":"article + -ste (décliné)"}],"items":[{"id":"i0","texte":"Das beste Eis kostet drei Euro."},{"id":"i1","texte":"Er singt am schönsten."},{"id":"i2","texte":"Das schönste Lied kommt jetzt."},{"id":"i3","texte":"Das Eis ist am besten."}]},{"enonce":"Complète : « Juillet est le mois le plus chaud. »","aide":"Après *ß*, on intercale un *e* pour pouvoir prononcer.","type":"trous","segments":["Der Juli ist am ",0,"."],"banque":["heißten","heißesten","heißestes","heißsten"]},{"enonce":"Remets en ordre : « Ce que je préfère, c’est manger de la pizza. » La phrase commence par Am liebsten.","aide":"Le verbe est en deuxième position, avant le sujet.","type":"ordre","items":[{"id":"a","texte":"esse"},{"id":"b","texte":"Am liebsten"},{"id":"c","texte":"Pizza"},{"id":"d","texte":"ich"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m14"]},"explication":"**beste** : *der beste Spieler*. Devant un nom, on emploie l’article et la forme en **-ste**, qui se décline."},{"cle":{"type":"zone","ids":["m21"]},"explication":"**schnellsten** : *am schnellsten* est la forme figée, utilisée avec un verbe : elle ne se décline pas."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0"}},"explication":"Avec *sein* ou un verbe (*ist am besten*, *singt am schönsten*), la forme est figée en *am … -sten*. Devant un nom (*das beste Eis*), elle se décline."},{"cle":{"type":"trous","trous":[["heissesten"]]},"affichage":"heißesten","explication":"**am heißesten** : *heiß* finit par ß, donc on ajoute un *e* de liaison avant *-sten*."},{"cle":{"type":"ordre","ids":["b","a","d","c"]},"explication":"**Am liebsten esse ich Pizza.** *am liebsten* exprime « ce que je préfère par-dessus tout » ; il occupe la première place, donc *esse* précède *ich*."}]$ex$::jsonb),
  ('149b010e-7cf9-5452-9f66-28b46bb2ee67'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Records allemands","competence":"argumenter","situation":"Un jeune Français écrit à Tim depuis l’Allemagne. Il a noté le nombre d’habitants de quatre villes et raconte son voyage.","documents":[{"id":"staedte","type":"tableau","titre":"Vier Städte","colonnes":["Stadt","Einwohner (Millionen)"],"lignes":[["Berlin","3,7"],["Hamburg","1,9"],["München","1,5"],["Köln","1,1"]],"enteteLignes":true,"source":"Chiffres arrondis"},{"id":"reise","type":"texte","genre":"lettre","titre":"Hallo Tim","blocs":["Ich bin in Deutschland! Berlin ist die größte Stadt des Landes. München gefällt mir gut, aber Hamburg ist größer. Von allen Städten besuche ich Köln am liebsten."],"source":"Courriel écrit pour l’exercice"}],"questions":[{"enonce":"Touche le superlatif décliné devant un nom.","aide":"Il est précédé de *die*.","type":"zone","document":"reise","multiple":false},{"enonce":"Combien de millions d’habitants de plus Berlin compte-t-elle que Hambourg ?","aide":"Soustrais 1,9 à 3,7.","type":"nombre","unite":"millions"},{"enonce":"Quelle phrase est juste d’après le tableau ?","aide":"Cherche la ville qui a le moins d’habitants.","type":"choix","options":[{"id":"a","texte":"Köln ist die kleinste der vier Städte"},{"id":"b","texte":"München ist am größten von allen"},{"id":"c","texte":"Hamburg ist die größte der vier Städte"},{"id":"d","texte":"Berlin ist die kleinste der vier Städte"}],"multiple":false},{"enonce":"Complète : « La plus petite ville des quatre est Cologne. »","aide":"Devant un nom, le superlatif se décline.","type":"trous","segments":["Die ",0," Stadt der vier ist Köln."],"banque":["am kleinsten","kleinste","kleiner","kleinsten"]},{"enonce":"Remets en ordre : « Hambourg me plaît le plus. » La phrase commence par Hamburg.","aide":"*gefallen* est en deuxième position, puis le datif *mir*.","type":"ordre","items":[{"id":"a","texte":"Hamburg"},{"id":"b","texte":"gefällt"},{"id":"c","texte":"am besten"},{"id":"d","texte":"mir"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7"]},"explication":"**größte** : *die größte Stadt*. Devant un nom, on emploie article + superlatif en **-ste** ; *groß* n’a pas de *e* de liaison."},{"cle":{"type":"nombre","valeur":1.8,"tolerance":0},"affichage":"1,8 millions","explication":"**1,8 million** : 3,7 − 1,9 = 1,8."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Köln ist die kleinste der vier Städte** : 1,1 million, c’est le plus petit nombre. Le complément se dit avec *von* ou, ici, *der vier Städte*."},{"cle":{"type":"trous","trous":[["kleinste"]]},"affichage":"kleinste","explication":"**Die kleinste Stadt** : devant un nom, article + adjectif + **-ste**."},{"cle":{"type":"ordre","ids":["a","b","d","c"]},"explication":"**Hamburg gefällt mir am besten.** *gut → besser → am besten* : avec un verbe, on emploie la forme figée *am besten*."}]$ex$::jsonb),
  ('a6ba17af-0e6b-5120-b425-98e1e8f102c3'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Une visite au zoo","competence":"comprendre-langue","situation":"Tim et Zoé visitent le zoo. Observe les articles qui accompagnent les noms complément d’objet direct.","documents":[{"id":"zoo","type":"dialogue","modele":"sms","titre":"Im Zoo","participants":[{"nom":"Tim","emoji":"👦","cote":"gauche"},{"nom":"Zoé","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Tim","texte":"Im Zoo sehe ich einen Hund, eine Katze und ein Pferd."},{"qui":"Zoé","texte":"Und ich sehe den Vogel dort."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les deux articles qui montrent un nom masculin à l’accusatif.","aide":"Le masculin est le seul genre qui change entre le nominatif et l’accusatif.","type":"zone","document":"zoo","multiple":true},{"enonce":"Complète : « Je vois la table. » (masculin : der Tisch)","aide":"Le COD est à l’accusatif, et Tisch est masculin.","type":"trous","segments":["Ich sehe ",0," Tisch."],"banque":["den","des","dem","der"]},{"enonce":"Quel genre est le seul à changer entre le nominatif et l’accusatif ?","aide":"Compare der / den, ein / einen.","type":"choix","options":[{"id":"a","texte":"Le masculin"},{"id":"b","texte":"Le féminin"},{"id":"c","texte":"Le neutre"},{"id":"d","texte":"Le pluriel"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4","m14"]},"explication":"**einen** (devant *Hund*) et **den** (devant *Vogel*) : seuls les masculins changent à l’accusatif (*ein → einen*, *der → den*)."},{"cle":{"type":"trous","trous":[["den"]]},"affichage":"den","explication":"**Ich sehe den Tisch.** Accusatif masculin : *der → den*."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Le masculin seul** change : *der → den*, *ein → einen*. Féminin, neutre et pluriel gardent la même forme."}]$ex$::jsonb),
  ('a6ba17af-0e6b-5120-b425-98e1e8f102c3'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Une lettre pleine de cas","competence":"manier-langue","situation":"Une lettre de Lena à son frère mélange les quatre cas. À toi de les repérer et de justifier chaque terminaison.","documents":[{"id":"brief","type":"texte","genre":"lettre","titre":"Lenas Brief","blocs":["Ich schreibe meinem Bruder einen Brief. Der Brief liegt auf dem Tisch. Das ist das Auto des Vaters. Ich gebe jedem Kind ein Geschenk. Mit den Kindern spiele ich."],"source":"Lettre écrite pour l’exercice"}],"questions":[{"enonce":"Touche l’article au génitif, qui exprime la possession.","aide":"Cherche le complément du nom : « la voiture du père ».","type":"zone","document":"brief","multiple":false},{"enonce":"Complète la dernière phrase : « Je joue avec les enfants. »","aide":"Au datif pluriel, le nom lui-même prend une marque en plus.","type":"trous","segments":["Mit den Kinder",0," spiele ich."],"banque":["n","e","s","er"]},{"enonce":"Touche le possessif au datif : Lena écrit à qui ?","aide":"Il se décline comme « einem » devant un nom masculin.","type":"zone","document":"brief","multiple":false},{"enonce":"Associe chaque cas à sa fonction principale.","aide":"Retrouve dans la lettre : Ich (sujet), einen Brief, meinem Bruder, des Vaters.","type":"association","gauche":[{"id":"g0","texte":"Nominatif"},{"id":"g1","texte":"Accusatif"},{"id":"g2","texte":"Datif"},{"id":"g3","texte":"Génitif"}],"droite":[{"id":"d0","texte":"le complément d’objet indirect"},{"id":"d1","texte":"le complément du nom"},{"id":"d2","texte":"le complément d’objet direct"},{"id":"d3","texte":"le sujet"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m16"]},"explication":"**des** : génitif masculin (*das Auto des Vaters*), avec un -s sur le nom."},{"cle":{"type":"trous","trous":[["n"]]},"affichage":"n","explication":"**Mit den Kindern** : au datif pluriel, le nom prend un **-n** supplémentaire."},{"cle":{"type":"zone","ids":["m2"]},"explication":"**meinem** : datif masculin, car *schreiben* + COI (*meinem Bruder*). Les possessifs se déclinent comme *ein* et *kein*."},{"cle":{"type":"association","paires":{"g2":"d0","g3":"d1","g1":"d2","g0":"d3"}},"explication":"**Nominatif** = sujet, **accusatif** = COD, **datif** = COI, **génitif** = possession."}]$ex$::jsonb),
  ('a6ba17af-0e6b-5120-b425-98e1e8f102c3'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le vélo de Karl","competence":"raisonner","situation":"Mara complète le tableau de l’article défini avant de discuter du vélo de son cousin. Un bon tableau, c’est la moitié du travail.","documents":[{"id":"tab","type":"tableau","titre":"Der bestimmte Artikel","colonnes":["Fall","Maskulin","Feminin","Neutrum","Plural"],"lignes":[["Nominativ","der","die","das","die"],["Akkusativ","?","die","das","die"],["Dativ","dem","?","dem","den"],["Genitiv","des","der","des","der"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"},{"id":"rad","type":"dialogue","modele":"sms","titre":"Das Fahrrad","participants":[{"nom":"Mara","emoji":"👧","cote":"gauche"},{"nom":"Ole","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Mara","texte":"Wem gehört das Fahrrad?"},{"qui":"Ole","texte":"Das Fahrrad gehört meinem Bruder. Er fährt damit zu seinen Freunden."},{"qui":"Mara","texte":"Und das Auto vor dem Haus?"},{"qui":"Ole","texte":"Das ist das Auto meines Vaters."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Complète le tableau : accusatif masculin et datif féminin.","aide":"Le masculin est le seul genre qui change entre nominatif et accusatif.","type":"trous","segments":["Accusatif masculin : ",0," — datif féminin : ",1],"banque":["der","dem","des","den"]},{"enonce":"Touche le possessif au génitif dans la conversation.","aide":"Il suit « das Auto » et marque la possession.","type":"zone","document":"rad","multiple":false},{"enonce":"Pourquoi Ole écrit-il « meinem Bruder » et non « meinen Bruder » dans « Das Fahrrad gehört meinem Bruder » ?","aide":"Cherche le cas qui suit le verbe gehören.","type":"choix","options":[{"id":"a","texte":"Meinen est réservé au génitif"},{"id":"b","texte":"Bruder est un nom au pluriel"},{"id":"c","texte":"Le sujet est toujours au datif"},{"id":"d","texte":"Gehören se construit avec le datif"}],"multiple":false},{"enonce":"Complète : « Il roule vers ses amis. » (Freund + terminaison)","aide":"Au datif pluriel, le nom prend un -n supplémentaire ; Freund est déjà au pluriel avec -e.","type":"trous","segments":["Er fährt zu seinen Freund",0,"."],"banque":["e","en","s","er"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"trous","trous":[["den"],["der"]]},"affichage":"den · der","explication":"**den** (accusatif masculin) et **der** (datif féminin : *der Frau*)."},{"cle":{"type":"zone","ids":["m25"]},"explication":"**meines** : génitif masculin de *mein* (*meines Vaters*), avec -es sur le possessif et -s sur le nom."},{"cle":{"type":"choix","ids":["d"]},"explication":"**gehören** exige le datif : *meinem Bruder* (datif masculin de *mein*)."},{"cle":{"type":"trous","trous":[["en"]]},"affichage":"en","explication":"**Freunden** : pluriel *Freunde* + **-n** au datif pluriel."}]$ex$::jsonb),
  ('9ac65504-f599-5b22-b227-603400d2217b'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le petit renard","competence":"comprendre-langue","situation":"Un conte raconte l’histoire d’un renard et d’une pomme. Les contes se racontent au prétérit : repère-le.","documents":[{"id":"conte","type":"texte","genre":"recit","titre":"Der kleine Fuchs","blocs":["Es war einmal ein kleiner Fuchs. Er ging durch den Wald und fand einen Apfel. Er nahm ihn und kam nach Hause. Dort sah er seine Mutter und gab ihr den Apfel."],"source":"Conte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les prétérits de « gehen » et de « finden ».","aide":"Ce sont deux verbes forts : la voyelle a changé.","type":"zone","document":"conte","multiple":true},{"enonce":"Associe chaque infinitif à son prétérit, tel qu’il apparaît dans le conte.","aide":"Dans le conte, retrouve la forme de chaque verbe.","type":"association","gauche":[{"id":"g0","texte":"kommen"},{"id":"g1","texte":"sehen"},{"id":"g2","texte":"geben"},{"id":"g3","texte":"nehmen"}],"droite":[{"id":"d0","texte":"kam"},{"id":"d1","texte":"gab"},{"id":"d2","texte":"sah"},{"id":"d3","texte":"nahm"}]},{"enonce":"Complète : « Il était une fois un renard. »","aide":"C’est le prétérit de sein.","type":"trous","segments":["Es ",0," einmal ein Fuchs."],"banque":["wurde","ist","hatte","war"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7","m12"]},"explication":"**ging** (*gehen*) et **fand** (*finden*) : verbes forts, voyelle modifiée et aucune terminaison à la 3e personne."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2","g3":"d3"}},"explication":"**kam**, **sah**, **gab**, **nahm** : des prétérits forts, sans terminaison à la 3e personne du singulier."},{"cle":{"type":"trous","trous":[["war"]]},"affichage":"war","explication":"**Es war einmal ein Fuchs.** *war* est le prétérit de *sein*."}]$ex$::jsonb),
  ('9ac65504-f599-5b22-b227-603400d2217b'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Où étais-tu hier ?","competence":"analyser-document","situation":"Eva et Jonas échangent des SMS. Observe quels verbes sont au prétérit et lesquels sont au parfait.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Gestern","participants":[{"nom":"Eva","emoji":"👧","cote":"gauche"},{"nom":"Jonas","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Eva","texte":"Wo warst du gestern? Ich konnte dich nicht erreichen."},{"qui":"Jonas","texte":"Ich war bei Oma. Ich hatte kein Handy dabei."},{"qui":"Eva","texte":"Und was habt ihr gemacht?"},{"qui":"Jonas","texte":"Wir haben Karten gespielt, und ich musste Kuchen essen."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les cinq prétérits : ce sont les seuls que la langue parlée garde.","aide":"Cherche les formes de sein, haben et des modaux.","type":"zone","document":"sms","multiple":true},{"enonce":"Pourquoi Jonas dit-il « Wir haben Karten gespielt » plutôt que « Wir spielten Karten » ?","aide":"Les verbes ordinaires se racontent au parfait dans un message.","type":"choix","options":[{"id":"a","texte":"Parce que Karten est au pluriel et exige le parfait"},{"id":"b","texte":"À l’oral on raconte au parfait, sauf avec sein, haben et les modaux"},{"id":"c","texte":"Parce que spielen est un verbe fort qui n’a pas de prétérit"},{"id":"d","texte":"Parce que le prétérit n’existe pas pour les verbes faibles"}],"multiple":false},{"enonce":"Complète avec « sein » et « haben » : « Où étiez-vous hier, et aviez-vous faim ? »","aide":"Ihr : le prétérit se termine par -t pour ihr.","type":"trous","segments":["Wo ",0," ihr gestern, und ",1," ihr Hunger?"],"banque":["wart","hattet","waren","hatten"]},{"enonce":"Associe chaque modal à son prétérit.","aide":"Pas d’inflexion : on enlève le tréma et on ajoute -te.","type":"association","gauche":[{"id":"g0","texte":"können"},{"id":"g1","texte":"dürfen"},{"id":"g2","texte":"müssen"},{"id":"g3","texte":"wollen"}],"droite":[{"id":"d0","texte":"wollte"},{"id":"d1","texte":"durfte"},{"id":"d2","texte":"konnte"},{"id":"d3","texte":"musste"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1","m5","m10","m14","m29"]},"explication":"**warst, war, hatte, konnte, musste** : *sein*, *haben* et les modaux gardent le prétérit à l’oral."},{"cle":{"type":"choix","ids":["b"]},"explication":"À l’oral, on raconte au **parfait**. Seuls *sein*, *haben*, *werden* et les modaux gardent le prétérit."},{"cle":{"type":"trous","trous":[["wart"],["hattet"]]},"affichage":"wart · hattet","explication":"**Wo wart ihr gestern, und hattet ihr Hunger?** *ihr wart*, *ihr hattet*."},{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g0":"d2","g2":"d3"}},"explication":"Prétérit des modaux : **konnte, durfte, musste, wollte** : sans inflexion, avec *-te*."}]$ex$::jsonb),
  ('9ac65504-f599-5b22-b227-603400d2217b'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Récit écrit, message oral","competence":"raisonner","situation":"Lea raconte sa soirée deux fois : dans un petit récit écrit, puis dans un message à Max. Compare les temps utilisés.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"Ein langer Abend","blocs":["Nachdem Lea nach Hause gekommen war, aß sie schnell. Sie hatte lange gearbeitet. Dann nahm sie ihr Buch und las bis elf Uhr. Am nächsten Morgen blieb sie lange im Bett, weil sie spät eingeschlafen war."],"source":"Récit écrit pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Max fragt","participants":[{"nom":"Max","emoji":"👦","cote":"gauche"},{"nom":"Lea","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Max","texte":"Wie war dein Abend?"},{"qui":"Lea","texte":"Ich habe bis elf gelesen. Ich bin spät eingeschlafen."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les trois auxiliaires du plus-que-parfait.","aide":"Ce sont des prétérits de sein ou de haben suivis d’un participe II.","type":"zone","document":"recit","multiple":true},{"enonce":"Remets en ordre : « Après que Tom avait travaillé, il mangea. » La phrase commence par Nachdem.","aide":"Après nachdem, le plus-que-parfait finit la subordonnée ; ensuite, le verbe de la principale ouvre.","type":"ordre","items":[{"id":"a","texte":"Nachdem"},{"id":"b","texte":"hatte"},{"id":"c","texte":"er"},{"id":"d","texte":"gearbeitet"},{"id":"e","texte":"Tom"},{"id":"f","texte":"aß"}]},{"enonce":"Range ces verbes selon la famille de leur prétérit.","aide":"Faible : -te seulement. Fort : voyelle changée. Mixte : les deux.","type":"categories","categories":[{"id":"c0","texte":"Faible"},{"id":"c1","texte":"Fort"},{"id":"c2","texte":"Mixte"}],"items":[{"id":"i0","texte":"lernen → lernte"},{"id":"i1","texte":"denken → dachte"},{"id":"i2","texte":"gehen → ging"},{"id":"i3","texte":"bringen → brachte"},{"id":"i4","texte":"spielen → spielte"},{"id":"i5","texte":"nehmen → nahm"}]},{"enonce":"Les deux documents racontent la même soirée. Pourquoi ne choisissent-ils pas le même temps ?","aide":"Compare un récit écrit à un SMS : le registre change.","type":"choix","options":[{"id":"a","texte":"Lea est une enfant, Max un adulte : l’âge décide du temps"},{"id":"b","texte":"Le prétérit est réservé aux verbes forts, le parfait aux faibles"},{"id":"c","texte":"Après nachdem, le prétérit est toujours remplacé par le parfait"},{"id":"d","texte":"Le récit écrit se raconte au prétérit, le message oral au parfait"}],"multiple":false},{"enonce":"Touche les deux auxiliaires du parfait dans le message de Lea.","aide":"Ils sont devant gelesen et eingeschlafen.","type":"zone","document":"sms","multiple":true}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5","m10","m35"]},"explication":"**war** (… gekommen), **hatte** (… gearbeitet), **war** (… eingeschlafen) : prétérit de l’auxiliaire + participe II."},{"cle":{"type":"ordre","ids":["a","e","d","b","f","c"]},"explication":"**Nachdem Tom gearbeitet hatte, aß er.** Subordonnée : participe puis auxiliaire à la fin ; principale : verbe avant le sujet."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c2","i2":"c1","i3":"c2","i4":"c0","i5":"c1"}},"explication":"**Faibles** : *spielte, lernte* ; **forts** : *ging, nahm* ; **mixtes** : *brachte, dachte* (radical modifié et terminaison -te)."},{"cle":{"type":"choix","ids":["d"]},"explication":"En allemand, **prétérit** et **parfait** s’opposent par le registre : écrit narratif pour l’un, oral et messages pour l’autre."},{"cle":{"type":"zone","ids":["m5","m10"]},"explication":"**habe** (… gelesen) et **bin** (… eingeschlafen) : auxiliaires du parfait ; *einschlafen* est un changement d’état, donc *sein*."}]$ex$::jsonb),
  ('5b05b29b-e67a-511e-b421-791e84f8f39c'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La famille de Lena","competence":"comprendre-langue","situation":"Lena présente sa famille à sa nouvelle classe. Observe les petits mots qui disent « mon », « ma » ou « notre ».","documents":[{"id":"fam","type":"texte","genre":"recit","titre":"Meine Familie","blocs":["Das ist meine Familie. Mein Vater heißt Karl, meine Mutter heißt Eva. Unser Hund heißt Rex."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche le possessif qui veut dire « notre ».","aide":"Il ne commence pas par m-.","type":"zone","document":"fam","multiple":false},{"enonce":"Associe chaque possessif à son sens.","aide":"*euer* s’adresse à plusieurs personnes que l’on tutoie.","type":"association","gauche":[{"id":"g0","texte":"mein"},{"id":"g1","texte":"dein"},{"id":"g2","texte":"unser"},{"id":"g3","texte":"euer"}],"droite":[{"id":"d0","texte":"notre"},{"id":"d1","texte":"votre"},{"id":"d2","texte":"mon"},{"id":"d3","texte":"ton"}]},{"enonce":"Complète : « Voici mon frère et voici ma sœur. »","aide":"Le possessif se décline comme *ein* : un -e pour le féminin.","type":"trous","segments":["Das ist ",0," Bruder und das ist ",1," Schwester."],"banque":["mein","meine","meinen","meiner"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m12"]},"explication":"**Unser** : *unser Hund* = « notre chien »."},{"cle":{"type":"association","paires":{"g2":"d0","g3":"d1","g0":"d2","g1":"d3"}},"explication":"*mein* = mon, *dein* = ton, *unser* = notre, *euer* = votre (à plusieurs amis)."},{"cle":{"type":"trous","trous":[["mein"],["meine"]]},"affichage":"mein · meine","explication":"**mein Bruder** (masculin, sans terminaison) et **meine Schwester** (féminin, -e)."}]$ex$::jsonb),
  ('5b05b29b-e67a-511e-b421-791e84f8f39c'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"La fête de l’école","competence":"manier-langue","situation":"C’est la fête de l’école. Un article de présentation dit avec qui chacun arrive : à chaque fois, il faut regarder QUI possède et CE QUI est possédé.","documents":[{"id":"fest","type":"texte","genre":"article","titre":"Schulfest","blocs":["Heute ist Schulfest. Anna kommt mit ihrem Bruder. Peter kommt mit seiner Schwester. Die Kinder spielen mit ihren Freunden."],"source":"Article écrit pour l’exercice"}],"questions":[{"enonce":"Touche le possessif qui renvoie à un garçon, Peter.","aide":"Son radical commence par *s-*.","type":"zone","document":"fest","multiple":false},{"enonce":"Touche le possessif qui renvoie à Anna.","aide":"Son radical est *ihr-*.","type":"zone","document":"fest","multiple":false},{"enonce":"Pourquoi « seiner » finit-il par -er ?","aide":"La terminaison dépend de l’objet possédé, pas du possesseur.","type":"choix","options":[{"id":"a","texte":"Peter est un homme, donc la terminaison est -er"},{"id":"b","texte":"Mit demande le génitif, d’où la terminaison -er"},{"id":"c","texte":"Schwester est féminin, et le nom est au datif"},{"id":"d","texte":"Le possesseur est neutre, donc on met -er"}],"multiple":false},{"enonce":"Complète : « Avez-vous vu vos parents ? » (on tutoie plusieurs amis)","aide":"*euer* perd son e devant une terminaison.","type":"trous","segments":["Habt ihr ",0," Eltern gesehen?"],"banque":["euere","euer","eure","eurer"]},{"enonce":"Remets en ordre : « Il met son manteau. » La phrase commence par Er.","aide":"Avec un vêtement, l’allemand emploie l’article et non le possessif.","type":"ordre","items":[{"id":"a","texte":"an"},{"id":"b","texte":"sich"},{"id":"c","texte":"zieht"},{"id":"d","texte":"Er"},{"id":"e","texte":"den Mantel"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m11"]},"explication":"**seiner** : le radical *sein-* vient du possesseur (Peter, un homme)."},{"cle":{"type":"zone","ids":["m6"]},"explication":"**ihrem** : le radical *ihr-* vient du possesseur (Anna, une femme) ; *-em* vient de *der Bruder* au datif."},{"cle":{"type":"choix","ids":["c"]},"explication":"La terminaison suit l’**objet possédé** : *Schwester* est féminin et au datif après *mit* ; le radical *sein-* suit le possesseur."},{"cle":{"type":"trous","trous":[["eure"]]},"affichage":"eure","explication":"**Habt ihr eure Eltern gesehen?** *euer* devient *eur-* devant une terminaison, et le pluriel prend **-e**."},{"cle":{"type":"ordre","ids":["d","c","b","e","a"]},"explication":"**Er zieht sich den Mantel an.** Pas de possessif : *den Mantel* + *sich* (datif) disent « son manteau »."}]$ex$::jsonb),
  ('5b05b29b-e67a-511e-b421-791e84f8f39c'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Au bureau des objets trouvés","competence":"raisonner","situation":"Au bureau des objets trouvés, Herr Braun vérifie à qui appartiennent plusieurs affaires. Un tableau rappelle qui est le propriétaire de chaque objet.","documents":[{"id":"fund","type":"dialogue","modele":"sms","titre":"Im Fundbüro","participants":[{"nom":"Herr Braun","emoji":"👨","cote":"gauche"},{"nom":"Frau Weiß","emoji":"👩","cote":"droite"}],"repliques":[{"qui":"Herr Braun","texte":"Guten Tag, Frau Weiß. Ist das Ihre Jacke?"},{"qui":"Frau Weiß","texte":"Nein, meine Jacke ist grün. Aber das ist die Mütze von meinem Sohn."},{"qui":"Herr Braun","texte":"Und der Schirm? Gehört er Ihrem Mann?"},{"qui":"Frau Weiß","texte":"Ja, das ist seiner. Und die Handschuhe sind unsere."}],"source":"Dialogue écrit pour l’exercice"},{"id":"liste","type":"tableau","titre":"Liste des objets","colonnes":["Objet","Genre","Propriétaire"],"lignes":[["die Tasche","féminin","Frau Weiß"],["das Handy","neutre","Lena, sa fille"],["die Schlüssel","pluriel","Ben, son fils"]],"source":"Liste écrite pour l’exercice"}],"questions":[{"enonce":"Touche les deux possessifs de politesse (« votre »).","aide":"Ils s’écrivent avec une majuscule, au milieu de la phrase.","type":"zone","document":"fund","multiple":true},{"enonce":"Touche les deux possessifs employés seuls, sans nom derrière.","aide":"Ils répondent à « À qui est-ce ? ».","type":"zone","document":"fund","multiple":true},{"enonce":"Herr Braun parle des propriétaires à un collègue. Complète d’après la liste.","aide":"Radical d’après le possesseur (femme ou homme), terminaison d’après l’objet (genre).","type":"trous","segments":["Das ist ",0," Tasche. Das ist ",1," Handy. Das sind ",2," Schlüssel."],"banque":["ihrem","ihre","ihr","sein","seine"]},{"enonce":"Pourquoi « Ihre Jacke » prend-il une majuscule dans le dialogue ?","aide":"Regarde à qui Herr Braun s’adresse.","type":"choix","options":[{"id":"a","texte":"Ihre veut dire « leur » et prend toujours une majuscule"},{"id":"b","texte":"Herr Braun vouvoie Frau Weiß : c’est la politesse"},{"id":"c","texte":"Ihre est un nom propre dans cette phrase"},{"id":"d","texte":"Ihre est placé juste après un point"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6","m26"]},"explication":"**Ihre** et **Ihrem** : Herr Braun vouvoie Frau Weiß, donc *Ihr-* prend une majuscule."},{"cle":{"type":"zone","ids":["m31","m36"]},"explication":"**seiner** et **unsere** : employé seul, le possessif prend les terminaisons de l’article défini (*das ist seiner*)."},{"cle":{"type":"trous","trous":[["ihre"],["ihr"],["seine"]]},"affichage":"ihre · ihr · seine","explication":"**ihre Tasche** (Frau Weiß, *Tasche* féminin), **ihr Handy** (Lena, *Handy* neutre : pas de terminaison), **seine Schlüssel** (Ben, pluriel)."},{"cle":{"type":"choix","ids":["b"]},"explication":"Quand on **vouvoie**, le possessif s’écrit avec une majuscule : *Ihre Jacke* = « votre veste ». Sans majuscule, *ihre* voudrait dire « sa » (à elle) ou « leur »."}]$ex$::jsonb),
  ('e784b9c4-b74b-551e-b1ab-4289cdf67844'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Que font Pia et Ali samedi ?","competence":"comprendre-langue","situation":"Pia et Ali échangent des messages sur leurs projets du week-end. Observe où se trouve le verbe dans chaque phrase.","documents":[{"id":"plaene","type":"dialogue","modele":"sms","titre":"Pläne fürs Wochenende","participants":[{"nom":"Pia","emoji":"👧","cote":"gauche"},{"nom":"Ali","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Pia","texte":"Was machst du am Samstag?"},{"qui":"Ali","texte":"Am Samstag fahre ich nach Köln."},{"qui":"Pia","texte":"Toll! Ich bleibe zu Hause."},{"qui":"Ali","texte":"Heute Abend spiele ich Fußball."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les quatre verbes conjugués de la conversation.","aide":"Cherche le mot qui change avec la personne : machst, fahre…","type":"zone","document":"plaene","multiple":true},{"enonce":"Dans « Am Samstag fahre ich nach Köln », qu’y a-t-il à la première place, devant le verbe ?","aide":"La règle compte des groupes, pas des mots.","type":"choix","options":[{"id":"a","texte":"Le groupe « Am Samstag », en deux mots"},{"id":"b","texte":"Le verbe « fahre » lui-même, seul"},{"id":"c","texte":"Le sujet « ich », toujours premier"},{"id":"d","texte":"Le seul mot « Samstag », sans « am »"}],"multiple":false},{"enonce":"Remets les éléments dans l’ordre pour dire « Demain, je vais à Berlin ». La phrase commence par Morgen.","aide":"Le verbe conjugué est toujours deuxième. Où passe donc le sujet ?","type":"ordre","items":[{"id":"a","texte":"nach Berlin"},{"id":"b","texte":"ich"},{"id":"c","texte":"Morgen"},{"id":"d","texte":"fahre"}]},{"enonce":"Complète la phrase : « Aujourd’hui, je vais au cinéma. »","aide":"Le sujet est « ich » : quelle terminaison au présent ?","type":"trous","segments":["Heute ",0," ich ins Kino."],"banque":["geht","gehen","gehst","gehe"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1","m7","m13","m18"]},"explication":"Les verbes conjugués sont **machst, fahre, bleibe, spiele**. Dans chaque phrase, ils sont à la deuxième place."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le verbe occupe la deuxième **place**, non le deuxième mot : « Am Samstag » forme un seul groupe, et *fahre* vient juste derrière."},{"cle":{"type":"ordre","ids":["c","d","b","a"]},"explication":"**Morgen fahre ich nach Berlin.** Le groupe *Morgen* ouvre la phrase, le verbe suit, le sujet passe derrière : c’est l’inversion."},{"cle":{"type":"trous","trous":[["gehe"]]},"affichage":"gehe","explication":"**Heute gehe ich ins Kino.** *Heute* ouvre la phrase, le verbe conjugué *gehe* est deuxième, le sujet *ich* passe derrière."}]$ex$::jsonb),
  ('e784b9c4-b74b-551e-b1ab-4289cdf67844'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le courriel à Oma","competence":"manier-langue","situation":"Tom écrit à sa grand-mère pour lui raconter sa semaine. Dans chaque phrase, le verbe est en deux morceaux : l’un à la deuxième place, l’autre à la fin.","documents":[{"id":"oma","type":"texte","genre":"lettre","titre":"Die E-Mail an Oma","blocs":["Liebe Oma,","gestern habe ich einen Film gesehen. Heute muss ich Hausaufgaben machen. Morgen stehe ich früh auf.","Liebe Grüße\nTom"],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les trois mots qui ferment une phrase du courriel : un participe, un infinitif et un préverbe.","aide":"Cherche le dernier mot de chacune des trois phrases (avant le point).","type":"zone","document":"oma","multiple":true},{"enonce":"Quel type de « parenthèse verbale » forme « habe … gesehen » ?","aide":"Regarde l’auxiliaire « habe » et la forme du dernier mot.","type":"choix","options":[{"id":"a","texte":"Un verbe à préverbe séparable"},{"id":"b","texte":"Un modal suivi d’un infinitif"},{"id":"c","texte":"Une subordonnée avec le verbe à la fin"},{"id":"d","texte":"Un temps composé : auxiliaire puis participe"}],"multiple":false},{"enonce":"Remets les éléments en ordre : « Ce soir, je dois travailler. » La phrase commence par Heute Abend.","aide":"Le modal est conjugué en deuxième place, l’infinitif part à la fin.","type":"ordre","items":[{"id":"a","texte":"Heute Abend"},{"id":"b","texte":"arbeiten"},{"id":"c","texte":"muss"},{"id":"d","texte":"ich"}]},{"enonce":"Complète : « Je me lève à sept heures demain. » (aufstehen)","aide":"Le verbe se coupe en deux : le radical conjugué d’abord, le préverbe à la toute fin.","type":"trous","segments":["Ich ",0," morgen um sieben Uhr ",1,"."],"banque":["auf","steht","an","stehe"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7","m12","m17"]},"explication":"**gesehen** (participe), **machen** (infinitif avec muss) et **auf** (préverbe de *aufstehen*) ferment chacun leur phrase."},{"cle":{"type":"choix","ids":["d"]},"explication":"**habe … gesehen** : l’auxiliaire *haben* est à la deuxième place, le participe passé *gesehen* ferme la phrase."},{"cle":{"type":"ordre","ids":["a","c","d","b"]},"explication":"**Heute Abend muss ich arbeiten.** Le modal *muss* est deuxième, le sujet suit, et l’infinitif *arbeiten* ferme la phrase."},{"cle":{"type":"trous","trous":[["stehe"],["auf"]]},"affichage":"stehe · auf","explication":"**Ich stehe morgen um sieben Uhr auf.** *stehe* est à la deuxième place, le préverbe *auf* est rejeté en fin de phrase."}]$ex$::jsonb),
  ('e784b9c4-b74b-551e-b1ab-4289cdf67844'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le voyage de Selin","competence":"raisonner","situation":"Selin organise un voyage et offre des cadeaux. Utilise l’agenda et la conversation pour construire des phrases à l’ordre irréprochable.","documents":[{"id":"reise","type":"tableau","titre":"Selins Reiseplan","colonnes":["Wie?","Wohin?","Wann?","Warum?"],"lignes":[["mit dem Zug","nach München","morgen","wegen der Arbeit"]],"enteteLignes":false,"source":"Agenda écrit pour l’exercice"},{"id":"geschenk","type":"dialogue","modele":"sms","titre":"Geschenke","participants":[{"nom":"Selin","emoji":"👧","cote":"gauche"},{"nom":"Tom","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Selin","texte":"Was schenkst du Oma?"},{"qui":"Tom","texte":"Ich gebe der Oma das Buch."},{"qui":"Selin","texte":"Und das Heft?"},{"qui":"Tom","texte":"Ich gebe es dem Opa."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche, dans l’agenda, la case qui donne la cause du voyage.","aide":"La cause répond à la question « Warum ? ».","type":"zone","document":"reise","multiple":false},{"enonce":"Selin dit son voyage dans l’ordre neutre. Complète la phrase « Ich fahre… » avec les quatre compléments de l’agenda.","aide":"Retiens TeKaMoLo : temps, cause, manière, lieu.","type":"ordre","items":[{"id":"a","texte":"nach München"},{"id":"b","texte":"morgen"},{"id":"c","texte":"wegen der Arbeit"},{"id":"d","texte":"mit dem Zug"}]},{"enonce":"Touche le pronom qui a pris la place d’un nom accusatif et se trouve donc devant le datif « dem Opa ».","aide":"Il remplace « das Heft » et se place juste après le verbe.","type":"zone","document":"geschenk","multiple":false},{"enonce":"Comment dire « Je le lui donne » (le livre, à Oma) ?","aide":"Quand l’accusatif est un pronom, il passe devant le datif.","type":"choix","options":[{"id":"a","texte":"Ich gebe es ihr."},{"id":"b","texte":"Ich gebe ihr das."},{"id":"c","texte":"Ich gebe ihr es."},{"id":"d","texte":"Ich ihr gebe es."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c3"]},"explication":"**wegen der Arbeit** répond à *Warum ?* : c’est le complément de cause (Ka)."},{"cle":{"type":"ordre","ids":["b","c","d","a"]},"explication":"**Ich fahre morgen wegen der Arbeit mit dem Zug nach München.** Ordre TeKaMoLo : Temps, Cause, Manière, Lieu."},{"cle":{"type":"zone","ids":["m15"]},"explication":"**es** remplace *das Heft* : un accusatif pronom passe devant le datif — *Ich gebe es dem Opa* — alors que deux noms suivent l’ordre datif puis accusatif."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Ich gebe es ihr.** Le pronom accusatif *es* se place immédiatement après le verbe, devant le datif *ihr*."}]$ex$::jsonb),
  ('b462d66b-b245-59dd-b171-d0f387a69259'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les voisins de la rue","competence":"comprendre-langue","situation":"Dans sa rue, Clara présente ses voisins. Elle les décrit avec de petites phrases relatives.","documents":[{"id":"nachbarn","type":"texte","genre":"recit","titre":"Unsere Straße","blocs":["Hier wohnt Herr Maier, der Klavier spielt. Gegenüber wohnt Frau Koch, die jeden Morgen Zeitung liest. Dort steht das Haus, das ganz neu ist."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche le pronom relatif qui reprend « Frau Koch ».","aide":"Le pronom suit la virgule qui vient après le nom de la voisine.","type":"zone","document":"nachbarn","multiple":false},{"enonce":"Pourquoi Clara emploie-t-elle « der » dans « Herr Maier, der Klavier spielt » ?","aide":"Pense au genre de Herr Maier et à la fonction du pronom devant « spielt ».","type":"choix","options":[{"id":"a","texte":"Le verbe spielt exige toujours le mot der"},{"id":"b","texte":"L’antécédent est masculin et le pronom est sujet"},{"id":"c","texte":"Herr Maier est au datif dans la phrase"},{"id":"d","texte":"Klavier est un nom masculin placé après le verbe"}],"multiple":false},{"enonce":"Complète : « Là-bas se trouve la maison qui est toute neuve. »","aide":"L’antécédent est « das Haus », neutre, sujet de la relative.","type":"trous","segments":["Dort steht das Haus, ",0," ganz neu ist."],"banque":["das","der","den","die"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m11"]},"explication":"**die** : l’antécédent *Frau Koch* est féminin, et il est sujet de *liest* (nominatif)."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le pronom prend le **genre de l’antécédent** (masculin) et le **cas de sa fonction** (sujet, nominatif) : **der**."},{"cle":{"type":"trous","trous":[["das"]]},"affichage":"das","explication":"**das** : *Haus* est neutre et sujet de *ist* (nominatif neutre : das)."}]$ex$::jsonb),
  ('b462d66b-b245-59dd-b171-d0f387a69259'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Le voisin dont tout le monde parle","competence":"manier-langue","situation":"Jule décrit sa famille de voisins. Chaque relative a son propre cas : prends le temps de chercher la fonction du pronom.","documents":[{"id":"nachbar","type":"texte","genre":"recit","titre":"Mein Nachbar","blocs":["Mein Nachbar ist ein Mann, den alle mögen. Seine Frau ist eine Lehrerin, der ich oft helfe. Ihre Kinder, die sehr laut sind, spielen im Garten. Sie haben einen Hund, mit dem ich gern spazieren gehe."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche le pronom relatif au datif féminin : la voisine à qui Jule rend service.","aide":"Le verbe helfen est suivi du datif ; l’antécédent est féminin.","type":"zone","document":"nachbar","multiple":false},{"enonce":"Associe chaque relative à la fonction de son pronom.","aide":"Demande-toi quelle fonction le pronom a DANS la relative.","type":"association","gauche":[{"id":"g0","texte":"den alle mögen"},{"id":"g1","texte":"der ich oft helfe"},{"id":"g2","texte":"die sehr laut sind"},{"id":"g3","texte":"mit dem ich spazieren gehe"}],"droite":[{"id":"d0","texte":"après la préposition mit (datif)"},{"id":"d1","texte":"complément d’objet direct (accusatif)"},{"id":"d2","texte":"sujet (nominatif pluriel)"},{"id":"d3","texte":"complément d’objet indirect (datif)"}]},{"enonce":"Complète : « C’est l’amie à qui je donne le livre, et l’ami avec qui je voyage. »","aide":"Datif féminin pour la première, datif masculin (après mit) pour la seconde.","type":"trous","segments":["Das ist die Freundin, ",0," ich das Buch gebe, und der Freund, mit ",1," ich fahre."],"banque":["den","die","dem","der"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m13"]},"explication":"**der** : *Lehrerin* est féminin et *helfen* se construit avec le datif, donc datif féminin = *der*."},{"cle":{"type":"association","paires":{"g3":"d0","g0":"d1","g2":"d2","g1":"d3"}},"explication":"**den** = COD (acc. masc.), **der** = COI (dat. fém.), **die** = sujet (pluriel), **dem** = datif imposé par *mit*."},{"cle":{"type":"trous","trous":[["der"],["dem"]]},"affichage":"der · dem","explication":"**der** (datif féminin : on donne à *die Freundin*) et **dem** (datif masculin, imposé par *mit*)."}]$ex$::jsonb),
  ('b462d66b-b245-59dd-b171-d0f387a69259'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le sac trouvé à l’école","competence":"raisonner","situation":"Un élève a trouvé un sac à dos dans la cour. Une note d’information du secrétariat explique ce qu’il faut faire.","documents":[{"id":"fund","type":"texte","genre":"article","titre":"Fundsache","blocs":["Ein Schüler hat gestern einen Rucksack gefunden, dessen Besitzer unbekannt ist. Die Lehrerin, deren Büro neben dem Eingang liegt, bewahrt ihn auf. Alles, was im Rucksack ist, steht auf einer Liste. Der Schüler kam zu spät, was die Lehrerin geärgert hat."],"source":"Note écrite pour l’exercice"}],"questions":[{"enonce":"Touche les deux pronoms relatifs au génitif.","aide":"Ils expriment l’appartenance : « dont le propriétaire », « dont le bureau ».","type":"zone","document":"fund","multiple":true},{"enonce":"Pourquoi écrit-on « Alles, was im Rucksack ist » et non « Alles, das… » ?","aide":"Pense à « alles », « nichts », « etwas ».","type":"choix","options":[{"id":"a","texte":"Rucksack est masculin, donc il faut un autre pronom"},{"id":"b","texte":"Après alles, nichts ou etwas, le relatif est was"},{"id":"c","texte":"Après un pluriel, was remplace toujours das"},{"id":"d","texte":"Das ne s’emploie jamais dans une proposition relative"}],"multiple":false},{"enonce":"Touche le « was » qui reprend toute la proposition précédente (« Der Schüler kam zu spät »).","aide":"Un seul des deux « was » reprend une phrase entière plutôt qu’un mot comme « alles ».","type":"zone","document":"fund","multiple":false},{"enonce":"Remets en ordre la relative : « Der Mann, … » (« dont la voiture est en panne »).","aide":"Après dessen, le nom n’a pas d’article ; le verbe va à la fin.","type":"ordre","items":[{"id":"a","texte":"dessen"},{"id":"b","texte":"kaputt"},{"id":"c","texte":"Auto"},{"id":"d","texte":"ist"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7","m13"]},"explication":"**dessen** (masculin) et **deren** (féminin) sont au génitif : « dont le… ». Le nom qui suit n’a pas d’article."},{"cle":{"type":"choix","ids":["b"]},"explication":"Après **alles, nichts, etwas, viel, wenig**, le pronom relatif est **was**."},{"cle":{"type":"zone","ids":["m36"]},"explication":"**was** (après « zu spät, ») reprend toute la phrase précédente : il signifie « ce qui »."},{"cle":{"type":"ordre","ids":["a","c","b","d"]},"explication":"**Der Mann, dessen Auto kaputt ist** : *dessen* + nom sans article, et le verbe conjugué ferme la relative."}]$ex$::jsonb),
  ('65318149-e09d-5271-a9c8-888224569afe'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Au marché aux puces","competence":"comprendre-langue","situation":"Aux puces, un vendeur et un client discutent. Observe comment ils montrent les objets.","documents":[{"id":"flohmarkt","type":"dialogue","modele":"sms","titre":"Auf dem Flohmarkt","participants":[{"nom":"Verkäufer","emoji":"🧑","cote":"gauche"},{"nom":"Kunde","emoji":"🙂","cote":"droite"}],"repliques":[{"qui":"Verkäufer","texte":"Dieses Buch kostet drei Euro."},{"qui":"Kunde","texte":"Und diese Lampe?"},{"qui":"Verkäufer","texte":"Diese Lampe kostet fünf Euro."},{"qui":"Kunde","texte":"Ich nehme diesen Stuhl."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le démonstratif à l’accusatif masculin.","aide":"Le démonstratif suit les terminaisons de l’article défini : der → den.","type":"zone","document":"flohmarkt","multiple":false},{"enonce":"Complète : « Je prends ce livre. » (das Buch)","aide":"Buch est neutre, accusatif neutre = nominatif neutre.","type":"trous","segments":["Ich nehme ",0," Buch."],"banque":["dieser","dieses","diesen","diese"]},{"enonce":"Avec quelles terminaisons se décline « dieser » ?","aide":"Compare dieser / der, diesen / den.","type":"choix","options":[{"id":"a","texte":"Aucune, il est invariable"},{"id":"b","texte":"Celles de l’article défini"},{"id":"c","texte":"Celles de l’article indéfini"},{"id":"d","texte":"Celles d’un adjectif"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m15"]},"explication":"**diesen** : accusatif masculin de *dieser*, comme *den* pour *der*."},{"cle":{"type":"trous","trous":[["dieses"]]},"affichage":"dieses","explication":"**dieses Buch** : neutre, la terminaison est celle de l’article défini *das* → *-es*."},{"cle":{"type":"choix","ids":["b"]},"explication":"**dieser** prend les terminaisons de l’article défini : *dieser, diesen, diesem, dieses*."}]$ex$::jsonb),
  ('65318149-e09d-5271-a9c8-888224569afe'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"« Den kenne ich gut ! »","competence":"manier-langue","situation":"Anna et Ben parlent de leurs camarades. Dans la langue de tous les jours, on montre quelqu’un avec der, die, das.","documents":[{"id":"kennen2","type":"dialogue","modele":"sms","titre":"Wer ist Peter?","participants":[{"nom":"Anna","emoji":"👧","cote":"gauche"},{"nom":"Ben","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Anna","texte":"Kennst du Peter?"},{"qui":"Ben","texte":"Den kenne ich gut! Mit dem spiele ich Fußball."},{"qui":"Anna","texte":"Und Lea?"},{"qui":"Ben","texte":"Die kenne ich nicht. Aber von der habe ich viel gehört."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le démonstratif accentué à l’accusatif masculin qui reprend « Peter ».","aide":"Il ouvre la phrase de Ben, comme un « Lui, je le connais bien ! ».","type":"zone","document":"kennen2","multiple":false},{"enonce":"Pourquoi Ben dit-il « Mit dem spiele ich Fußball » et non « Mit den » ?","aide":"Repère la préposition et le genre de la personne.","type":"choix","options":[{"id":"a","texte":"Mit exige l’accusatif, et Peter est pluriel"},{"id":"b","texte":"Mit exige le datif, et Peter est masculin"},{"id":"c","texte":"Dem est la forme du nominatif masculin"},{"id":"d","texte":"Peter est neutre, donc dem est obligatoire"}],"multiple":false},{"enonce":"Touche les deux démonstratifs qui désignent Lea.","aide":"Un à l’accusatif féminin, l’autre au datif féminin après von.","type":"zone","document":"kennen2","multiple":true},{"enonce":"Complète : « Je ne connais pas les enfants. Je ne parle jamais avec eux. »","aide":"Le démonstratif au datif pluriel a une forme particulière.","type":"trous","segments":["Die Kinder kenne ich nicht. Mit ",0," spreche ich nie."],"banque":["dem","den","denen","die"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3"]},"explication":"**Den kenne ich gut !** : *den* est le démonstratif accentué, accusatif masculin ; il est en tête pour insister."},{"cle":{"type":"choix","ids":["b"]},"explication":"**mit** est suivi du datif, et le démonstratif masculin au datif est **dem**."},{"cle":{"type":"zone","ids":["m14","m20"]},"explication":"**Die** (accusatif féminin : « elle, je ne la connais pas ») et **der** (datif féminin après *von*) désignent Lea."},{"cle":{"type":"trous","trous":[["denen"]]},"affichage":"denen","explication":"**denen** : datif pluriel du démonstratif (comme du pronom relatif), imposé par *mit*."}]$ex$::jsonb),
  ('65318149-e09d-5271-a9c8-888224569afe'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Deux amies, le même T-shirt","competence":"raisonner","situation":"Lea et Mia portent un T-shirt qui se ressemble beaucoup. Un petit article raconte leur journée, avec quelques démonstratifs plus fins.","documents":[{"id":"freundinnen","type":"texte","genre":"article","titre":"Zwei Freundinnen","blocs":["Zwei Freundinnen, Lea und Mia, tragen heute das gleiche T-Shirt. Sie wohnen in demselben Haus, im dritten Stock. Lea traf gestern Paul und dessen Schwester."],"source":"Article écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui dit que les deux T-shirts sont semblables, mais que ce sont deux exemplaires.","aide":"Il y a deux objets différents, de même modèle.","type":"zone","document":"freundinnen","multiple":false},{"enonce":"À qui appartient la sœur dans « Paul und dessen Schwester » ?","aide":"Dessen remplace un possessif ambigu et vise le nom juste avant.","type":"choix","options":[{"id":"a","texte":"À une personne non citée"},{"id":"b","texte":"À Lea, qui l’a rencontrée"},{"id":"c","texte":"À Paul, le dernier nom cité"},{"id":"d","texte":"À Mia, l’autre amie"}],"multiple":false},{"enonce":"Touche le mot qui dit qu’elles habitent dans la MÊME maison, un seul et unique bâtiment.","aide":"Il s’agit d’un seul objet, identique.","type":"zone","document":"freundinnen","multiple":false},{"enonce":"Associe chaque forme à ce qu’elle exprime.","aide":"Relis le texte : une maison, deux T-shirts, la sœur de Paul.","type":"association","gauche":[{"id":"g0","texte":"derselbe"},{"id":"g1","texte":"der gleiche"},{"id":"g2","texte":"dessen"},{"id":"g3","texte":"dieser"}],"droite":[{"id":"d0","texte":"semblable : deux objets"},{"id":"d1","texte":"démonstratif neutre de base"},{"id":"d2","texte":"possessif qui lève l’ambiguïté"},{"id":"d3","texte":"identique : un seul objet"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8"]},"explication":"**gleiche** (*das gleiche T-Shirt*) : deux objets semblables."},{"cle":{"type":"choix","ids":["c"]},"explication":"**dessen** = « de celui-ci » : c’est la sœur de **Paul**, sans équivoque (alors que *seine Schwester* pourrait être ambigu)."},{"cle":{"type":"zone","ids":["m13"]},"explication":"**demselben** (*in demselben Haus*) : un seul Haus, identique. *Derselbe* se décline sur ses deux morceaux."},{"cle":{"type":"association","paires":{"g1":"d0","g3":"d1","g2":"d2","g0":"d3"}},"explication":"**derselbe** = même objet ; **der gleiche** = même modèle ; **dessen** = « de celui-ci » ; **dieser** = démonstratif de base."}]$ex$::jsonb),
  ('5c40007f-ccb0-5043-9b02-006edf5845e2'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les projets de l’été","competence":"comprendre-langue","situation":"Mia et Ben parlent de leurs vacances. Observe les petits « zu » placés devant leurs verbes.","documents":[{"id":"sommer","type":"dialogue","modele":"sms","titre":"Was machst du im Sommer?","participants":[{"nom":"Mia","emoji":"👧","cote":"gauche"},{"nom":"Ben","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Mia","texte":"Was hast du im Sommer vor?"},{"qui":"Ben","texte":"Ich habe vor, nach Italien zu fahren."},{"qui":"Mia","texte":"Super! Ich versuche, einen Ferienjob zu finden."},{"qui":"Ben","texte":"Hast du Lust, mit mir zu fahren?"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les trois « zu » de la conversation.","aide":"Le petit mot zu se place juste devant l’infinitif.","type":"zone","document":"sommer","multiple":true},{"enonce":"Range chaque verbe selon qu’il demande « zu » devant l’infinitif ou non.","aide":"Les modaux, les verbes de mouvement et sehen / hören / lassen refusent zu.","type":"categories","categories":[{"id":"c0","texte":"Infinitif avec zu"},{"id":"c1","texte":"Infinitif sans zu"}],"items":[{"id":"i0","texte":"vergessen"},{"id":"i1","texte":"können"},{"id":"i2","texte":"gehen"},{"id":"i3","texte":"versuchen"},{"id":"i4","texte":"hoffen"},{"id":"i5","texte":"hören"}]},{"enonce":"Complète : « As-tu envie d’aller au cinéma ? »","aide":"Après « Lust haben », l’infinitif prend zu.","type":"trous","segments":["Hast du Lust, ins Kino ",0," gehen?"],"banque":["um","ohne","zu","zum"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m11","m18","m25"]},"explication":"Les trois **zu** se trouvent devant *fahren*, *finden*, *fahren* : après *vorhaben*, *versuchen* et *Lust haben*, l’infinitif prend zu."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0","i4":"c0","i5":"c1"}},"explication":"**versuchen, hoffen, vergessen** appellent *zu*. Les **modaux** (*können*), les verbes de mouvement (*gehen*) et *hören* l’excluent."},{"cle":{"type":"trous","trous":[["zu"]]},"affichage":"zu","explication":"**Hast du Lust, ins Kino zu gehen ?** *zu* se place juste devant l’infinitif, en fin de groupe."}]$ex$::jsonb),
  ('5c40007f-ccb0-5043-9b02-006edf5845e2'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Lea apprend l’espagnol","competence":"analyser-texte","situation":"Un petit article présente une lycéenne qui prépare son avenir. Les groupes infinitifs expriment un but, une privation ou une substitution.","documents":[{"id":"lea","type":"texte","genre":"article","titre":"Leas Plan","blocs":["Lea lernt Spanisch, um in Madrid zu arbeiten. Ihre Mutter bezahlt den Kurs, damit Lea eine gute Lehrerin hat. Statt zu schlafen, übt sie jeden Morgen."],"source":"Article écrit pour l’exercice"}],"questions":[{"enonce":"Touche la conjonction du but employée parce que les deux propositions n’ont pas le même sujet.","aide":"Le sujet de la première proposition est la mère ; celui de la seconde est Lea.","type":"zone","document":"lea","multiple":false},{"enonce":"Pourquoi ne peut-on pas écrire « …, um Lea eine gute Lehrerin zu haben » ?","aide":"Qui paie le cours ? Et qui doit avoir une bonne professeure ?","type":"choix","options":[{"id":"a","texte":"Les deux propositions n’ont pas le même sujet"},{"id":"b","texte":"Um… zu exprime toujours la cause, jamais le but"},{"id":"c","texte":"Le verbe haben ne se met jamais à l’infinitif"},{"id":"d","texte":"Lehrerin est un nom qui ne se déclinerait pas"}],"multiple":false},{"enonce":"Associe chaque groupe infinitif à ce qu’il exprime.","aide":"Pense aux traductions : « pour », « sans », « au lieu de ».","type":"association","gauche":[{"id":"g0","texte":"um… zu"},{"id":"g1","texte":"ohne… zu"},{"id":"g2","texte":"statt… zu"}],"droite":[{"id":"d0","texte":"le but"},{"id":"d1","texte":"la substitution (au lieu de)"},{"id":"d2","texte":"la privation (sans faire)"}]},{"enonce":"Remets en ordre la fin de la phrase « Ich lerne Deutsch, … » (« pour étudier à Berlin »).","aide":"Le groupe est introduit par um ; zu se place juste devant l’infinitif final.","type":"ordre","items":[{"id":"a","texte":"studieren"},{"id":"b","texte":"in Berlin"},{"id":"c","texte":"zu"},{"id":"d","texte":"um"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m13"]},"explication":"**damit** : avec deux sujets différents (*die Mutter* / *Lea*), on ne peut pas employer *um… zu*."},{"cle":{"type":"choix","ids":["a"]},"explication":"**um… zu** exige le **même sujet** dans les deux propositions. Si le sujet change, on emploie **damit**."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"**um… zu** = pour (but), **ohne… zu** = sans, **statt… zu** = au lieu de. Tous trois exigent une virgule."},{"cle":{"type":"ordre","ids":["d","b","c","a"]},"explication":"**…, um in Berlin zu studieren.** *um* ouvre le groupe, *zu* précède l’infinitif qui le ferme."}]$ex$::jsonb),
  ('5c40007f-ccb0-5043-9b02-006edf5845e2'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"La liste de choses à faire","competence":"manier-langue","situation":"Sarah a écrit un pense-bête pour sa journée. Elle y mélange infinitifs avec zu, sans zu, et tournures plus soutenues.","documents":[{"id":"zettel","type":"texte","genre":"consigne","titre":"Sarahs Zettel","blocs":["Heute habe ich viel zu tun: Ich muss früh aufstehen. Ich vergesse nicht, Oma anzurufen. Danach habe ich vor, im Supermarkt einzukaufen. Die Hausaufgaben sind bis morgen zu machen."],"source":"Pense-bête écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux verbes à préverbe séparable dans lesquels zu s’est glissé au milieu du mot.","aide":"Le zu s’intercale entre le préverbe (an-, ein-) et le radical.","type":"zone","document":"zettel","multiple":true},{"enonce":"Que signifie « Die Hausaufgaben sind bis morgen zu machen » ?","aide":"Sein + zu + infinitif a une valeur passive d’obligation ou de possibilité.","type":"choix","options":[{"id":"a","texte":"Les devoirs doivent être faits d’ici demain"},{"id":"b","texte":"Les devoirs ne sont pas à faire"},{"id":"c","texte":"Les devoirs sont faits par quelqu’un d’autre"},{"id":"d","texte":"Les devoirs ont été faits hier soir"}],"multiple":false},{"enonce":"Complète : « Je n’oublie pas d’appeler Oma. » (anrufen)","aide":"Avec un préverbe séparable, zu s’intercale entre le préverbe et le radical, en un seul mot.","type":"trous","segments":["Ich vergesse nicht, Oma ",0,"."],"banque":["zuanrufen","anzurufen","zu anrufen","anrufen"]},{"enonce":"Remets en ordre la fin de la phrase « Er ging weg, … » (« sans rien dire »).","aide":"Le groupe commence par ohne et se termine par l’infinitif précédé de zu.","type":"ordre","items":[{"id":"a","texte":"sagen"},{"id":"b","texte":"zu"},{"id":"c","texte":"ohne"},{"id":"d","texte":"etwas"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m14","m21"]},"explication":"**anzurufen** et **einzukaufen** : avec un préverbe séparable, *zu* s’insère entre le préverbe et le radical, en un seul mot. *aufstehen* n’a pas de zu après un modal."},{"cle":{"type":"choix","ids":["a"]},"explication":"**sein + zu + infinitif** a une valeur passive : « doit être fait »."},{"cle":{"type":"trous","trous":[["anzurufen"]]},"affichage":"anzurufen","explication":"**anzurufen** : an + zu + rufen, en un seul mot. Le groupe infinitif ferme la phrase."},{"cle":{"type":"ordre","ids":["c","d","b","a"]},"explication":"**Er ging weg, ohne etwas zu sagen.** *ohne… zu* exprime la privation, avec une virgule devant."}]$ex$::jsonb),
  ('2359e022-15b6-50e4-9ed4-6d25d2e43450'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les projets de l’été","competence":"comprendre-langue","situation":"Marie demande à Paul ce qu’il fera cet été. Il répond au futur : repère la construction werden + infinitif.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Sommer","participants":[{"nom":"Marie","emoji":"👧","cote":"gauche"},{"nom":"Paul","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Marie","texte":"Was wirst du im Sommer machen?"},{"qui":"Paul","texte":"Ich werde nach Italien fahren. Meine Schwester wird auch kommen."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les trois formes conjuguées de « werden ».","aide":"Elles sont en 2e position : wirst, werde, wird.","type":"zone","document":"sms","multiple":true},{"enonce":"Touche les deux infinitifs qui ferment les phrases au futur.","aide":"Ils sont tout à la fin de leur phrase.","type":"zone","document":"sms","multiple":true},{"enonce":"Complète : « Tu travailleras en juillet et nous nous baignerons en août. »","aide":"Du : wirst. Wir : werden.","type":"trous","segments":["Du ",0," im Juli arbeiten, und wir ",1," im August schwimmen."],"banque":["werden","wirst","werdet","wird"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1","m7","m13"]},"explication":"**wirst, werde, wird** : le présent de *werden* est l’auxiliaire du futur."},{"cle":{"type":"zone","ids":["m10","m15"]},"explication":"**fahren** et **kommen** : au futur, l’infinitif part à la fin et *werden* reste en 2e position."},{"cle":{"type":"trous","trous":[["wirst"],["werden"]]},"affichage":"wirst · werden","explication":"**Du wirst im Juli arbeiten, und wir werden im August schwimmen.** *werden* + infinitif."}]$ex$::jsonb),
  ('2359e022-15b6-50e4-9ed4-6d25d2e43450'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le bulletin météo","competence":"analyser-texte","situation":"La radio locale annonce le temps des prochains jours. Certaines phrases emploient le futur, d’autres le présent : à toi de comprendre quand le futur est utile.","documents":[{"id":"wetter","type":"texte","genre":"article","titre":"Das Wetter","blocs":["Morgen regnet es im Norden. Im Süden wird es sonnig sein. Am Samstag wird es dann wärmer werden."],"source":"Bulletin écrit pour l’exercice"}],"questions":[{"enonce":"Touche le verbe au présent qui exprime ici l’avenir.","aide":"Un adverbe de temps (morgen) suffit à situer l’action.","type":"zone","document":"wetter","multiple":false},{"enonce":"Touche les deux « wird » qui forment un futur avec un infinitif.","aide":"Ils sont suivis de « sein » et de « werden » à l’infinitif.","type":"zone","document":"wetter","multiple":true},{"enonce":"Range ces phrases : le présent suffit-il, ou le futur est-il utile ?","aide":"Un adverbe de temps rend le futur inutile ; une promesse ou un ordre l’appelle.","type":"categories","categories":[{"id":"c0","texte":"Le présent suffit"},{"id":"c1","texte":"Le futur est utile"}],"items":[{"id":"i0","texte":"Nächste Woche kommt Tom."},{"id":"i1","texte":"Morgen fahre ich nach Wien."},{"id":"i2","texte":"Du wirst jetzt aufräumen!"},{"id":"i3","texte":"Das wird nicht einfach sein."},{"id":"i4","texte":"Am Montag habe ich Training."},{"id":"i5","texte":"Ich werde dir helfen."}]},{"enonce":"Complète : « Ne t’inquiète pas, je ne t’oublierai pas. »","aide":"Ich : la forme de werden est en -e.","type":"trous","segments":["Keine Sorge, ich ",0," dich nicht vergessen."],"banque":["werden","werde","wird","wirst"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1"]},"explication":"**regnet** est au présent : avec *morgen*, le présent suffit pour parler de l’avenir."},{"cle":{"type":"zone","ids":["m7","m13"]},"explication":"**wird … sein** et **wird … werden** : *werden* + infinitif à la fin = futur."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1","i4":"c0","i5":"c1"}},"explication":"Avec un **adverbe de temps**, le présent suffit. Sans repère de temps, pour une **promesse**, une **prédiction** ou une **insistance**, on emploie le futur."},{"cle":{"type":"trous","trous":[["werde"]]},"affichage":"werde","explication":"**Keine Sorge, ich werde dich nicht vergessen.** Une promesse, sans repère de temps : le futur s’impose."}]$ex$::jsonb),
  ('2359e022-15b6-50e4-9ed4-6d25d2e43450'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Où est donc Max ?","competence":"raisonner","situation":"Max ne répond pas au téléphone. Clara et Ben cherchent à comprendre. Attention : un futur allemand ne parle pas toujours de l’avenir.","documents":[{"id":"dial","type":"dialogue","modele":"sms","titre":"Wo ist Max?","participants":[{"nom":"Clara","emoji":"👧","cote":"gauche"},{"nom":"Ben","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Clara","texte":"Wo ist Max? Er antwortet nicht."},{"qui":"Ben","texte":"Er wird wohl schlafen."},{"qui":"Clara","texte":"Dann wird er es vergessen haben!"},{"qui":"Ben","texte":"Er wird bestimmt bald kommen."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Associe chaque phrase à sa traduction.","aide":"Tous commencent par werden, mais ce qui suit change le sens.","type":"association","gauche":[{"id":"g0","texte":"Er wird wohl schlafen"},{"id":"g1","texte":"Er wird es vergessen haben"},{"id":"g2","texte":"Er wird bestimmt bald kommen"},{"id":"g3","texte":"Er wird Arzt"}],"droite":[{"id":"d0","texte":"Il doit dormir"},{"id":"d1","texte":"Il a dû l’oublier"},{"id":"d2","texte":"Il devient médecin"},{"id":"d3","texte":"Il viendra sûrement bientôt"}]},{"enonce":"Touche le petit mot qui transforme ce futur en supposition.","aide":"Il se traduit par « sans doute, probablement ».","type":"zone","document":"dial","multiple":false},{"enonce":"Range ces phrases : vrai futur ou supposition sur le présent ?","aide":"Cherche wohl, ou un repère comme morgen ou bald.","type":"categories","categories":[{"id":"c0","texte":"Futur (l’avenir)"},{"id":"c1","texte":"Supposition (le présent)"}],"items":[{"id":"i0","texte":"Er wird wohl zu Hause sein."},{"id":"i1","texte":"Das Konzert wird bald beginnen."},{"id":"i2","texte":"Ich werde dir morgen helfen."},{"id":"i3","texte":"Sie wird wohl noch schlafen."},{"id":"i4","texte":"Er wird wohl krank sein."},{"id":"i5","texte":"Wir werden nächste Woche reisen."}]},{"enonce":"Remets en ordre : « Je crois qu’il viendra. » La phrase commence par Ich glaube.","aide":"En subordonnée, c’est werden qui ferme la phrase, après l’infinitif.","type":"ordre","items":[{"id":"a","texte":"wird"},{"id":"b","texte":"Ich glaube"},{"id":"c","texte":"kommen"},{"id":"d","texte":"dass"},{"id":"e","texte":"er"}]},{"enonce":"Complète : « Elle a dû rater le bus. »","aide":"Le futur II se forme avec werden + participe II + infinitif de l’auxiliaire.","type":"trous","segments":["Sie wird den Bus verpasst ",0,"."],"banque":["sein","haben","hat","worden"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g0":"d0","g1":"d1","g3":"d2","g2":"d3"}},"explication":"*wohl* + futur = supposition sur le présent ; futur II = supposition sur le passé ; *bald* = vrai futur ; *werden* + nom = devenir."},{"cle":{"type":"zone","ids":["m8"]},"explication":"**wohl** renforce la supposition : *Er wird wohl schlafen* = « il doit dormir »."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c1","i4":"c1","i5":"c0"}},"explication":"Avec **wohl**, le futur dit une hypothèse sur le présent ; avec un repère comme **morgen** ou **bald**, il parle vraiment de l’avenir."},{"cle":{"type":"ordre","ids":["b","d","e","c","a"]},"explication":"**Ich glaube, dass er kommen wird.** Subordonnée : l’infinitif, puis *werden* conjugué en dernier."},{"cle":{"type":"trous","trous":[["haben"]]},"affichage":"haben","explication":"**Sie wird den Bus verpasst haben.** Futur II : *werden* + participe + *haben*, une supposition sur le passé."}]$ex$::jsonb),
  ('5ba02fae-7d2b-52f8-ac05-f0408c97ae3d'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un samedi chez Oma","competence":"comprendre-langue","situation":"Tom demande à Lea ce qu’elle a fait hier. Elle raconte, et Tom répond à son tour : repère les verbes qui portent le récit.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Was hast du gemacht?","participants":[{"nom":"Tom","emoji":"👧","cote":"gauche"},{"nom":"Lea","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Tom","texte":"Was hast du gestern gemacht?"},{"qui":"Lea","texte":"Ich war bei Oma. Ich bin mit dem Zug gefahren und habe Kuchen gebacken."},{"qui":"Tom","texte":"Ich habe Fußball gespielt."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les deux formes du verbe « sein » dans le message de Lea.","aide":"Cherche les mots qui veulent dire « étais » et « suis ».","type":"zone","document":"sms","multiple":true},{"enonce":"Touche les trois formes de « haben » qui servent d’auxiliaire.","aide":"Elles sont devant un participe : gemacht, gebacken, gespielt.","type":"zone","document":"sms","multiple":true},{"enonce":"Range ces verbes selon l’auxiliaire qu’ils prennent au parfait.","aide":"Les verbes de déplacement d’un point à un autre prennent sein.","type":"categories","categories":[{"id":"c0","texte":"haben"},{"id":"c1","texte":"sein"}],"items":[{"id":"i0","texte":"essen"},{"id":"i1","texte":"kommen"},{"id":"i2","texte":"fahren"},{"id":"i3","texte":"spielen"},{"id":"i4","texte":"fliegen"},{"id":"i5","texte":"machen"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6","m10"]},"explication":"**war** (prétérit) et **bin** (présent) sont deux formes de *sein*."},{"cle":{"type":"zone","ids":["m1","m16","m20"]},"explication":"**hast**, **habe**, **habe** sont des formes de *haben* qui forment le parfait de *machen*, *backen* et *spielen*."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0","i4":"c1","i5":"c0"}},"explication":"**sein** avec *fahren, kommen, fliegen* (déplacement) ; **haben** avec *spielen, essen, machen*."}]$ex$::jsonb),
  ('5ba02fae-7d2b-52f8-ac05-f0408c97ae3d'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Un colis, un frère et un faux ami","competence":"analyser-texte","situation":"Une petite-fille remercie sa grand-mère dans une lettre. Attention : un mot ressemble à l’anglais « to become », mais il ne veut pas dire ce que tu crois.","documents":[{"id":"brief","type":"texte","genre":"lettre","titre":"Liebe Oma","blocs":["Liebe Oma, danke für dein Paket! Ich habe es gestern bekommen. Mein Bruder wird bald Arzt. Er hat ein Stipendium bekommen. Ich bin müde geworden, weil wir viel gearbeitet haben. Bis bald!"],"source":"Lettre écrite pour l’exercice"}],"questions":[{"enonce":"Touche les deux fois où le verbe « bekommen » apparaît.","aide":"C’est un participe II qui commence par be-.","type":"zone","document":"brief","multiple":true},{"enonce":"Que signifie « Ich habe es gestern bekommen » ?","aide":"*bekommen* a un sens très précis : ce n’est pas « devenir ».","type":"choix","options":[{"id":"a","texte":"Je l’ai donné hier"},{"id":"b","texte":"Je l’ai gardé hier"},{"id":"c","texte":"Je suis devenu cela hier"},{"id":"d","texte":"Je l’ai reçu hier"}],"multiple":false},{"enonce":"Complète : « Mon frère devient médecin. »","aide":"Pour dire « devenir », l’allemand emploie werden.","type":"trous","segments":["Mein Bruder ",0," Arzt."],"banque":["wird","hat","ist","bekommt"]},{"enonce":"Remets en ordre : « Je suis devenu fatigué. » La phrase commence par Ich.","aide":"Au parfait, l’auxiliaire est en deuxième position et le participe à la fin.","type":"ordre","items":[{"id":"a","texte":"bin"},{"id":"b","texte":"müde"},{"id":"c","texte":"geworden"},{"id":"d","texte":"Ich"}]},{"enonce":"Pourquoi dit-on « Ich bin müde geworden » et non « Ich habe müde geworden » ?","aide":"Souviens-toi des quatre verbes à part : sein, bleiben, werden, passieren.","type":"choix","options":[{"id":"a","texte":"müde est un verbe de déplacement"},{"id":"b","texte":"bin est la forme polie de habe"},{"id":"c","texte":"werden est l’un des quatre verbes à part avec sein"},{"id":"d","texte":"geworden est un verbe fort donc il prend sein"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m10","m20"]},"explication":"**bekommen** apparaît deux fois : *Paket bekommen* et *Stipendium bekommen*."},{"cle":{"type":"choix","ids":["d"]},"explication":"**bekommen** = « recevoir ». « Devenir » se dit *werden* : *Ich werde Arzt*."},{"cle":{"type":"trous","trous":[["wird"]]},"affichage":"wird","explication":"**Mein Bruder wird Arzt.** *werden* + nom = « devenir ». *bekommt* voudrait dire « reçoit »."},{"cle":{"type":"ordre","ids":["d","a","b","c"]},"explication":"**Ich bin müde geworden.** *werden* forme son parfait avec *sein* : *bin … geworden*."},{"cle":{"type":"choix","ids":["c"]},"explication":"**werden** fait partie des quatre verbes qui forment leur parfait avec *sein*, comme *sein*, *bleiben* et *passieren*."}]$ex$::jsonb),
  ('5ba02fae-7d2b-52f8-ac05-f0408c97ae3d'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Papa attend Nora","competence":"raisonner","situation":"Nora rentre en retard, et son père lui écrit. Puis un article local annonce la carrière d’un cuisinier. Dans les deux documents, des auxiliaires à ne pas confondre.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Wo bist du?","participants":[{"nom":"Papa","emoji":"👨","cote":"gauche"},{"nom":"Nora","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Papa","texte":"Wo bist du? Was ist passiert?"},{"qui":"Nora","texte":"Der Bus ist nicht gekommen. Ich bin zu Fuß gelaufen."},{"qui":"Papa","texte":"Du hast bestimmt Hunger. Ich habe Pizza gemacht."},{"qui":"Nora","texte":"Super! Ich bin gleich da."}],"source":"Messages écrits pour l’exercice"},{"id":"presse","type":"texte","genre":"article","titre":"Neues aus dem Viertel","blocs":["Mein Bruder wird Koch. Er wird bald in Berlin arbeiten. Das Restaurant wird gerade gebaut."],"source":"Article écrit pour l’exercice"}],"questions":[{"enonce":"Touche les trois « sein » qui servent d’auxiliaire au parfait.","aide":"Chacun est suivi d’un participe : passiert, gekommen, gelaufen.","type":"zone","document":"sms","multiple":true},{"enonce":"Touche le seul « haben » qui sert ici d’auxiliaire.","aide":"L’autre « hast » est suivi d’un nom : Hunger.","type":"zone","document":"sms","multiple":false},{"enonce":"Pourquoi Nora dit-elle « Ich bin zu Fuß gelaufen » ?","aide":"Demande-toi si Nora va d’un endroit à un autre.","type":"choix","options":[{"id":"a","texte":"zu Fuß exige toujours le verbe sein"},{"id":"b","texte":"laufen est un déplacement d’un point à un autre"},{"id":"c","texte":"laufen est un verbe qui change de voyelle"},{"id":"d","texte":"Parce que le sujet est ich"}],"multiple":false},{"enonce":"Range ces phrases selon l’auxiliaire du parfait.","aide":"Un verbe de mouvement avec un COD prend haben.","type":"categories","categories":[{"id":"c0","texte":"haben"},{"id":"c1","texte":"sein"}],"items":[{"id":"i0","texte":"Ich … nach Köln gefahren"},{"id":"i1","texte":"Er … eingeschlafen"},{"id":"i2","texte":"Sie … einen Brief geschrieben"},{"id":"i3","texte":"Wir … Fußball gespielt"},{"id":"i4","texte":"Ich … das Auto gefahren (j’ai conduit la voiture)"},{"id":"i5","texte":"Es … schon passiert"}]},{"enonce":"Associe chaque phrase de l’article à sa traduction.","aide":"Regarde ce qui suit werden : un nom, un infinitif ou un participe.","type":"association","gauche":[{"id":"g0","texte":"Er wird Koch"},{"id":"g1","texte":"Er wird arbeiten"},{"id":"g2","texte":"Das Restaurant wird gebaut"}],"droite":[{"id":"d0","texte":"Il travaillera"},{"id":"d1","texte":"Le restaurant est construit"},{"id":"d2","texte":"Il devient cuisinier"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4","m8","m12"]},"explication":"**ist** (… passiert), **ist** (… gekommen) et **bin** (… gelaufen) sont des auxiliaires. Les autres « bist » et « bin » sont des verbes pleins."},{"cle":{"type":"zone","ids":["m21"]},"explication":"**habe** forme le parfait de *machen*. *Du hast Hunger* utilise *haben* comme verbe plein (« avoir faim »)."},{"cle":{"type":"choix","ids":["b"]},"explication":"**sein** s’emploie avec les verbes de déplacement d’un point à un autre : *Ich bin gelaufen*."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0","i4":"c0","i5":"c1"}},"explication":"**haben** quand il y a un COD (*das Auto gefahren*) ou pour la plupart des verbes ; **sein** pour le déplacement (*nach Köln gefahren*) et le changement d’état (*eingeschlafen*, *passiert*)."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"**werden** + nom = devenir ; + infinitif = futur ; + participe II = passif."}]$ex$::jsonb),
  ('677f76f9-8081-5751-bab2-7865d4ccfa59'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un goûter pour Opa","competence":"comprendre-langue","situation":"Jule prépare l’anniversaire de son grand-père. Son petit mot contient plusieurs prépositions qu’il faut savoir reconnaître.","documents":[{"id":"opa","type":"texte","genre":"lettre","titre":"Opas Geburtstag","blocs":["Morgen hat Opa Geburtstag. Ich kaufe ein Geschenk für meinen Opa. Wir gehen durch den Park und sitzen um einen Tisch. Ohne Oma feiern wir nicht."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les quatre prépositions qui sont toujours suivies de l’accusatif.","aide":"Pense à la liste durch · für · gegen · ohne · um.","type":"zone","document":"opa","multiple":true},{"enonce":"Associe chaque préposition à son sens.","aide":"Retrouve chaque préposition dans le texte.","type":"association","gauche":[{"id":"g0","texte":"durch"},{"id":"g1","texte":"für"},{"id":"g2","texte":"ohne"},{"id":"g3","texte":"um"}],"droite":[{"id":"d0","texte":"pour"},{"id":"d1","texte":"autour de"},{"id":"d2","texte":"à travers"},{"id":"d3","texte":"sans"}]},{"enonce":"Complète : « Le cadeau est pour ma sœur. »","aide":"*für* demande l’accusatif ; *Schwester* est féminin.","type":"trous","segments":["Das Geschenk ist für ",0," Schwester."],"banque":["die","dem","den","der"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8","m13","m18","m21"]},"explication":"**für**, **durch**, **um** et **ohne** régissent toujours l’accusatif, quel que soit le sens."},{"cle":{"type":"association","paires":{"g1":"d0","g3":"d1","g0":"d2","g2":"d3"}},"explication":"*durch* = à travers, *für* = pour, *ohne* = sans, *um* = autour de."},{"cle":{"type":"trous","trous":[["die"]]},"affichage":"die","explication":"**für die Schwester** : accusatif féminin = *die*."}]$ex$::jsonb),
  ('677f76f9-8081-5751-bab2-7865d4ccfa59'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Rendez-vous au cinéma","competence":"analyser-document","situation":"Ben et Mia organisent une soirée cinéma. Pour s’y retrouver, ils doivent distinguer l’heure approximative de l’heure précise.","documents":[{"id":"kino","type":"dialogue","modele":"sms","titre":"Heute Abend","participants":[{"nom":"Ben","emoji":"👧","cote":"gauche"},{"nom":"Mia","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Ben","texte":"Wann treffen wir uns heute?"},{"qui":"Mia","texte":"Gegen vier. Der Film beginnt um 18 Uhr."},{"qui":"Ben","texte":"Super. Ich komme ohne Marie, sie ist krank."},{"qui":"Mia","texte":"Schade! Dann kaufe ich Popcorn für uns beide."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche la préposition qui donne une heure approximative, « vers quatre heures ».","aide":"Ce n’est pas celle du film.","type":"zone","document":"kino","multiple":false},{"enonce":"Touche la préposition qui donne une heure précise.","aide":"Elle est devant « 18 Uhr ».","type":"zone","document":"kino","multiple":false},{"enonce":"À quelle heure exacte commence le film ? (en heures, sur 24 h)","aide":"Cherche la préposition de l’heure précise.","type":"nombre","unite":"Uhr"},{"enonce":"Complète : « Nous jouons sans elle. » (Marie)","aide":"*ohne* est suivi de l’accusatif.","type":"trous","segments":["Wir spielen ohne ",0,"."],"banque":["ihm","sie","ihr","es"]},{"enonce":"Remets en ordre : « Nous traversons le parc. » La phrase commence par Wir.","aide":"*durch* est suivi de l’accusatif.","type":"ordre","items":[{"id":"a","texte":"gehen"},{"id":"b","texte":"Wir"},{"id":"c","texte":"den Park"},{"id":"d","texte":"durch"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5"]},"explication":"**Gegen** : *gegen vier* = « vers quatre heures »."},{"cle":{"type":"zone","ids":["m10"]},"explication":"**um** : *um 18 Uhr* = « à 18 h pile »."},{"cle":{"type":"nombre","valeur":18,"tolerance":0},"affichage":"18 Uhr","explication":"**18 Uhr** : le film commence *um 18 Uhr*, donc à l’heure précise de 18 h."},{"cle":{"type":"trous","trous":[["sie"]]},"affichage":"sie","explication":"**ohne sie** : *ohne* demande l’accusatif, et le pronom de « elle » à l’accusatif est *sie*."},{"cle":{"type":"ordre","ids":["b","a","d","c"]},"explication":"**Wir gehen durch den Park.** *durch* + accusatif masculin (*den*)."}]$ex$::jsonb),
  ('677f76f9-8081-5751-bab2-7865d4ccfa59'::uuid, 3, 3, 15, 50, 6,
   $ex${"titre":"Le rallye de la ville","competence":"analyser-document","situation":"Pour la semaine d’intégration, les élèves de 3e font un rallye dans la ville. La feuille de route précise l’itinéraire ; Jule et Ole échangent des messages à la veille du départ.","documents":[{"id":"rallye","type":"fiche","modele":"affiche","entete":"Stadtrallye","sousTitre":"Samstag, 9 Uhr","emoji":"🗺️","lignes":[{"texte":"1 · Gehen Sie durch den Park.","id":"z1"},{"texte":"2 · Laufen Sie die Straße entlang.","id":"z2"},{"texte":"3 · Gehen Sie um die Kirche.","id":"z3"},{"texte":"4 · Treffpunkt: gegen 15 Uhr am Brunnen.","id":"z4"}],"pied":"Feuille écrite pour l’exercice","teinte":"bleu"},{"id":"jule","type":"dialogue","modele":"sms","titre":"Vor dem Rallye","participants":[{"nom":"Jule","emoji":"👧","cote":"gauche"},{"nom":"Ole","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Jule","texte":"Kommst du mit dem Auto?"},{"qui":"Ole","texte":"Nein, ich komme ohne Auto, mit dem Bus."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche la préposition qui impose toujours l’accusatif.","aide":"L’autre préposition est suivie du datif.","type":"zone","document":"jule","multiple":false},{"enonce":"Touche la ligne où la préposition se place après le nom.","aide":"Cherche le mot qui veut dire « le long de ».","type":"zone","document":"rallye","multiple":false},{"enonce":"Complète : « Nous marchons autour de la fontaine et à travers la porte. »","aide":"*um* et *durch* demandent l’accusatif ; regarde le genre de *Brunnen* et de *Tür*.","type":"trous","segments":["Wir laufen um ",0," Brunnen und gehen durch ",1," Tür."],"banque":["die","das","dem","den"]},{"enonce":"Remets en ordre : « Nous longeons la rue. » La phrase commence par Wir.","aide":"*entlang* est placé après le nom.","type":"ordre","items":[{"id":"a","texte":"gehen"},{"id":"b","texte":"entlang"},{"id":"c","texte":"die Straße"},{"id":"d","texte":"Wir"}]},{"enonce":"Que signifie « Treffpunkt : gegen 15 Uhr » sur la feuille ?","aide":"Compare avec *um 15 Uhr*.","type":"choix","options":[{"id":"a","texte":"On se retrouve vers 15 heures"},{"id":"b","texte":"On se retrouve avant 15 heures"},{"id":"c","texte":"On se retrouve à 15 heures pile"},{"id":"d","texte":"On se retrouve après 15 heures"}],"multiple":false},{"enonce":"Complète : « Je vais à la gare pour chercher mon grand-père. »","aide":"Devant un verbe à l’infinitif, *für* est impossible.","type":"trous","segments":["Ich fahre zum Bahnhof, ",0," Opa abzuholen."],"banque":["durch","um","für","ohne"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8"]},"explication":"**ohne** régit toujours l’accusatif ; *mit* régit toujours le datif."},{"cle":{"type":"zone","ids":["z2"]},"explication":"**Ligne 2** : *die Straße entlang*. *entlang* se place **après** le nom et veut dire « le long de »."},{"cle":{"type":"trous","trous":[["den"],["die"]]},"affichage":"den · die","explication":"**um den Brunnen** (masculin) et **durch die Tür** (féminin) : accusatif après *um* et *durch*."},{"cle":{"type":"ordre","ids":["d","a","c","b"]},"explication":"**Wir gehen die Straße entlang.** Avec *entlang* en postposition, le nom est à l’accusatif : *die Straße*."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Vers 15 heures** : *gegen* donne une heure approximative ; *um* donnerait l’heure précise."},{"cle":{"type":"trous","trous":[["um"]]},"affichage":"um","explication":"**um … zu** : « pour + infinitif » se dit *um … zu*. *für* introduit un groupe nominal, jamais un verbe."}]$ex$::jsonb),
  ('62a14f6a-2405-53a0-88a6-81c842ae171f'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le tableau des trois formes","competence":"lire-tableau","situation":"Un camarade a commencé à recopier les trois formes de quatre verbes. Observe le tableau et complète ce qui manque.","documents":[{"id":"tab","type":"tableau","titre":"Trois temps primitifs","colonnes":["Infinitif","Prétérit","Participe II"],"lignes":[["machen","machte","gemacht"],["spielen","spielte","?"],["fahren","fuhr","gefahren"],["nehmen","nahm","?"]],"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux prétérits en -te : ce sont des verbes faibles.","aide":"Le prétérit d’un verbe faible se termine par -te.","type":"zone","document":"tab","multiple":true},{"enonce":"Quel est le participe II de « spielen » ?","aide":"Verbe faible : ge- + radical + -t.","type":"texte"},{"enonce":"Quel est le participe II de « nehmen » ?","aide":"Verbe fort : ge- + radical modifié + -en.","type":"texte"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c1","r1c1"]},"explication":"**machte** et **spielte** se terminent par -te : *machen* et *spielen* sont faibles."},{"cle":{"type":"texte","acceptes":["gespielt"]},"affichage":"gespielt","explication":"**gespielt** : *ge-* + *spiel* + *-t*."},{"cle":{"type":"texte","acceptes":["genommen"]},"affichage":"genommen","explication":"**genommen** : *ge-* + *nomm* (la voyelle a changé) + *-en*."}]$ex$::jsonb),
  ('62a14f6a-2405-53a0-88a6-81c842ae171f'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le voyage de Lukas","competence":"manier-langue","situation":"Sophie et Max parlent du voyage de Lukas à Bonn. Plusieurs verbes forts changent de voyelle : saurais-tu les reconnaître ?","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Lukas fährt nach Bonn","participants":[{"nom":"Sophie","emoji":"👧","cote":"gauche"},{"nom":"Max","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Sophie","texte":"Was macht Lukas? Er fährt heute nach Bonn, oder?"},{"qui":"Max","texte":"Ja, er fährt mit dem Zug. Er liest ein Buch und er schläft ein bisschen."},{"qui":"Sophie","texte":"Und du? Du gibst ihm das Ticket?"},{"qui":"Max","texte":"Ja, ich gebe ihm das Ticket. Wir fahren zusammen zum Bahnhof."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les formes de la 3e personne du singulier dont la voyelle a changé par rapport à l’infinitif.","aide":"Cherche les ä et le ie : fahren, lesen, schlafen.","type":"zone","document":"sms","multiple":true},{"enonce":"Complète avec « nehmen » : « Lukas prend le train et toi tu prends le bus. »","aide":"Avec nehmen, la voyelle e devient i aux 2e et 3e personnes du singulier.","type":"trous","segments":["Lukas ",0," den Zug und du ",1," den Bus."],"banque":["nehmt","nimmt","nimmst","nehme"]},{"enonce":"Range ces verbes selon le changement de voyelle à la 2e personne du singulier.","aide":"Compare la voyelle de l’infinitif avec celle de la forme entre parenthèses.","type":"categories","categories":[{"id":"c0","texte":"e → i"},{"id":"c1","texte":"e → ie"},{"id":"c2","texte":"a → ä"}],"items":[{"id":"i0","texte":"schlafen (du schläfst)"},{"id":"i1","texte":"lesen (du liest)"},{"id":"i2","texte":"geben (du gibst)"},{"id":"i3","texte":"sprechen (du sprichst)"},{"id":"i4","texte":"sehen (du siehst)"},{"id":"i5","texte":"fahren (du fährst)"}]},{"enonce":"Pourquoi Max dit-il « Wir fahren » avec un a et non « Wir fähren » ?","aide":"Regarde les formes du pluriel dans le message : fahren, geben…","type":"choix","options":[{"id":"a","texte":"Le ä n’existe pas dans le nord de l’Allemagne"},{"id":"b","texte":"L’alternance ne touche que du et er/sie/es"},{"id":"c","texte":"fahren est un verbe faible au pluriel"},{"id":"d","texte":"Wir est une forme de politesse"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4","m11","m16","m21"]},"explication":"**fährt** (a → ä), **liest** (e → ie), **schläft** (a → ä) : la voyelle change à la 3e personne du singulier."},{"cle":{"type":"trous","trous":[["nimmt"],["nimmst"]]},"affichage":"nimmt · nimmst","explication":"**Lukas nimmt den Zug und du nimmst den Bus.** *nehmen* : e → i, avec *-t* pour *er* et *-st* pour *du*."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c1","i2":"c0","i3":"c0","i4":"c1","i5":"c2"}},"explication":"**e → i** : *sprechen, geben* ; **e → ie** : *sehen, lesen* ; **a → ä** : *fahren, schlafen*."},{"cle":{"type":"choix","ids":["b"]},"explication":"**wir fahren** : l’alternance a → ä n’existe qu’à *du* et *er/sie/es* ; elle disparaît au pluriel."}]$ex$::jsonb),
  ('62a14f6a-2405-53a0-88a6-81c842ae171f'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le compte rendu de la visite","competence":"analyser-texte","situation":"Un élève raconte sa visite chez Marie. Son texte cache des participes de tous les types : forts, mixtes, en -ieren. Un second document propose de compléter un tableau.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"Bei Marie","blocs":["Gestern habe ich Marie besucht. Wir haben lange gesprochen. Sie hat mir ein Buch gebracht, und ich habe ihr einen Brief geschrieben. Ihr Bruder hat in Lyon studiert. Er hat auch mit uns telefoniert."],"source":"Texte écrit pour l’exercice"},{"id":"tab","type":"tableau","titre":"À toi de jouer","colonnes":["Infinitif","Prétérit","Participe II"],"lignes":[["denken","dachte","?"],["essen","aß","?"],["googeln","googelte","?"]],"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux participes de verbes forts (ils se terminent par -en).","aide":"Cherche ge- … -en avec une voyelle modifiée.","type":"zone","document":"recit","multiple":true},{"enonce":"Touche les deux participes qui n’ont pas de « ge- » : ce sont des verbes en -ieren.","aide":"Ils se terminent par -iert.","type":"zone","document":"recit","multiple":true},{"enonce":"Touche le participe d’un verbe mixte : radical modifié et terminaison faible.","aide":"Il se termine par -t, mais le radical n’est plus celui de l’infinitif (bringen).","type":"zone","document":"recit","multiple":false},{"enonce":"Complète les participes II du tableau.","aide":"Mixte : ge- + radical modifié + -t. Fort : ge- … -en. Faible : ge- … -t.","type":"trous","segments":["denken → ",0," · essen → ",1," · googeln → ",2]},{"enonce":"Pourquoi le participe de « besuchen » est-il « besucht » et non « gebesucht » ?","aide":"Regarde le début du verbe : be-.","type":"choix","options":[{"id":"a","texte":"Le participe se forme ici avec sein et non haben"},{"id":"b","texte":"besuchen est un verbe fort qui change de voyelle"},{"id":"c","texte":"besuchen se termine par -ieren comme studieren"},{"id":"d","texte":"be- est un préverbe inséparable : pas de ge-"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8","m21"]},"explication":"**gesprochen** (*sprechen*) et **geschrieben** (*schreiben*) sont des participes forts."},{"cle":{"type":"zone","ids":["m27","m33"]},"explication":"**studiert** et **telefoniert** viennent de *studieren* et *telefonieren* : les verbes en -ieren sont faibles et sans ge-."},{"cle":{"type":"zone","ids":["m14"]},"explication":"**gebracht** : *bringen* est mixte, le radical change (*brach-*) mais la terminaison est faible (*-t*)."},{"cle":{"type":"trous","trous":[["gedacht"],["gegessen"],["gegoogelt"]]},"affichage":"gedacht · gegessen · gegoogelt","explication":"**gedacht** (mixte), **gegessen** (fort), **gegoogelt** (faible, comme tout verbe nouveau)."},{"cle":{"type":"choix","ids":["d"]},"explication":"**besucht** : les préverbes inséparables (*be-, ver-, er-*…) refusent le *ge-*."}]$ex$::jsonb),
  ('3693080b-ebed-515a-b479-248cabe48cb3'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un nouveau dans la classe","competence":"comprendre-langue","situation":"Leon fait connaissance avec Mina, qui vient d’arriver dans sa classe. Observe les questions qu’ils se posent.","documents":[{"id":"kennen","type":"dialogue","modele":"sms","titre":"Neue Mitschülerin","participants":[{"nom":"Leon","emoji":"👦","cote":"gauche"},{"nom":"Mina","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Leon","texte":"Hallo! Wie heißt du?"},{"qui":"Mina","texte":"Ich heiße Mina. Und du?"},{"qui":"Leon","texte":"Ich bin Leon. Woher kommst du?"},{"qui":"Mina","texte":"Aus Hamburg. Wohnst du auch hier?"},{"qui":"Leon","texte":"Ja, ich wohne in der Nähe der Schule."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le mot interrogatif qui demande l’origine : « d’où viens-tu ? ».","aide":"Le mot interrogatif est collé au début de la question de Leon sur la ville de Mina.","type":"zone","document":"kennen","multiple":false},{"enonce":"Touche le verbe qui ouvre la question fermée (celle à laquelle on répond par oui ou non).","aide":"Dans une question fermée, il n’y a pas de mot en w- : le verbe passe en tête.","type":"zone","document":"kennen","multiple":false},{"enonce":"Associe chaque mot interrogatif à son sens.","aide":"Le « hin » indique le mouvement vers un but, le « her » l’origine.","type":"association","gauche":[{"id":"g0","texte":"wo"},{"id":"g1","texte":"wohin"},{"id":"g2","texte":"woher"}],"droite":[{"id":"d0","texte":"où, vers quel lieu"},{"id":"d1","texte":"d’où"},{"id":"d2","texte":"où, sans mouvement"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m12"]},"explication":"**Woher** = « d’où ». Il demande l’origine, alors que *wo* demande le lieu sans mouvement."},{"cle":{"type":"zone","ids":["m17"]},"explication":"**Wohnst** ouvre « Wohnst du auch hier ? » : dans une question fermée, le verbe conjugué est en première position."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"**wo** = où (on est), **wohin** = où (on va), **woher** = d’où (on vient)."}]$ex$::jsonb),
  ('3693080b-ebed-515a-b479-248cabe48cb3'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le training de Paul","competence":"manier-langue","situation":"Nora et Paul parlent de leur entraînement. Le dialogue contient une question négative et une question indirecte.","documents":[{"id":"training","type":"dialogue","modele":"sms","titre":"Nach der Schule","participants":[{"nom":"Nora","emoji":"👧","cote":"gauche"},{"nom":"Paul","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Nora","texte":"Kommst du heute nicht zum Training?"},{"qui":"Paul","texte":"Doch, ich komme. Wann beginnt es?"},{"qui":"Nora","texte":"Ich weiß nicht, wann der Trainer kommt."},{"qui":"Paul","texte":"Dann frage ich ihn, ob wir heute früher anfangen."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le mot par lequel Paul contredit la question négative de Nora.","aide":"Paul veut dire « si ! » : ce n’est pas ja.","type":"zone","document":"training","multiple":false},{"enonce":"On te demande « Hast du keinen Hunger ? » et tu as faim. Que réponds-tu ?","aide":"La question est négative : il faut contredire.","type":"choix","options":[{"id":"a","texte":"Doch ! Ich habe Hunger."},{"id":"b","texte":"Nein ! Ich habe Hunger."},{"id":"c","texte":"Nicht ! Ich habe Hunger."},{"id":"d","texte":"Ja ! Ich habe Hunger."}],"multiple":false},{"enonce":"Remets en ordre la question indirecte « Ich weiß nicht, … ».","aide":"Dans une subordonnée, le verbe conjugué va tout à la fin.","type":"ordre","items":[{"id":"a","texte":"abfährt"},{"id":"b","texte":"wann"},{"id":"c","texte":"der Zug"}]},{"enonce":"Complète la question indirecte : « Je me demande s’il vient. »","aide":"Le « si » d’une question indirecte exprime une alternative.","type":"trous","segments":["Ich frage mich, ",0," er kommt."],"banque":["dass","wenn","wann","ob"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6"]},"explication":"**Doch** contredit une question négative ou une affirmation négative : « si ! »."},{"cle":{"type":"choix","ids":["a"]},"explication":"Face à une question négative, on contredit par **Doch** : *Doch ! Ich habe Hunger.* Ici, *ja* serait impossible."},{"cle":{"type":"ordre","ids":["b","c","a"]},"explication":"**Ich weiß nicht, wann der Zug abfährt.** Question indirecte : mot interrogatif, sujet, puis le verbe conjugué à la fin."},{"cle":{"type":"trous","trous":[["ob"]]},"affichage":"ob","explication":"**Ich frage mich, ob er kommt.** *ob* traduit le « si » d’une alternative ; *wenn* introduit une condition ou un moment."}]$ex$::jsonb),
  ('3693080b-ebed-515a-b479-248cabe48cb3'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Une classe en route pour Vienne","competence":"analyser-document","situation":"La classe de Herr Berg part en voyage scolaire à Vienne. Lis l’affiche, puis choisis le bon mot interrogatif pour chaque information.","documents":[{"id":"plakat","type":"fiche","modele":"affiche","entete":"Klassenfahrt nach Wien","sousTitre":"Klasse 3b","emoji":"🚆","lignes":[{"texte":"Wir fahren mit dem Zug nach Wien.","id":"z1"},{"texte":"Wir treffen uns um acht Uhr.","id":"z2"},{"texte":"Wir warten am Bahnhof auf Herrn Berg, unseren Lehrer.","id":"z3"},{"texte":"Wir denken schon an die Stadtführung.","id":"z4"}],"pied":"Affiche écrite pour l’exercice"}],"questions":[{"enonce":"Touche la ligne qui répond à la question « Auf wen warten wir ? ».","aide":"La question porte sur une personne : cherche qui on attend.","type":"zone","document":"plakat","multiple":false},{"enonce":"Associe chaque réponse à la question qui la provoque.","aide":"Pour une chose, wo(r)- + préposition ; pour une personne, préposition + wen / wem.","type":"association","gauche":[{"id":"g0","texte":"Ich schreibe mit einem Stift."},{"id":"g1","texte":"Ich spreche mit meiner Lehrerin."},{"id":"g2","texte":"Ich denke an die Prüfung."},{"id":"g3","texte":"Ich warte auf den Bus."}],"droite":[{"id":"d0","texte":"Womit schreibst du?"},{"id":"d1","texte":"Woran denkst du?"},{"id":"d2","texte":"Worauf wartest du?"},{"id":"d3","texte":"Mit wem sprichst du?"}]},{"enonce":"Touche la ligne qui répond à la question « Woran denken wir schon ? ».","aide":"Cherche le verbe « denken » suivi de sa préposition.","type":"zone","document":"plakat","multiple":false},{"enonce":"Complète la question dont la réponse est « An die Prüfung ».","aide":"On interroge sur une chose avec wo(r)- + préposition.","type":"trous","segments":[0," denkst du? — An die Prüfung."],"banque":["Wofür","Woran","Wohin","An wen"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"**Wir warten am Bahnhof auf Herrn Berg** : on interroge sur une personne avec *auf wen*, la préposition étant suivie du pronom au cas voulu."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g3":"d2","g1":"d3"}},"explication":"Chose : **womit, woran, worauf**. Personne : **mit wem** (datif après mit), *auf wen*, *an wen*."},{"cle":{"type":"zone","ids":["z4"]},"explication":"**Wir denken schon an die Stadtführung** : *an die Stadtführung* est une chose, donc on demande *woran*."},{"cle":{"type":"trous","trous":[["woran"]]},"affichage":"Woran","explication":"**Woran denkst du ?** *Woran* = *wo* + *r* + *an* : on interroge sur une chose, jamais sur une personne."}]$ex$::jsonb),
  ('5b6e33d3-fa43-50b9-b4d2-16f08e6808cf'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Que fais-tu aujourd’hui ?","competence":"comprendre-langue","situation":"Nina et Jan se demandent ce qu’ils font aujourd’hui. Repère les terminaisons du présent.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Heute","participants":[{"nom":"Nina","emoji":"👧","cote":"gauche"},{"nom":"Jan","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Nina","texte":"Was machst du heute?"},{"qui":"Jan","texte":"Ich spiele Fußball. Und du?"},{"qui":"Nina","texte":"Ich lerne. Mein Bruder spielt auch."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les deux verbes conjugués à la 1re personne du singulier.","aide":"Ils se terminent par -e et suivent « Ich ».","type":"zone","document":"sms","multiple":true},{"enonce":"Touche la forme conjuguée à la 2e personne du singulier.","aide":"Elle se termine par -st.","type":"zone","document":"sms","multiple":false},{"enonce":"Complète : « Tu apprends beaucoup et nous jouons ensemble. »","aide":"Du : terminaison -st. Wir : terminaison -en.","type":"trous","segments":["Du ",0," viel, und wir ",1," zusammen."],"banque":["lernst","lernt","spielt","spielen"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5","m10"]},"explication":"**spiele** et **lerne** : à *ich*, la terminaison du présent est **-e**."},{"cle":{"type":"zone","ids":["m1"]},"explication":"**machst** : à *du*, la terminaison est **-st**."},{"cle":{"type":"trous","trous":[["lernst"],["spielen"]]},"affichage":"lernst · spielen","explication":"**Du lernst viel, und wir spielen zusammen.** *du* → *-st* ; *wir* → *-en*."}]$ex$::jsonb),
  ('5b6e33d3-fa43-50b9-b4d2-16f08e6808cf'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le carnet de conjugaison","competence":"lire-tableau","situation":"Un élève prépare sa fiche de conjugaison. Il a laissé deux cases vides : à toi de voir quelle règle de prononciation s’applique.","documents":[{"id":"tab","type":"tableau","titre":"Présent : ich et du","colonnes":["Verbe","ich","du"],"lignes":[["arbeiten","arbeite","arbeitest"],["heißen","heiße","heißt"],["sammeln","sammle","sammelst"],["finden","finde","?"],["sitzen","sitze","?"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche la case où le e du radical tombe à la 1re personne.","aide":"Cherche un verbe en -eln.","type":"zone","document":"tab","multiple":false},{"enonce":"Complète la case : « du » + finden.","aide":"Le radical se termine par -d : on intercale un e.","type":"texte"},{"enonce":"Complète la case : « du » + sitzen.","aide":"Le radical se termine par -z : le -st perd son s.","type":"texte"},{"enonce":"Pourquoi écrit-on « du heißt » et non « du heißst » ?","aide":"Regarde la lettre qui précède la terminaison -st.","type":"choix","options":[{"id":"a","texte":"ß est une consonne muette"},{"id":"b","texte":"Après ß, le -st perd son s"},{"id":"c","texte":"heißen est un verbe fort"},{"id":"d","texte":"Après ß on ajoute un e"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c1"]},"explication":"**sammle** : avec les verbes en *-eln*, le *e* du radical tombe à *ich*."},{"cle":{"type":"texte","acceptes":["findest"]},"affichage":"findest","explication":"**findest** : après -d ou -t, on glisse un *e* pour pouvoir prononcer *-st* (comme *du arbeitest*)."},{"cle":{"type":"texte","acceptes":["sitzt"]},"affichage":"sitzt","explication":"**sitzt** : après -s, -ß, -z, -x, la terminaison *-st* perd son *s* (comme *du heißt*)."},{"cle":{"type":"choix","ids":["b"]},"explication":"**du heißt** : quand le radical finit par -s, -ß, -z ou -x, le *s* de *-st* disparaît."}]$ex$::jsonb),
  ('5b6e33d3-fa43-50b9-b4d2-16f08e6808cf'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Depuis trois ans à Berlin","competence":"raisonner","situation":"Paul veut aller à Berlin et interroge Mia, qui y habite. Leur discussion mêle habitude, moment présent et avenir.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Berlin","participants":[{"nom":"Paul","emoji":"👦","cote":"gauche"},{"nom":"Mia","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Paul","texte":"Wohnst du schon lange in Berlin?"},{"qui":"Mia","texte":"Ja, ich wohne seit drei Jahren hier. Jeden Samstag laufe ich im Park."},{"qui":"Paul","texte":"Cool! Morgen fahre ich auch nach Berlin."},{"qui":"Mia","texte":"Super! Ich zeige dir die Stadt, und du siehst viel."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui dit que Mia habite à Berlin « depuis » trois ans.","aide":"C’est une préposition suivie du datif.","type":"zone","document":"sms","multiple":false},{"enonce":"Range ces phrases selon la valeur du présent.","aide":"Cherche l’adverbe de temps : jetzt, jeden…, morgen.","type":"categories","categories":[{"id":"c0","texte":"Moment présent"},{"id":"c1","texte":"Habitude"},{"id":"c2","texte":"Avenir proche"}],"items":[{"id":"i0","texte":"Er schläft jetzt."},{"id":"i1","texte":"Jeden Samstag laufe ich im Park."},{"id":"i2","texte":"Morgen fahre ich nach Berlin."},{"id":"i3","texte":"Nächste Woche kommt Paul."},{"id":"i4","texte":"Montags spielt sie Tennis."},{"id":"i5","texte":"Ich lese gerade ein Buch."}]},{"enonce":"Complète : « Tu dors longtemps et il mange beaucoup. »","aide":"Schlafen : a → ä à du. Essen : e → i à er.","type":"trous","segments":["Du ",0," (schlafen) lange, und er ",1," (essen) viel."],"banque":["schläft","isst","esst","schläfst"]},{"enonce":"Comment dit-on « Je travaille ici depuis deux ans » ?","aide":"Avec seit, l’allemand garde le temps du moment présent.","type":"choix","options":[{"id":"a","texte":"Ich arbeitete seit zwei Jahren hier"},{"id":"b","texte":"Ich arbeite seit zwei Jahren hier"},{"id":"c","texte":"Ich habe seit zwei Jahren hier gearbeitet"},{"id":"d","texte":"Ich werde seit zwei Jahren hier arbeiten"}],"multiple":false},{"enonce":"Remets en ordre : « Demain, il va à Berlin (en voiture). » La phrase commence par Morgen.","aide":"Le complément de temps ouvre la phrase : le verbe vient ensuite, puis le sujet.","type":"ordre","items":[{"id":"a","texte":"er"},{"id":"b","texte":"Morgen"},{"id":"c","texte":"fährt"},{"id":"d","texte":"nach Berlin"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m9"]},"explication":"**seit** + datif : une action commencée dans le passé et qui continue. Le verbe reste **au présent**."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c2","i3":"c2","i4":"c1","i5":"c0"}},"explication":"Un même présent dit trois choses : **le moment** (*jetzt, gerade*), **l’habitude** (*jeden Samstag, montags*) et **l’avenir proche** (*morgen, nächste Woche*)."},{"cle":{"type":"trous","trous":[["schlafst"],["isst"]]},"affichage":"schläfst · isst","explication":"**Du schläfst lange, und er isst viel.** *schlafen* : a → ä ; *essen* : e → i à la 3e personne."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Ich arbeite seit zwei Jahren hier.** *seit* + présent pour une action commencée dans le passé qui dure encore."},{"cle":{"type":"ordre","ids":["b","c","a","d"]},"explication":"**Morgen fährt er nach Berlin.** Le présent suffit pour dire l’avenir ; *fahren* change de voyelle à *er* (a → ä)."}]$ex$::jsonb),
  ('8cae8614-321f-5290-bd1f-f11f5b8e14d2'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les affaires du vide-grenier","competence":"manier-langue","situation":"Samedi, le quartier de Hannah organise un vide-grenier. Une affiche annonce ce qu’on y trouvera, et Hannah veut repérer les pluriels.","documents":[{"id":"flohmarkt","type":"texte","genre":"article","titre":"Flohmarkt am Samstag","blocs":["Bei uns gibt es Bücher, Lampen, Stühle und Autos für Kinder. Kommt vorbei!"],"source":"Affiche écrite pour l’exercice"}],"questions":[{"enonce":"Touche le seul pluriel qui se termine par -s : c’est un mot emprunté.","aide":"Les mots empruntés prennent un -s ; les autres pluriels de l’affiche n’en ont pas.","type":"zone","document":"flohmarkt","multiple":false},{"enonce":"Associe chaque nom au singulier au pluriel qui figure sur l’affiche.","aide":"Retrouve le mot dans le texte et regarde sa terminaison.","type":"association","gauche":[{"id":"g0","texte":"das Buch"},{"id":"g1","texte":"die Lampe"},{"id":"g2","texte":"der Stuhl"},{"id":"g3","texte":"das Auto"}],"droite":[{"id":"d0","texte":"die Stühle"},{"id":"d1","texte":"die Autos"},{"id":"d2","texte":"die Lampen"},{"id":"d3","texte":"die Bücher"}]},{"enonce":"Complète : « Anna achète deux journaux. »","aide":"Presque tous les féminins prennent -n ou -en, sans inflexion.","type":"trous","segments":["Anna kauft zwei ",0,"."],"banque":["Zeitungen","Zeitunge","Zeitungs","Zeitüngen"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8"]},"explication":"**Autos** : *das Auto → die Autos*. Les mots d’emprunt et les abréviations font leur pluriel en **-s**, sans inflexion."},{"cle":{"type":"association","paires":{"g2":"d0","g3":"d1","g1":"d2","g0":"d3"}},"explication":"Quatre schémas : *das Buch → die Bücher* (-er), *die Lampe → die Lampen* (-n), *der Stuhl → die Stühle* (-e) et *das Auto → die Autos* (-s)."},{"cle":{"type":"trous","trous":[["zeitungen"]]},"affichage":"Zeitungen","explication":"**Anna kauft zwei Zeitungen.** *Zeitung* est féminin : la quasi-totalité des féminins font leur pluriel en **-(e)n**, jamais d’Umlaut."}]$ex$::jsonb),
  ('8cae8614-321f-5290-bd1f-f11f5b8e14d2'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Mit den Freunden unterwegs","competence":"manier-langue","situation":"Lea demande à Tim ce qu’il fait samedi. Dans leurs messages, regarde ce qui arrive aux noms quand ils sont au datif pluriel.","documents":[{"id":"sms1","type":"dialogue","modele":"sms","titre":"Am Samstag","participants":[{"nom":"Lea","emoji":"👧","cote":"gauche"},{"nom":"Tim","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lea","texte":"Was machst du am Samstag?"},{"qui":"Tim","texte":"Ich fahre mit meinen Freunden in die Stadt."},{"qui":"Lea","texte":"Fahrt ihr mit den Autos oder mit den Zügen?"},{"qui":"Tim","texte":"Mit den Zügen. Nach dem Kino laufen wir zu Fuß."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les deux noms qui ont pris un -n au datif pluriel.","aide":"Compare avec le pluriel de base : *die Freunde*, *die Züge*.","type":"zone","document":"sms1","multiple":true},{"enonce":"Touche le seul nom au datif pluriel qui n’a pas pris de -n.","aide":"Regarde comment se termine son pluriel.","type":"zone","document":"sms1","multiple":false},{"enonce":"Complète : « Tim joue avec les enfants. »","aide":"Le pluriel est *Kinder*. Il se termine par -r, pas par -n.","type":"trous","segments":["Tim spielt mit den ",0,"."],"banque":["Kinders","Kindern","Kinden","Kinder"]},{"enonce":"Associe chaque nom au singulier à sa forme au datif pluriel.","aide":"Passe d’abord au pluriel, puis ajoute -n, sauf si le pluriel finit par -s.","type":"association","gauche":[{"id":"g0","texte":"der Zug"},{"id":"g1","texte":"das Haus"},{"id":"g2","texte":"die Stadt"},{"id":"g3","texte":"das Hotel"}],"droite":[{"id":"d0","texte":"den Häusern"},{"id":"d1","texte":"den Städten"},{"id":"d2","texte":"den Hotels"},{"id":"d3","texte":"den Zügen"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m9","m21"]},"explication":"**Freunden** et **Zügen** : au datif pluriel, le nom prend un **-n** s’il n’en a pas déjà un (*die Freunde → mit den Freunden*)."},{"cle":{"type":"zone","ids":["m17"]},"explication":"**Autos** : le pluriel finit déjà par un **-s**, et on n’ajoute pas de -n après un -s (*mit den Autos*)."},{"cle":{"type":"trous","trous":[["kindern"]]},"affichage":"Kindern","explication":"**Tim spielt mit den Kindern.** *die Kinder* se termine par -r, donc le datif pluriel ajoute **-n**."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"*die Züge → den Zügen*, *die Häuser → den Häusern*, *die Städte → den Städten* : -n ajouté. *die Hotels → den Hotels* : après -s, rien."}]$ex$::jsonb),
  ('8cae8614-321f-5290-bd1f-f11f5b8e14d2'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Un courriel et un tableau à compléter","competence":"manier-langue","situation":"Hannah écrit à Lara après une journée en ville. Son courriel contient deux noms qui ne se comportent pas comme les autres ; un tableau l’aide à trier les pluriels.","documents":[{"id":"mail1","type":"texte","genre":"lettre","titre":"Hallo Lara","blocs":["Heute war ich in der Stadt. Ich habe eine neue Brille gekauft und etwas Obst. Es waren viele Leute da, und die Polizei hat die Straße gesperrt."],"source":"Courriel écrit pour l’exercice"},{"id":"tab1","type":"tableau","titre":"Pluriel et datif pluriel","colonnes":["Singulier","Pluriel","Datif pluriel"],"lignes":[["der Lehrer","die Lehrer","?"],["die Lehrerin","?","?"],["das Auto","die Autos","?"],["das Kind","die Kinder","den Kindern"]],"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche le nom qui n’existe qu’au pluriel.","aide":"Il se traduit par « les gens ».","type":"zone","document":"mail1","multiple":false},{"enonce":"Touche le nom singulier que le français traduit par un pluriel (« des lunettes »).","aide":"Il est précédé de *eine*.","type":"zone","document":"mail1","multiple":false},{"enonce":"Complète la ligne *der Lehrer* du tableau : « avec les professeurs ».","aide":"Le pluriel *die Lehrer* ne finit pas par -n.","type":"trous","segments":["mit den ",0],"banque":["Lehreren","Lehrers","Lehrern","Lehrer"]},{"enonce":"Complète la ligne *die Lehrerin* : le pluriel, puis le datif pluriel.","aide":"Les féminins en -in doublent le n au pluriel.","type":"trous","segments":["die ",0," → mit den ",1],"banque":["Lehrerinen","Lehrerins","Lehrerin","Lehrerinnen"]},{"enonce":"Pourquoi écrit-on « mit den Autos » sans -n ?","aide":"Regarde la dernière lettre de *Autos*.","type":"choix","options":[{"id":"a","texte":"Le pluriel finit déjà par -s : on n’ajoute rien"},{"id":"b","texte":"Un mot emprunté n’a pas de datif pluriel"},{"id":"c","texte":"Le -n ne s’ajoute qu’après un pluriel en -er"},{"id":"d","texte":"Auto est neutre, donc jamais de -n au datif"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m18"]},"explication":"**Leute** : *die Leute* n’a pas de singulier."},{"cle":{"type":"zone","ids":["m10"]},"explication":"**Brille** : l’allemand dit *eine Brille* (au singulier) là où le français dit « des lunettes »."},{"cle":{"type":"trous","trous":[["lehrern"]]},"affichage":"Lehrern","explication":"**mit den Lehrern** : *die Lehrer* ne se termine ni par -n ni par -s, donc on ajoute **-n** au datif pluriel."},{"cle":{"type":"trous","trous":[["lehrerinnen"],["lehrerinnen"]]},"affichage":"Lehrerinnen · Lehrerinnen","explication":"**die Lehrerinnen → mit den Lehrerinnen**. Les féminins en *-in* doublent le *n* et prennent -en ; le pluriel finit déjà par -n, donc rien ne s’ajoute au datif."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Le pluriel finit déjà par -s.** C’est la seule exception à la règle du -n au datif pluriel : *mit den Autos*."}]$ex$::jsonb),
  ('890d4c78-95a3-54aa-a1ea-179146d5a587'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un courriel pour Frau Weber","competence":"manier-langue","situation":"Mia écrit à sa professeure d’allemand pour lui proposer une sortie. Relis son courriel et observe ses majuscules.","documents":[{"id":"mail","type":"texte","genre":"lettre","titre":"Die E-Mail von Mia","blocs":["Sehr geehrte Frau Weber,","ich möchte Sie fragen, ob Sie am Freitag Zeit haben. Meine Freunde kommen auch, sie sind sehr nett.","Mit freundlichen Grüßen\nMia Keller"],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux mots du courriel qui sont le « vous » de politesse.","aide":"Cherche le mot écrit avec une majuscule au milieu de la phrase, alors qu’il n’est pas un nom.","type":"zone","document":"mail","multiple":true},{"enonce":"Pourquoi Mia écrit-elle « Sie » avec un S majuscule dans « ob Sie am Freitag Zeit haben » ?","aide":"Regarde à qui Mia s’adresse : elle vouvoie sa professeure.","type":"choix","options":[{"id":"a","texte":"C’est un nom propre, comme Mia ou Berlin"},{"id":"b","texte":"C’est un verbe devenu nom, comme das Essen"},{"id":"c","texte":"C’est le « Sie » de politesse, qui prend toujours la majuscule"},{"id":"d","texte":"C’est le premier mot d’une phrase, donc une majuscule"}],"multiple":false},{"enonce":"Que signifie « sie sind sehr nett » dans la dernière phrase du courriel ?","aide":"Le verbe est « sind » et le mot « sie » est écrit avec une minuscule.","type":"choix","options":[{"id":"a","texte":"vous êtes très gentil"},{"id":"b","texte":"elle est très gentille"},{"id":"c","texte":"ils sont très gentils"},{"id":"d","texte":"je suis très gentil"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6","m9"]},"explication":"Les deux **Sie** désignent Frau Weber : le « Sie » de politesse garde toujours sa majuscule, même au milieu d’une phrase."},{"cle":{"type":"choix","ids":["c"]},"explication":"Mia vouvoie Frau Weber : **Sie, Ihnen, Ihr** s’écrivent toujours avec une majuscule quand ils signifient « vous » de politesse."},{"cle":{"type":"choix","ids":["c"]},"explication":"**sie sind** = « ils / elles sont » : minuscule, donc ce n’est pas le « vous » de politesse, et « sind » est une forme de pluriel. Il reprend « meine Freunde »."}]$ex$::jsonb),
  ('890d4c78-95a3-54aa-a1ea-179146d5a587'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Cinq phrases de Lukas à corriger","competence":"manier-langue","situation":"Lukas s’entraîne à écrire en allemand. Sa professeure a relevé cinq de ses phrases : une seule est parfaitement ponctuée.","documents":[{"id":"saetze","type":"tableau","titre":"Fünf Sätze von Lukas","colonnes":["Satz"],"lignes":[["Ich lerne Deutsch um in Berlin zu studieren."],["Er ist arm, aber glücklich."],["Ich weiß dass er kommt."],["Ich lese, und ich schreibe."],["Das Buch das ich lese ist spannend."]],"enteteLignes":false,"source":"Phrases écrites pour l’exercice"}],"questions":[{"enonce":"Touche la seule phrase du tableau qui est correctement ponctuée.","aide":"Cherche la phrase où la virgule est devant « aber » : cette conjonction l’exige.","type":"zone","document":"saetze","multiple":false},{"enonce":"Touche la phrase qui contient une virgule en trop.","aide":"Regarde ce qu’on met devant « und » dans une énumération ou une coordination simple.","type":"zone","document":"saetze","multiple":false},{"enonce":"Combien de virgules faut-il ajouter dans la dernière phrase : « Das Buch das ich lese ist spannend » ?","aide":"La relative « das ich lese » est enchâssée dans la phrase : que faut-il de chaque côté ?","type":"nombre"},{"enonce":"Dans la première phrase, pourquoi faut-il une virgule devant « um in Berlin zu studieren » ?","aide":"Pense aux trois groupes infinitifs à virgule obligatoire : um… zu, ohne… zu, statt… zu.","type":"choix","options":[{"id":"a","texte":"Un groupe introduit par um… zu exige toujours la virgule"},{"id":"b","texte":"Toute phrase allemande doit avoir au moins une virgule"},{"id":"c","texte":"Le verbe studieren est à l’infinitif, comme tout infinitif"},{"id":"d","texte":"Le mot Berlin est un nom propre qui impose une virgule"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c0"]},"explication":"**Er ist arm, aber glücklich.** : la virgule devant *aber* est obligatoire. Les autres phrases oublient une virgule, ou en ajoutent une de trop."},{"cle":{"type":"zone","ids":["r3c0"]},"explication":"**Ich lese, und ich schreibe** : en principe, il n’y a pas de virgule devant *und* ni devant *oder*. On écrit : *Ich lese und ich schreibe.*"},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2","explication":"Une subordonnée enchâssée est encadrée de **deux** virgules : *Das Buch, das ich lese, ist spannend.*"},{"cle":{"type":"choix","ids":["a"]},"explication":"Le groupe **um… zu** (le but) est toujours précédé d’une virgule : *Ich lerne Deutsch, um in Berlin zu studieren.*"}]$ex$::jsonb),
  ('890d4c78-95a3-54aa-a1ea-179146d5a587'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le brouillon de Karl","competence":"manier-langue","situation":"Karl a écrit à toute vitesse, sans aucune virgule. Il cite aussi son frère à la française. Aide-le à remettre de l’ordre.","documents":[{"id":"brouillon","type":"texte","genre":"lettre","titre":"Karls Entwurf","blocs":["Mein Bruder sagt dass ich Deutsch lerne um in Wien zu studieren aber ich weiß nicht ob ich das schaffe"],"source":"Brouillon écrit pour l’exercice"},{"id":"zitat","type":"dialogue","modele":"sms","titre":"Karl und Lea","participants":[{"nom":"Lea","emoji":"👧","cote":"gauche"},{"nom":"Karl","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lea","texte":"Was sagt dein Bruder?"},{"qui":"Karl","texte":"Er sagt, “Ich komme morgen.”"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Combien de virgules faut-il dans le brouillon de Karl pour qu’il soit correctement ponctué ?","aide":"Une virgule devant la subordonnée en « dass », une devant « um… zu », une devant « aber » et une devant la subordonnée en « ob ».","type":"nombre"},{"enonce":"Touche le mot du brouillon qui s’écrit avec ss, parce que la voyelle qui précède est brève.","aide":"Un seul mot du texte s’écrit « ss » ; celui avec « ß » est un leurre.","type":"zone","document":"brouillon","multiple":false},{"enonce":"Associe chaque mot à la règle d’écriture qui explique son orthographe.","aide":"Prononce chaque mot : la voyelle est-elle brève, longue ou une diphtongue ?","type":"association","gauche":[{"id":"g0","texte":"der Fluss"},{"id":"g1","texte":"die Straße"},{"id":"g2","texte":"heißen"}],"droite":[{"id":"d0","texte":"ss après une voyelle brève"},{"id":"d1","texte":"ß après une diphtongue"},{"id":"d2","texte":"ß après une voyelle longue"}]},{"enonce":"Karl cite son frère à la française dans le message à Lea. Quelle correction apporter ?","aide":"En allemand, on annonce le discours direct par des deux-points et on ouvre les guillemets en bas.","type":"choix","options":[{"id":"a","texte":"Supprimer les guillemets et garder simplement la virgule"},{"id":"b","texte":"Deux-points, puis guillemets bas à l’ouverture et haut à la fermeture"},{"id":"c","texte":"Un point-virgule à la place de la virgule, guillemets inchangés"},{"id":"d","texte":"Guillemets français « » avec espaces, la virgule étant conservée"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4","explication":"Quatre virgules : *Mein Bruder sagt, dass ich Deutsch lerne, um in Wien zu studieren, aber ich weiß nicht, ob ich das schaffe.* (devant dass, um, aber et ob)."},{"cle":{"type":"zone","ids":["m3"]},"explication":"**dass** s’écrit avec *ss* : la voyelle *a* est brève. À l’inverse, *weiß* prend ß (voyelle longue ou diphtongue)."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"**Fluss** : voyelle brève, donc *ss*. **Straße** : voyelle longue, donc *ß*. **heißen** : diphtongue *ei*, donc *ß*."},{"cle":{"type":"choix","ids":["b"]},"explication":"On écrit : *Er sagt: „Ich komme morgen.“* — **deux-points** avant la citation, guillemets **en bas** à l’ouverture et **en haut** à la fermeture."}]$ex$::jsonb),
  ('41574001-1a64-565f-b3f3-6308e6006bfa'::uuid, 1, 1, 5, 20, 3,
