  ('41574001-1a64-565f-b3f3-6308e6006bfa'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Qui donne quoi à qui ?","competence":"manier-langue","situation":"Lena, Tom et leurs amis s’échangent des cadeaux. Leurs pronoms compléments se placent juste après le verbe.","documents":[{"id":"geschenk2","type":"dialogue","modele":"sms","titre":"Geschenke","participants":[{"nom":"Lena","emoji":"👧","cote":"gauche"},{"nom":"Tom","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lena","texte":"Hast du Julias Geschenk?"},{"qui":"Tom","texte":"Ja, ich gebe es ihr morgen."},{"qui":"Lena","texte":"Und Max und Tim? Ich schenke ihnen die Karten."},{"qui":"Tom","texte":"Ich besuche sie am Wochenende."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le pronom au datif qui désigne Julia.","aide":"Julia est féminin ; le datif de « sie » (elle) est différent de l’accusatif.","type":"zone","document":"geschenk2","multiple":false},{"enonce":"Remets en ordre : « Je te le donne demain. » La phrase commence par Ich gebe.","aide":"Deux pronoms : accusatif d’abord, datif ensuite, puis le complément de temps.","type":"ordre","items":[{"id":"a","texte":"dir"},{"id":"b","texte":"morgen"},{"id":"c","texte":"es"}]},{"enonce":"Touche le pronom à l’accusatif pluriel que Tom emploie pour Max et Tim.","aide":"Au pluriel, nominatif et accusatif sont identiques.","type":"zone","document":"geschenk2","multiple":false},{"enonce":"Complète : « Je leur offre les cartes. » (à Max et à Tim)","aide":"Le datif pluriel est la forme de la 3e personne en -en.","type":"trous","segments":["Ich schenke ",0," die Karten."],"banque":["sie","Ihnen","ihnen","ihr"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8"]},"explication":"**ihr** : datif féminin singulier. L’accusatif *es* (le cadeau) passe devant lui."},{"cle":{"type":"ordre","ids":["c","a","b"]},"explication":"**Ich gebe es dir morgen.** Deux pronoms compléments : l’accusatif passe devant le datif, juste après le verbe."},{"cle":{"type":"zone","ids":["m21"]},"explication":"**sie** : accusatif pluriel, « les ». Écrit avec une minuscule, ce n’est pas le *Sie* de politesse."},{"cle":{"type":"trous","trous":[["ihnen"]]},"affichage":"ihnen","explication":"**ihnen** : datif pluriel de *sie* (« à eux, à elles »)."}]$ex$::jsonb),
  ('41574001-1a64-565f-b3f3-6308e6006bfa'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Une lettre à Herr Schmidt","competence":"raisonner","situation":"Une élève écrit à son professeur de musique. Sa lettre mélange le « vous » de politesse, un « sie » pluriel et le petit mot es.","documents":[{"id":"brief2","type":"texte","genre":"lettre","titre":"Ein Brief an Herrn Schmidt","blocs":["Sehr geehrter Herr Schmidt,","ich schreibe Ihnen, weil ich den Kurs besuchen möchte. Können Sie mir bitte sagen, wann er beginnt? Meine Freundinnen kommen auch. Ich kenne sie seit der Schule, und ich helfe ihnen oft. Es regnet, aber das ist nicht wichtig."],"source":"Lettre écrite pour l’exercice"}],"questions":[{"enonce":"Touche les deux pronoms de politesse du courrier.","aide":"Ils s’écrivent avec une majuscule au milieu de la phrase.","type":"zone","document":"brief2","multiple":true},{"enonce":"Touche le « es » qui est un sujet apparent (il ne remplace aucun nom).","aide":"Il s’agit d’un verbe météo.","type":"zone","document":"brief2","multiple":false},{"enonce":"À qui renvoie « ihnen » (en minuscule) dans « ich helfe ihnen oft » ?","aide":"La majuscule manque : ce n’est pas le « vous » de politesse.","type":"choix","options":[{"id":"a","texte":"À Herr Schmidt, vouvoyé"},{"id":"b","texte":"À moi-même, 1re personne"},{"id":"c","texte":"À la pluie, sujet apparent"},{"id":"d","texte":"À mes amies, au datif pluriel"}],"multiple":false},{"enonce":"Associe chaque forme à sa fonction.","aide":"Regarde la majuscule, puis le cas.","type":"association","gauche":[{"id":"g0","texte":"Ich schreibe Ihnen"},{"id":"g1","texte":"Ich helfe ihnen"},{"id":"g2","texte":"Ich kenne sie"},{"id":"g3","texte":"Können Sie mir helfen ?"}],"droite":[{"id":"d0","texte":"datif pluriel (à eux, à elles)"},{"id":"d1","texte":"nominatif de politesse (vous)"},{"id":"d2","texte":"datif de politesse (à vous)"},{"id":"d3","texte":"accusatif pluriel (les)"}]}]}$ex$::jsonb,
